-- Provision three isolated application schemas in the shared non-production project.
-- Production is intentionally not referenced or modified.
do $provision$
declare
  lane text;
  template constant text := $lane_template$
create schema __LANE__;
revoke all on schema __LANE__ from public;
grant usage on schema __LANE__ to anon, authenticated, service_role;

-- Replayed from supabase/migrations/20260809235600_identity_and_rosters.sql
create extension if not exists pgcrypto;

create schema if not exists __LANE___private;
revoke all on schema __LANE___private from public;
grant usage on schema __LANE___private to authenticated;

create table __LANE__.players (
  id uuid primary key default gen_random_uuid(),
  user_id uuid unique references auth.users(id) on delete set null,
  display_name text not null check (char_length(display_name) between 1 and 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table __LANE__.player_ratings (
  player_id uuid primary key references __LANE__.players(id) on delete cascade,
  fargo_rating integer check (fargo_rating between 0 and 1000),
  rating_status text not null default 'unverified'
    check (rating_status in ('unverified', 'provisional', 'established')),
  updated_at timestamptz not null default now()
);

create table __LANE__.seasons (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  status text not null default 'draft'
    check (status in ('draft', 'registration', 'active', 'playoffs', 'complete')),
  roster_lock_round integer,
  opening_block_length integer not null default 3 check (opening_block_length > 0),
  individual_min_matches integer not null default 5 check (individual_min_matches > 0),
  created_at timestamptz not null default now()
);

create table __LANE__.teams (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references __LANE__.seasons(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 80),
  created_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  unique (season_id, name),
  unique (id, season_id)
);

create table __LANE__.team_memberships (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references __LANE__.seasons(id) on delete cascade,
  team_id uuid not null,
  player_id uuid not null references __LANE__.players(id) on delete cascade,
  role text not null default 'player' check (role in ('player', 'captain')),
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  check (ends_at is null or ends_at >= starts_at),
  foreign key (team_id, season_id)
    references __LANE__.teams(id, season_id)
    on delete cascade
);

create unique index one_active_team_membership_per_season
  on __LANE__.team_memberships (season_id, player_id)
  where ends_at is null;

create index team_memberships_team_active_idx
  on __LANE__.team_memberships (team_id, ends_at);

create or replace function __LANE___private.current_player_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.id
  from __LANE__.players p
  where p.user_id = (select auth.uid())
  limit 1;
$$;

create or replace function __LANE___private.is_team_captain(target_team_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from __LANE__.team_memberships tm
    join __LANE__.players p on p.id = tm.player_id
    where tm.team_id = target_team_id
      and tm.role = 'captain'
      and tm.ends_at is null
      and p.user_id = (select auth.uid())
  );
$$;

revoke all on function __LANE___private.current_player_id() from public;
revoke all on function __LANE___private.is_team_captain(uuid) from public;
grant execute on function __LANE___private.current_player_id() to authenticated;
grant execute on function __LANE___private.is_team_captain(uuid) to authenticated;

alter table __LANE__.players enable row level security;
alter table __LANE__.player_ratings enable row level security;
alter table __LANE__.seasons enable row level security;
alter table __LANE__.teams enable row level security;
alter table __LANE__.team_memberships enable row level security;

grant select on __LANE__.players, __LANE__.player_ratings, __LANE__.seasons, __LANE__.teams, __LANE__.team_memberships to anon, authenticated;
grant insert (user_id, display_name) on __LANE__.players to authenticated;
grant update (display_name) on __LANE__.players to authenticated;
grant insert (season_id, name, created_by) on __LANE__.teams to authenticated;
grant insert (season_id, team_id, player_id, role) on __LANE__.team_memberships to authenticated;
grant all on __LANE__.players, __LANE__.player_ratings, __LANE__.seasons, __LANE__.teams, __LANE__.team_memberships to service_role;

create policy "Players are publicly readable"
on __LANE__.players for select
to anon, authenticated
using (true);

create policy "Users create their own player profile"
on __LANE__.players for insert
to authenticated
with check ((select auth.uid()) is not null and (select auth.uid()) = user_id);

create policy "Users update their own player profile"
on __LANE__.players for update
to authenticated
using ((select auth.uid()) is not null and (select auth.uid()) = user_id)
with check ((select auth.uid()) is not null and (select auth.uid()) = user_id);

create policy "Ratings are publicly readable"
on __LANE__.player_ratings for select
to anon, authenticated
using (true);

create policy "Seasons are publicly readable"
on __LANE__.seasons for select
to anon, authenticated
using (true);

create policy "Teams are publicly readable"
on __LANE__.teams for select
to anon, authenticated
using (true);

create policy "Authenticated users can create teams"
on __LANE__.teams for insert
to authenticated
with check ((select auth.uid()) is not null and (select auth.uid()) = created_by);

create policy "Memberships are publicly readable"
on __LANE__.team_memberships for select
to anon, authenticated
using (true);

create policy "Team creator can bootstrap own captain membership"
on __LANE__.team_memberships for insert
to authenticated
with check (
  role = 'captain'
  and player_id = (select __LANE___private.current_player_id())
  and exists (
    select 1
    from __LANE__.teams t
    where t.id = team_id
      and t.season_id = season_id
      and t.created_by = (select auth.uid())
  )
);

comment on table __LANE__.player_ratings is
  'Ratings are public read-only to browser roles; trusted server/service-role operations own rating changes.';

comment on table __LANE__.team_memberships is
  'Membership history is time-bounded. Normal invite, trade, removal, and roster exception writes go through trusted server commands.';


-- Replayed from supabase/migrations/20260810001500_authorization_contracts.sql
create table __LANE___private.league_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  granted_at timestamptz not null default now(),
  granted_by uuid references auth.users(id) on delete set null,
  note text
);

create table __LANE___private.player_contacts (
  player_id uuid primary key references __LANE__.players(id) on delete cascade,
  email text,
  phone text,
  updated_at timestamptz not null default now()
);

create table __LANE___private.payment_status (
  season_id uuid not null references __LANE__.seasons(id) on delete cascade,
  player_id uuid not null references __LANE__.players(id) on delete cascade,
  status text not null default 'unpaid'
    check (status in ('unpaid', 'partial', 'paid', 'waived')),
  amount_due_cents integer not null default 0 check (amount_due_cents >= 0),
  amount_paid_cents integer not null default 0 check (amount_paid_cents >= 0),
  updated_at timestamptz not null default now(),
  primary key (season_id, player_id)
);

revoke all on table __LANE___private.league_admins from public, anon, authenticated;
revoke all on table __LANE___private.player_contacts from public, anon, authenticated;
revoke all on table __LANE___private.payment_status from public, anon, authenticated;
grant all on table __LANE___private.league_admins, __LANE___private.player_contacts, __LANE___private.payment_status to service_role;

create or replace function __LANE___private.is_league_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = (select auth.uid())
  );
$$;

create or replace function __LANE___private.active_team_roster_count(target_team_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
  from __LANE__.team_memberships tm
  where tm.team_id = target_team_id
    and tm.ends_at is null;
$$;

revoke all on function __LANE___private.is_league_admin() from public;
revoke all on function __LANE___private.active_team_roster_count(uuid) from public;
grant execute on function __LANE___private.is_league_admin() to authenticated;
grant execute on function __LANE___private.active_team_roster_count(uuid) to authenticated;

grant update (ends_at) on __LANE__.team_memberships to authenticated;

create policy "Captains can add roster players to own team"
on __LANE__.team_memberships for insert
to authenticated
with check (
  role = 'player'
  and (select __LANE___private.is_team_captain(team_id))
  and (select __LANE___private.active_team_roster_count(team_id)) < 4
);

create policy "Captains can end roster player memberships on own team"
on __LANE__.team_memberships for update
to authenticated
using (
  role = 'player'
  and ends_at is null
  and (select __LANE___private.is_team_captain(team_id))
)
with check (
  role = 'player'
  and ends_at is not null
  and (select __LANE___private.is_team_captain(team_id))
);

comment on table __LANE___private.league_admins is
  'Private league-admin authority list. Trusted Worker commands use this role; browser roles cannot read or mutate it.';

comment on table __LANE___private.player_contacts is
  'Private player contact details. Public profile data stays in __LANE__.players.';

comment on table __LANE___private.payment_status is
  'Private per-player payment status. Aggregate prize and purse data belongs in public read models.';

comment on function __LANE___private.is_league_admin() is
  'Returns whether the authenticated Supabase user has league-admin authority.';


-- Replayed from supabase/migrations/20260810003000_schedule_publication.sql
create table __LANE__.rounds (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references __LANE__.seasons(id) on delete cascade,
  round_number integer not null check (round_number > 0),
  stage text not null default 'regular'
    check (stage in ('regular', 'semifinal', 'championship', 'tiebreaker')),
  scheduled_on date,
  status text not null default 'scheduled'
    check (status in ('scheduled', 'in_progress', 'finalized', 'corrected')),
  created_at timestamptz not null default now(),
  unique (season_id, stage, round_number),
  unique (id, season_id)
);

create table __LANE__.team_matches (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null,
  round_id uuid not null,
  table_number integer not null check (table_number > 0),
  team_a_id uuid not null,
  team_b_id uuid not null,
  status text not null default 'scheduled'
    check (status in ('scheduled', 'lineups_due', 'in_progress', 'finalized', 'corrected')),
  winner_team_id uuid,
  created_at timestamptz not null default now(),
  check (team_a_id <> team_b_id),
  foreign key (round_id, season_id)
    references __LANE__.rounds(id, season_id)
    on delete cascade,
  foreign key (team_a_id, season_id)
    references __LANE__.teams(id, season_id)
    on delete cascade,
  foreign key (team_b_id, season_id)
    references __LANE__.teams(id, season_id)
    on delete cascade,
  foreign key (winner_team_id, season_id)
    references __LANE__.teams(id, season_id)
    on delete set null,
  unique (round_id, table_number)
);

create unique index team_matches_unique_pair_per_round
  on __LANE__.team_matches (round_id, least(team_a_id, team_b_id), greatest(team_a_id, team_b_id));

alter table __LANE__.rounds enable row level security;
alter table __LANE__.team_matches enable row level security;

grant select on __LANE__.rounds, __LANE__.team_matches to anon, authenticated;
grant all on __LANE__.rounds, __LANE__.team_matches to service_role;

create policy "Rounds are publicly readable"
on __LANE__.rounds for select
to anon, authenticated
using (true);

create policy "Team matches are publicly readable"
on __LANE__.team_matches for select
to anon, authenticated
using (true);

comment on table __LANE__.rounds is
  'Published regular-season and postseason rounds. Browser roles can read; trusted Worker commands publish or correct.';

comment on table __LANE__.team_matches is
  'Team pairings for a round with table assignment. Player match generation happens from submitted lineups.';


