  if response_status = 'accepted' then
    select count(*)::integer
      into active_roster_count
    from __LANE__.team_memberships tm
    where tm.team_id = invitation.team_id
      and tm.ends_at is null;

    if active_roster_count >= 4 then
      raise exception 'Team roster has no open primary spots';
    end if;

    insert into __LANE__.team_memberships (
      season_id,
      team_id,
      player_id,
      role
    ) values (
      invitation.season_id,
      invitation.team_id,
      invitation.invited_player_id,
      'player'
    );
  end if;

  update __LANE___private.team_invitations
  set status = response_status,
      responded_at = now()
  where id = target_invitation_id;

  return query
  select
    ti.id,
    ti.season_id,
    ti.team_id,
    ti.invited_player_id,
    ti.status,
    ti.responded_at
  from __LANE___private.team_invitations ti
  where ti.id = target_invitation_id;
end;
$$;

