      1 as sort_order,
      sp.season_id,
      fa.round_id,
      target_team_id as team_id,
      p.id as player_id,
      p.display_name,
      null::text as role,
      'free_agent'::text as participation_type,
      pr.fargo_rating,
      pr.rating_status,
      fa.status as availability_status,
      fa.updated_at
    from __LANE___private.free_agent_availability fa
    join __LANE__.season_players sp
      on sp.season_id = fa.season_id
     and sp.player_id = fa.player_id
    join __LANE__.players p
      on p.id = sp.player_id
    left join __LANE__.player_ratings pr
      on pr.player_id = sp.player_id
