set search_path = ''
as $$
declare
  rating_a __LANE__.player_ratings%rowtype;
  rating_b __LANE__.player_ratings%rowtype;
  rating_band __LANE__.season_race_chart_bands%rowtype;
  match_season __LANE__.seasons%rowtype;
begin
  select *
    into rating_a
  from __LANE__.player_ratings pr
  where pr.player_id = new.player_a_id;

  select *
    into rating_b
  from __LANE__.player_ratings pr
  where pr.player_id = new.player_b_id;

