    tl.id as lineup_id,
    tl.season_id,
    tl.round_id,
    tl.team_match_id,
    tl.team_id,
    tl.team_id = target_team_id as is_own_team,
    opponent_visible as opponent_lineup_visible,
    tls.slot_number,
