        updated_at = now()
    where seasons.id = target_season_id
    returning seasons.id into configured_id;
  end if;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  )
