    raise exception 'Trade not found';
  end if;

  if trade.status <> 'pending' then
    raise exception 'Trade is no longer pending';
  end if;

  select p.id
    into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;

  if actor_player_id is null
