  amount_paid_cents integer
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    sp.season_id,
    sp.player_id,
    sp.participation_type,
    sp.status,
    sp.created_at,
    coalesce(ps.status, 'unpaid'::text),
    coalesce(ps.amount_due_cents, 0),
