create or replace function __LANE__.get_own_team_membership_requests(actor_user_id uuid)
returns table (
  player_requests jsonb,
  captain_requests jsonb
)
language sql
stable
security definer
set search_path = ''
as $$
with actor_player as (
  select p.id
  from __LANE__.players p
  where p.user_id = actor_user_id
  limit 1
),
player_rows as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'requestId', r.id,
    'seasonId', r.season_id,
    'seasonName', s.name,
    'teamId', r.team_id,
    'teamName', t.name,
    'status', r.status,
    'createdAt', r.created_at,
    'resolvedAt', r.resolved_at
  ) order by r.created_at desc), '[]'::jsonb) as rows
  from actor_player ap
  join __LANE___private.team_membership_requests r on r.player_id = ap.id
  join __LANE__.teams t on t.id = r.team_id and t.season_id = r.season_id
  join __LANE__.seasons s on s.id = r.season_id
),
captain_team_ids as (
  select tm.team_id, tm.season_id
  from actor_player ap
  join __LANE__.team_memberships tm on tm.player_id = ap.id
  where tm.role = 'captain' and tm.ends_at is null
),
captain_rows as (
  select coalesce(jsonb_agg(jsonb_build_object(
    'requestId', r.id,
    'seasonId', r.season_id,
    'seasonName', s.name,
    'teamId', r.team_id,
    'teamName', t.name,
    'playerId', p.id,
    'displayName', p.display_name,
    'status', r.status,
    'createdAt', r.created_at
  ) order by r.created_at), '[]'::jsonb) as rows
  from captain_team_ids c
  join __LANE___private.team_membership_requests r
    on r.team_id = c.team_id and r.season_id = c.season_id and r.status = 'pending'
  join __LANE__.teams t on t.id = r.team_id and t.season_id = r.season_id
  join __LANE__.seasons s on s.id = r.season_id
  join __LANE__.players p on p.id = r.player_id
)
select player_rows.rows, captain_rows.rows
from player_rows cross join captain_rows;
$$;

