create or replace function __LANE___private.expire_season_team_registration(target_season_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update __LANE___private.season_team_slots sts
  set status = 'expired',
      resolved_at = now(),
      updated_at = now(),
      last_action_reason = coalesce(sts.last_action_reason, 'Reservation deadline passed')
  where sts.season_id = target_season_id
    and sts.status in ('reserved', 'transferred')
    and sts.reservation_expires_at is not null
    and sts.reservation_expires_at <= now();

  with expired_holds as (
    update __LANE___private.season_team_slots sts
    set status = 'expired',
        resolved_at = now(),
        updated_at = now(),
        last_action_reason = coalesce(sts.last_action_reason, 'Roster completion deadline passed')
    from __LANE__.seasons s
    where sts.season_id = target_season_id
      and s.id = sts.season_id
      and sts.status in ('approved_pending_roster', 'ready')
      and sts.hold_expires_at is not null
      and sts.hold_expires_at <= now()
      and __LANE___private.committed_team_roster_count(sts.team_id, sts.season_id)
          < s.minimum_committed_roster
    returning sts.id
  )
  update __LANE___private.team_applications ta
  set status = 'expired',
      updated_at = now(),
      admin_notes = coalesce(ta.admin_notes, 'Roster completion deadline passed')
  where ta.slot_id in (select id from expired_holds)
    and ta.status in ('approved_pending_roster', 'ready');
end;
$$;

create or replace function __LANE___private.refresh_team_slot_readiness(target_team_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  committed_count integer;
  minimum_count integer;
  target_slot_id uuid;
  target_status text;
  target_season_id uuid;
begin
  select sts.id, sts.status, sts.season_id, s.minimum_committed_roster
  into target_slot_id, target_status, target_season_id, minimum_count
  from __LANE___private.season_team_slots sts
  join __LANE__.seasons s on s.id = sts.season_id
  where sts.team_id = target_team_id
  order by sts.created_at desc
  limit 1
  for update of sts;

  if target_slot_id is null or target_status not in ('approved_pending_roster', 'ready') then
    return;
  end if;

  committed_count := __LANE___private.committed_team_roster_count(
    target_team_id,
    target_season_id
  );

  if committed_count >= minimum_count and target_status = 'approved_pending_roster' then
    update __LANE___private.season_team_slots
    set status = 'ready', updated_at = now()
    where id = target_slot_id;

    update __LANE___private.team_applications
    set status = 'ready', updated_at = now()
    where slot_id = target_slot_id
      and status = 'approved_pending_roster';
  elsif committed_count < minimum_count and target_status = 'ready' then
    update __LANE___private.season_team_slots
    set status = 'approved_pending_roster', updated_at = now()
    where id = target_slot_id;

    update __LANE___private.team_applications
    set status = 'approved_pending_roster', updated_at = now()
    where slot_id = target_slot_id
      and status = 'ready';
  end if;
end;
$$;

create or replace function __LANE___private.refresh_team_slots_for_season_player_trigger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  team_row record;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    for team_row in
      select distinct tm.team_id
      from __LANE__.team_memberships tm
      where tm.season_id = old.season_id
        and tm.player_id = old.player_id
    loop
      perform __LANE___private.refresh_team_slot_readiness(team_row.team_id);
    end loop;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    for team_row in
      select distinct tm.team_id
      from __LANE__.team_memberships tm
      where tm.season_id = new.season_id
        and tm.player_id = new.player_id
    loop
      perform __LANE___private.refresh_team_slot_readiness(team_row.team_id);
    end loop;
  end if;

  return coalesce(new, old);
end;
$$;

