  surface text,
  page_path text,
  context jsonb,
  comment text,
  status text,
  created_at timestamptz,
  reviewed_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'League admin access is required';
  end if;
  if status_filter is not null and status_filter not in ('open', 'reviewed') then
    raise exception 'Invalid feedback status';
  end if;
  if result_limit not between 1 and 250 then
    raise exception 'result_limit must be between 1 and 250';
  end if;

  return query
  select sf.id,
         sf.actor_user_id,
         sf.surface,
         sf.page_path,
         sf.context,
         sf.comment,
         sf.status,
         sf.created_at,
         sf.reviewed_at
  from __LANE___private.sandbox_feedback sf
  where status_filter is null or sf.status = status_filter
  order by sf.created_at desc
  limit result_limit;
end;
$$;

create or replace function __LANE__.resolve_sandbox_feedback(
  actor_user_id uuid,
  target_feedback_id uuid
)
returns table(
  id uuid,
  status text,
  reviewed_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'League admin access is required';
  end if;

  update __LANE___private.sandbox_feedback sf
  set status = 'reviewed',
      reviewed_at = now(),
      reviewed_by_user_id = actor_user_id
  where sf.id = target_feedback_id
    and sf.status = 'open';

  if not found then
    raise exception 'Open sandbox feedback not found';
  end if;

  return query
  select sf.id, sf.status, sf.reviewed_at
  from __LANE___private.sandbox_feedback sf
  where sf.id = target_feedback_id;
end;
$$;

