  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_membership_id is null then raise exception 'target_membership_id is required'; end if;

  select * into membership
  from __LANE__.team_memberships tm
  where tm.id = target_membership_id
  for update;
  if not found then raise exception 'Team membership not found'; end if;
  if membership.ends_at is not null then raise exception 'Team membership is already inactive'; end if;
  if membership.role <> 'player' then raise exception 'Captain memberships cannot be removed through this path'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before removing team members'; end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.team_id = membership.team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can remove team members';
  end if;

  ended_at := now();
  update __LANE__.team_memberships
  set ends_at = ended_at
  where team_memberships.id = target_membership_id;

  if not exists (
    select 1
    from __LANE__.team_memberships active_tm
    where active_tm.season_id = membership.season_id
      and active_tm.player_id = membership.player_id
      and active_tm.ends_at is null
  ) then
    update __LANE__.season_players sp
    set participation_type = 'free_agent',
        status = 'active'
    where sp.season_id = membership.season_id
      and sp.player_id = membership.player_id;
  end if;

  insert into __LANE___private.audit_events(
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'team.remove_member',
    'team_membership',
    membership.id,
    to_jsonb(membership),
    jsonb_build_object(
      'id', membership.id,
      'season_id', membership.season_id,
      'team_id', membership.team_id,
      'player_id', membership.player_id,
      'role', membership.role,
      'ends_at', ended_at
    )
  );

  return query
  select tm.id, tm.season_id, tm.team_id, tm.player_id, tm.role, tm.ends_at
  from __LANE__.team_memberships tm
  where tm.id = target_membership_id;
end;
$function$;

-- Repair active participants stranded by the old transition. This changes only
-- current participation metadata; effective-dated membership and match history stay intact.
update __LANE__.season_players sp
set participation_type = 'free_agent'
where sp.status = 'active'
  and sp.participation_type = 'rostered'
  and not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = sp.season_id
      and tm.player_id = sp.player_id
      and tm.ends_at is null
  );


-- Replayed from supabase/migrations/20260811092000_reconcile_war_game_rpc_ambiguities.sql
-- Reconcile PL/pgSQL name collisions found by the live Season 1 War Game.
-- Preserve the current multi-team/team-slot/postseason behavior while making
-- conflict targets and update predicates unambiguous on a fresh migration chain.

create or replace function __LANE__.register_for_season(
  actor_user_id uuid,
  target_season_id uuid,
  registration_participation_type text default 'free_agent'
)
returns table (
  season_id uuid,
  player_id uuid,
  participation_type text,
  registration_status text,
  registered_at timestamptz,
  payment_status text,
  amount_due_cents integer,
  amount_paid_cents integer
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  target_player __LANE__.players%rowtype;
  target_season __LANE__.seasons%rowtype;
  registration __LANE__.season_players%rowtype;
  fee_cents integer;
  has_active_team boolean;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if registration_participation_type not in ('rostered', 'free_agent') then
    raise exception 'participation_type must be rostered or free_agent';
  end if;

  select * into target_player
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before season registration'; end if;

  select * into target_season
  from __LANE__.seasons s
  where s.id = target_season_id;
  if not found then raise exception 'Season not found'; end if;
  if target_season.status <> 'registration' then raise exception 'Season registration is not open'; end if;

  select exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.player_id = target_player.id
      and tm.ends_at is null
  ) into has_active_team;

  if registration_participation_type = 'rostered' and not has_active_team then
    raise exception 'Active team membership is required for rostered registration';
  end if;
  if registration_participation_type = 'free_agent' and has_active_team then
    raise exception 'Rostered players cannot register as free agents for the same season';
  end if;

  insert into __LANE__.season_players(season_id, player_id, participation_type, status)
  values (target_season_id, target_player.id, registration_participation_type, 'active')
  on conflict on constraint season_players_season_id_player_id_key do update
    set participation_type = excluded.participation_type,
        status = 'active'
  returning * into registration;

  select coalesce(spc.entry_fee_cents, 0)
  into fee_cents
  from __LANE__.season_prize_configurations spc
  where spc.season_id = target_season_id
  order by spc.version desc
  limit 1;
  fee_cents := coalesce(fee_cents, 0);

  insert into __LANE___private.payment_status(season_id, player_id, status, amount_due_cents, amount_paid_cents)
  values (target_season_id, target_player.id, 'unpaid', fee_cents, 0)
  on conflict on constraint payment_status_pkey do nothing;

  return query
  select
    registration.season_id,
    registration.player_id,
    registration.participation_type,
    registration.status,
    registration.created_at,
    ps.status,
    ps.amount_due_cents,
    ps.amount_paid_cents
  from __LANE___private.payment_status ps
  where ps.season_id = target_season_id
    and ps.player_id = target_player.id;
end;
$function$;

create or replace function __LANE__.request_team_membership(
  actor_user_id uuid,
  target_team_id uuid
)
returns table (
  id uuid,
  season_id uuid,
  team_id uuid,
  player_id uuid,
  status text,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  request_id uuid;
  pending_invitation_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before requesting a team'; end if;

  select t.season_id into target_season_id
  from __LANE__.teams t
  where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;

  perform __LANE___private.expire_season_team_registration(target_season_id);
  if not exists (
    select 1
    from __LANE___private.season_team_slots sts
    where sts.season_id = target_season_id
      and sts.team_id = target_team_id
      and sts.status in ('approved_pending_roster', 'ready', 'confirmed')
  ) then
    raise exception 'This team is not accepting season roster requests';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.ends_at is null
  ) then
    raise exception 'Player is already an active member of this team';
  end if;

  if exists (
    select 1 from __LANE___private.team_membership_requests r
    where r.season_id = target_season_id
      and r.team_id = target_team_id
      and r.player_id = actor_player_id
      and r.status = 'pending'
  ) then
    raise exception 'Membership request is already pending';
  end if;

  select ti.id into pending_invitation_id
  from __LANE___private.team_invitations ti
  where ti.season_id = target_season_id
    and ti.team_id = target_team_id
    and ti.invited_player_id = actor_player_id
    and ti.status = 'pending'
  order by ti.created_at
  limit 1
  for update;

  if pending_invitation_id is not null then
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(target_season_id, target_team_id, actor_player_id, 'player');

    insert into __LANE___private.team_membership_requests(
      season_id, team_id, player_id, status, resolved_at, resolved_by_user_id
    ) values (
      target_season_id, target_team_id, actor_player_id, 'approved', now(), actor_user_id
    ) returning __LANE___private.team_membership_requests.id into request_id;

    update __LANE___private.team_invitations
    set status = 'accepted', responded_at = now()
    where __LANE___private.team_invitations.id = pending_invitation_id;
  else
    insert into __LANE___private.team_membership_requests(season_id, team_id, player_id)
    values(target_season_id, target_team_id, actor_player_id)
    returning __LANE___private.team_membership_requests.id into request_id;
  end if;

  return query
  select r.id, r.season_id, r.team_id, r.player_id, r.status, r.created_at
  from __LANE___private.team_membership_requests r
  where r.id = request_id;
end;
$function$;

create or replace function __LANE__.respond_to_team_membership_request(
  actor_user_id uuid,
  target_request_id uuid,
  response_status text
)
returns table (
  id uuid,
  season_id uuid,
  team_id uuid,
  player_id uuid,
  status text,
  resolved_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  request_row __LANE___private.team_membership_requests%rowtype;
  actor_player_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_request_id is null then raise exception 'target_request_id is required'; end if;
  if response_status not in ('approved', 'declined') then
    raise exception 'response_status must be approved or declined';
  end if;

  select * into request_row
  from __LANE___private.team_membership_requests r
  where r.id = target_request_id
  for update;
  if not found then raise exception 'Membership request not found'; end if;
  if request_row.status <> 'pending' then raise exception 'Membership request is no longer pending'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = request_row.team_id
      and tm.season_id = request_row.season_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can respond to membership requests';
  end if;

  if response_status = 'approved' then
    if not exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = request_row.season_id
        and tm.team_id = request_row.team_id
        and tm.player_id = request_row.player_id
        and tm.ends_at is null
    ) then
      insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
      values(request_row.season_id, request_row.team_id, request_row.player_id, 'player');
    end if;

    update __LANE___private.team_invitations
    set status = 'accepted', responded_at = now()
    where __LANE___private.team_invitations.season_id = request_row.season_id
      and __LANE___private.team_invitations.team_id = request_row.team_id
      and __LANE___private.team_invitations.invited_player_id = request_row.player_id
      and __LANE___private.team_invitations.status = 'pending';
  end if;

  update __LANE___private.team_membership_requests
  set status = response_status,
      resolved_at = now(),
      resolved_by_user_id = actor_user_id
  where __LANE___private.team_membership_requests.id = target_request_id;

  return query
  select r.id, r.season_id, r.team_id, r.player_id, r.status, r.resolved_at
  from __LANE___private.team_membership_requests r
  where r.id = target_request_id;
end;
$function$;

create or replace function __LANE__.invite_player_to_team(
  actor_user_id uuid,
  target_team_id uuid,
  target_player_id uuid
)
returns table(
  id uuid,
  season_id uuid,
  team_id uuid,
  invited_player_id uuid,
  status text,
  created_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  inserted_invitation_id uuid;
  pending_request_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;

  select t.season_id into target_season_id
  from __LANE__.teams t
  where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before inviting players'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can invite players';
  end if;

  if not exists (select 1 from __LANE__.players p where p.id = target_player_id) then
    raise exception 'Invited player not found';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = target_player_id
      and tm.ends_at is null
  ) then
    raise exception 'Player is already an active member of this team';
  end if;

  select r.id into pending_request_id
  from __LANE___private.team_membership_requests r
  where r.season_id = target_season_id
    and r.team_id = target_team_id
    and r.player_id = target_player_id
    and r.status = 'pending'
  order by r.created_at
  limit 1
  for update;

  insert into __LANE___private.team_invitations(
    season_id, team_id, invited_player_id, invited_by_user_id,
    status, responded_at
  ) values (
    target_season_id, target_team_id, target_player_id, actor_user_id,
    case when pending_request_id is null then 'pending' else 'accepted' end,
    case when pending_request_id is null then null else now() end
  ) returning __LANE___private.team_invitations.id into inserted_invitation_id;

  if pending_request_id is not null then
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(target_season_id, target_team_id, target_player_id, 'player');

    update __LANE___private.team_membership_requests
    set status = 'approved', resolved_at = now(), resolved_by_user_id = actor_user_id
    where __LANE___private.team_membership_requests.season_id = target_season_id
      and __LANE___private.team_membership_requests.team_id = target_team_id
      and __LANE___private.team_membership_requests.player_id = target_player_id
      and __LANE___private.team_membership_requests.status = 'pending';
  end if;

  return query
  select ti.id, ti.season_id, ti.team_id, ti.invited_player_id, ti.status, ti.created_at
  from __LANE___private.team_invitations ti
  where ti.id = inserted_invitation_id;
end;
$function$;

create or replace function __LANE__.respond_to_team_invitation(
  actor_user_id uuid,
  target_invitation_id uuid,
  response_status text
)
returns table(
  id uuid,
  season_id uuid,
  team_id uuid,
  invited_player_id uuid,
  status text,
  responded_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $function$
declare
  invitation __LANE___private.team_invitations%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_invitation_id is null then raise exception 'target_invitation_id is required'; end if;
  if response_status not in ('accepted', 'declined') then
    raise exception 'response_status must be accepted or declined';
  end if;

  select * into invitation
  from __LANE___private.team_invitations ti
  where ti.id = target_invitation_id
  for update;
  if not found then raise exception 'Invitation not found'; end if;
  if invitation.status <> 'pending' then raise exception 'Invitation is no longer pending'; end if;

  if not exists (
    select 1 from __LANE__.players p
    where p.id = invitation.invited_player_id
      and p.user_id = actor_user_id
  ) then
    raise exception 'Only the invited player can respond';
  end if;

  if response_status = 'accepted' then
    if not exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = invitation.season_id
        and tm.team_id = invitation.team_id
        and tm.player_id = invitation.invited_player_id
        and tm.ends_at is null
    ) then
      insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
      values(invitation.season_id, invitation.team_id, invitation.invited_player_id, 'player');
    end if;

    update __LANE___private.team_membership_requests
    set status = 'approved', resolved_at = now(), resolved_by_user_id = actor_user_id
    where __LANE___private.team_membership_requests.season_id = invitation.season_id
      and __LANE___private.team_membership_requests.team_id = invitation.team_id
      and __LANE___private.team_membership_requests.player_id = invitation.invited_player_id
      and __LANE___private.team_membership_requests.status = 'pending';
  end if;

  update __LANE___private.team_invitations
  set status = response_status,
      responded_at = now()
  where __LANE___private.team_invitations.id = target_invitation_id;

  return query
  select ti.id, ti.season_id, ti.team_id, ti.invited_player_id, ti.status, ti.responded_at
  from __LANE___private.team_invitations ti
  where ti.id = target_invitation_id;
