-- Replayed from supabase/migrations/20260811120500_explicit_scoring_team_context.sql
create or replace function __LANE___private.match_tracker_for_scoring_team(
  actor_user_id uuid,
  target_match __LANE__.player_matches,
  target_scoring_team_id uuid
)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  actor_player_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_scoring_team_id is null then raise exception 'scoring_team_id is required'; end if;
  if target_scoring_team_id not in (target_match.team_a_id, target_match.team_b_id) then
    raise exception 'Scoring team is not part of this player match';
  end if;
  select p.id into actor_player_id from __LANE__.players p where p.user_id = actor_user_id limit 1;
  if actor_player_id is null or not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.player_id = actor_player_id
      and tm.season_id = target_match.season_id
      and tm.team_id = target_scoring_team_id
      and tm.ends_at is null
  ) then raise exception 'Actor is not an active member of the scoring team'; end if;
  return case when target_scoring_team_id = target_match.team_a_id then target_match.player_a_id else target_match.player_b_id end;
end;
$$;
