drop function if exists __LANE__.get_player_match_score_comparison(uuid, uuid);
create function __LANE__.get_player_match_score_comparison(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid)
returns table(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, opponent_player_id uuid, own_racks jsonb, opponent_racks jsonb, own_confirmed_at timestamptz, opponent_confirmed_at timestamptz, histories_match boolean, mismatch_rack_number integer, both_confirmed boolean, ready_to_finalize boolean)
language plpgsql security definer set search_path = '' as $$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
  opponent_id uuid;
  own_submission __LANE___private.player_match_score_submissions%rowtype;
  opponent_submission __LANE___private.player_match_score_submissions%rowtype;
  own_history jsonb;
  opponent_history jsonb;
  mismatch_number integer;
begin
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  select * into target_match from __LANE__.player_matches pm where pm.id = target_player_match_id;
  if not found then raise exception 'Player match not found'; end if;
  tracker_id := __LANE___private.match_tracker_for_scoring_team(actor_user_id, target_match, target_scoring_team_id);
  opponent_id := case when tracker_id = target_match.player_a_id then target_match.player_b_id else target_match.player_a_id end;
  select * into own_submission from __LANE___private.player_match_score_submissions s where s.player_match_id = target_player_match_id and s.tracker_player_id = tracker_id;
  select * into opponent_submission from __LANE___private.player_match_score_submissions s where s.player_match_id = target_player_match_id and s.tracker_player_id = opponent_id;
  own_history := coalesce(own_submission.racks, '[]'::jsonb);
  opponent_history := coalesce(opponent_submission.racks, '[]'::jsonb);
  select gs + 1 into mismatch_number from generate_series(0, greatest(jsonb_array_length(own_history), jsonb_array_length(opponent_history)) - 1) gs
    where (own_history -> gs) is distinct from (opponent_history -> gs) order by gs limit 1;
  return query select target_player_match_id, target_scoring_team_id, tracker_id, opponent_id, own_history, opponent_history,
    own_submission.confirmed_at, opponent_submission.confirmed_at,
    (own_history = opponent_history and jsonb_array_length(own_history) > 0), mismatch_number,
    (own_submission.confirmed_at is not null and opponent_submission.confirmed_at is not null),
    (own_history = opponent_history and jsonb_array_length(own_history) > 0 and own_submission.confirmed_at is not null and opponent_submission.confirmed_at is not null);
end;
$$;
revoke all on function __LANE__.get_player_match_score_comparison(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function __LANE__.get_player_match_score_comparison(uuid, uuid, uuid) to service_role;

drop function if exists __LANE__.record_player_match_score_rack(uuid, uuid, text);
create function __LANE__.record_player_match_score_rack(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, rack_winner_side text)
returns table(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, discipline text, winner_side text, score_a integer, score_b integer, record_complete boolean)
language plpgsql security definer set search_path = '' as $$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
  existing_submission __LANE___private.player_match_score_submissions%rowtype;
  next_rack_number integer;
  rack_discipline text;
  next_racks jsonb;
  next_score_a integer;
  next_score_b integer;
begin
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  if rack_winner_side not in ('A', 'B') then raise exception 'rack_winner_side must be A or B'; end if;
  select * into target_match from __LANE__.player_matches pm where pm.id = target_player_match_id for update;
  if not found then raise exception 'Player match not found'; end if;
  if target_match.status in ('finalized', 'corrected') then raise exception 'Player match is finalized'; end if;
  if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before recording racks'; end if;
  tracker_id := __LANE___private.match_tracker_for_scoring_team(actor_user_id, target_match, target_scoring_team_id);
  select * into existing_submission from __LANE___private.player_match_score_submissions s where s.player_match_id = target_player_match_id and s.tracker_player_id = tracker_id for update;
  if not found then existing_submission.racks := '[]'::jsonb; end if;
  select count(*) filter (where elem->>'winnerSide'='A')::integer, count(*) filter (where elem->>'winnerSide'='B')::integer
    into next_score_a, next_score_b from jsonb_array_elements(existing_submission.racks) elem;
  if next_score_a >= target_match.race_to_a or next_score_b >= target_match.race_to_b then raise exception 'Score record is already complete'; end if;
  next_rack_number := jsonb_array_length(existing_submission.racks) + 1;
  rack_discipline := case when next_rack_number <= target_match.opening_block_length then target_match.opening_discipline when target_match.opening_discipline='8-ball' then '9-ball' else '8-ball' end;
  next_racks := existing_submission.racks || jsonb_build_array(jsonb_build_object('rackNumber', next_rack_number, 'discipline', rack_discipline, 'winnerSide', rack_winner_side));
  select count(*) filter (where elem->>'winnerSide'='A')::integer, count(*) filter (where elem->>'winnerSide'='B')::integer
