drop function if exists __LANE__.list_scorable_player_matches(uuid);
create function __LANE__.list_scorable_player_matches(actor_user_id uuid)
returns table(player_match_id uuid,season_id uuid,season_name text,round_id uuid,round_number integer,scheduled_on date,team_match_id uuid,slot_number integer,status text,team_a_name text,team_b_name text,player_a_name text,player_b_name text,scoring_team_id uuid,scoring_team_name text,editable_side text)
language sql stable security definer set search_path = '' as $$
  with actor as (select p.id as player_id from __LANE__.players p where p.user_id=actor_user_id limit 1)
  select pm.id,pm.season_id,s.name,pm.round_id,r.round_number,r.scheduled_on,pm.team_match_id,pm.slot_number,pm.status,ta.name,tb.name,pa.display_name,pb.display_name,tm.team_id,
    case when tm.team_id=pm.team_a_id then ta.name else tb.name end,
    case when tm.team_id=pm.team_a_id then 'A' else 'B' end
  from __LANE__.player_matches pm
  join actor a on true
  join __LANE__.team_memberships tm on tm.player_id=a.player_id and tm.season_id=pm.season_id and tm.ends_at is null and tm.team_id in(pm.team_a_id,pm.team_b_id)
  join __LANE__.seasons s on s.id=pm.season_id join __LANE__.rounds r on r.id=pm.round_id join __LANE__.teams ta on ta.id=pm.team_a_id join __LANE__.teams tb on tb.id=pm.team_b_id join __LANE__.players pa on pa.id=pm.player_a_id join __LANE__.players pb on pb.id=pm.player_b_id
  where pm.status not in('finalized','corrected')
  order by case when r.scheduled_on>=current_date then 0 else 1 end,abs(r.scheduled_on-current_date),r.round_number,pm.slot_number,tm.team_id;
$$;
