-- Replayed from supabase/migrations/20260811121500_preserve_reconciled_score_validation.sql
create or replace function __LANE__.finalize_reconciled_player_match(
  actor_user_id uuid,
  target_player_match_id uuid,
  target_scoring_team_id uuid
)
returns table (
  player_match_id uuid,
  status text,
  winner_side text,
  winner_player_id uuid,
  score_a integer,
  score_b integer,
  finalized_at timestamptz
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_match __LANE__.player_matches%rowtype;
  finalized_match __LANE__.player_matches%rowtype;
  authorized_tracker_id uuid;
  submission_a __LANE___private.player_match_score_submissions%rowtype;
  submission_b __LANE___private.player_match_score_submissions%rowtype;
  reconciled_racks jsonb;
  reconciled_score_a integer;
  reconciled_score_b integer;
  resolved_winner_side text;
  resolved_winner_player_id uuid;
  canonical_before jsonb;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if target_player_match_id is null then
    raise exception 'target_player_match_id is required';
  end if;
  if target_scoring_team_id is null then
    raise exception 'scoring_team_id is required';
  end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;
  if target_match.status in ('finalized', 'corrected') then
    raise exception 'Player match is already finalized';
  end if;

  authorized_tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );
  if authorized_tracker_id is null then
    raise exception 'Actor is not an active member of the scoring team';
  end if;

  if target_match.race_to_a is null or target_match.race_to_b is null then
    raise exception 'Race targets are required before finalization';
  end if;

  select * into submission_a
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = target_match.player_a_id
  for update;
  if not found then
    raise exception 'Both team score records are required before finalization';
  end if;

  select * into submission_b
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = target_match.player_b_id
  for update;
  if not found then
    raise exception 'Both team score records are required before finalization';
  end if;

  if submission_a.confirmed_at is null or submission_b.confirmed_at is null then
    raise exception 'Both teams must confirm the reconciled score before finalization';
  end if;
  if submission_a.racks is distinct from submission_b.racks
      or jsonb_array_length(submission_a.racks) = 0 then
    raise exception 'Team score histories must match before finalization';
  end if;

  reconciled_racks := submission_a.racks;

  if exists (
    select 1
    from jsonb_array_elements(reconciled_racks) with ordinality as rack(value, ordinality)
    where coalesce(rack.value ->> 'winnerSide', '') not in ('A', 'B')
       or nullif(rack.value ->> 'rackNumber', '')::integer is distinct from rack.ordinality::integer
       or coalesce(rack.value ->> 'discipline', '') is distinct from (
         case
           when rack.ordinality <= target_match.opening_block_length then target_match.opening_discipline
           when target_match.opening_discipline = '8-ball' then '9-ball'
           else '8-ball'
         end
       )
  ) then
    raise exception 'Reconciled rack history is invalid';
  end if;

  select
    count(*) filter (where rack.value ->> 'winnerSide' = 'A')::integer,
    count(*) filter (where rack.value ->> 'winnerSide' = 'B')::integer
  into reconciled_score_a, reconciled_score_b
  from jsonb_array_elements(reconciled_racks) as rack(value);

  if reconciled_score_a >= target_match.race_to_a
      and reconciled_score_b >= target_match.race_to_b then
    raise exception 'Reconciled score cannot have both players reach the race target';
  end if;
  if reconciled_score_a < target_match.race_to_a
      and reconciled_score_b < target_match.race_to_b then
    raise exception 'Race target must be reached before finalization';
  end if;

  if reconciled_score_a >= target_match.race_to_a then
    resolved_winner_side := 'A';
    resolved_winner_player_id := target_match.player_a_id;
  else
    resolved_winner_side := 'B';
    resolved_winner_player_id := target_match.player_b_id;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rackNumber', pmr.rack_number,
        'discipline', pmr.discipline,
        'winnerSide', pmr.winner_side,
        'winnerPlayerId', pmr.winner_player_id,
        'recordedBy', pmr.recorded_by,
        'recordedAt', pmr.recorded_at
      ) order by pmr.rack_number
    ),
    '[]'::jsonb
  ) into canonical_before
  from __LANE__.player_match_racks pmr
  where pmr.player_match_id = target_player_match_id;

  delete from __LANE__.player_match_racks pmr
  where pmr.player_match_id = target_player_match_id;

  insert into __LANE__.player_match_racks (
    season_id,
    player_match_id,
    rack_number,
    discipline,
    winner_side,
    winner_player_id,
    recorded_by
  )
  select
    target_match.season_id,
    target_player_match_id,
    rack.ordinality::integer,
    rack.value ->> 'discipline',
    rack.value ->> 'winnerSide',
    case
      when rack.value ->> 'winnerSide' = 'A' then target_match.player_a_id
      else target_match.player_b_id
    end,
    actor_user_id
  from jsonb_array_elements(reconciled_racks) with ordinality as rack(value, ordinality)
  order by rack.ordinality;

  update __LANE__.player_matches
  set score_a = reconciled_score_a,
      score_b = reconciled_score_b,
      winner_side = resolved_winner_side,
      winner_player_id = resolved_winner_player_id,
      status = 'finalized',
      finalized_by = actor_user_id,
      finalized_at = now()
  where player_matches.id = target_player_match_id
  returning * into finalized_match;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'player_match.finalize_reconciled',
    'player_match',
    target_player_match_id,
    jsonb_build_object(
      'match', to_jsonb(target_match),
      'canonicalRacks', canonical_before,
      'teamASubmission', to_jsonb(submission_a),
      'teamBSubmission', to_jsonb(submission_b),
      'scoringTeamId', target_scoring_team_id
    ),
    jsonb_build_object(
      'match', to_jsonb(finalized_match),
      'reconciledRacks', reconciled_racks,
      'scoringTeamId', target_scoring_team_id
    )
  );

  return query select
    finalized_match.id,
    finalized_match.status,
    finalized_match.winner_side,
    finalized_match.winner_player_id,
    finalized_match.score_a,
    finalized_match.score_b,
    finalized_match.finalized_at;
end;
$$;

revoke all on function __LANE__.finalize_reconciled_player_match(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function __LANE__.finalize_reconciled_player_match(uuid, uuid, uuid) to service_role;


-- Replayed from supabase/migrations/20260811123000_nightly_lineup_sub_picker.sql
-- Nightly lineup candidate read model and trusted eligibility checks.
-- Regular-season players may represent multiple teams in the same round, but never
-- more than once for the same team because each submitted team lineup is unique and
-- slot players are unique. The existing trigger remains the concurrency-safe 7-match cap.

-- The old availability read model carried two superseded assumptions:
--   1. free agents disappeared once a roster reached four players;
--   2. anyone rostered on another team was hidden from substitute discovery.
-- Replace it with a captain-only read model that shows the full own roster plus
-- explicitly available substitutes, together with hard eligibility blockers.

drop function if exists __LANE__.list_team_round_availability(uuid, uuid, uuid);

create function __LANE__.list_team_round_availability(
  actor_user_id uuid,
  target_team_id uuid,
  target_round_id uuid
)
returns table(
  season_id uuid,
  round_id uuid,
  team_id uuid,
  player_id uuid,
  display_name text,
  role text,
  participation_type text,
  fargo_rating integer,
  rating_status text,
  availability_status text,
  updated_at timestamptz,
  payment_status text,
  regular_matches_scheduled integer,
  eligible boolean,
  eligibility_reason text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor_player_id uuid;
  target_season_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before viewing team availability'; end if;

  select t.season_id into target_season_id
  from __LANE__.teams t
  where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;

  if not exists (
    select 1 from __LANE__.rounds r
    where r.id = target_round_id and r.season_id = target_season_id and r.stage = 'regular'
  ) then raise exception 'Regular-season round not found for team season'; end if;

  if not exists (
    select 1 from __LANE__.team_matches tm
    where tm.round_id = target_round_id
      and (tm.team_a_id = target_team_id or tm.team_b_id = target_team_id)
  ) then raise exception 'Team is not scheduled for target round'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then raise exception 'Only the active captain can view team round availability'; end if;

  return query
  with scheduled_counts as (
    select tls.player_id, count(*)::integer as match_count
    from __LANE___private.team_lineup_slots tls
    join __LANE__.rounds r on r.id = tls.round_id
    where tls.season_id = target_season_id
      and tls.player_id is not null
      and r.stage = 'regular'
    group by tls.player_id
  ),
  available_sub_ids as (
    -- Free agents who explicitly marked this round available.
    select fa.player_id, fa.updated_at
    from __LANE___private.free_agent_availability fa
    join __LANE__.season_players sp
      on sp.season_id = fa.season_id and sp.player_id = fa.player_id
    where fa.season_id = target_season_id
      and fa.round_id = target_round_id
      and fa.status = 'available'
      and sp.status = 'active'

    union

    -- A rostered player may also substitute for another team in the same round.
    -- Their roster availability is player/round scoped by the existing key, so an
    -- explicit available status is sufficient; no season-wide membership exclusion.
    select ra.player_id, ra.updated_at
    from __LANE___private.roster_availability ra
    where ra.season_id = target_season_id
      and ra.round_id = target_round_id
      and ra.status = 'available'
      and exists (
        select 1 from __LANE__.team_memberships other_tm
        where other_tm.season_id = target_season_id
          and other_tm.player_id = ra.player_id
          and other_tm.ends_at is null
      )
  ),
  candidates as (
    select
      0 as sort_order,
      tm.season_id,
      target_round_id as round_id,
      tm.team_id,
      p.id as player_id,
      p.display_name,
      tm.role,
      'roster'::text as participation_type,
      pr.fargo_rating,
      pr.rating_status,
      ra.status as availability_status,
      ra.updated_at
    from __LANE__.team_memberships tm
    join __LANE__.players p on p.id = tm.player_id
    left join __LANE__.player_ratings pr on pr.player_id = tm.player_id
    left join __LANE___private.roster_availability ra
      on ra.round_id = target_round_id and ra.player_id = tm.player_id
    where tm.team_id = target_team_id
      and tm.season_id = target_season_id
      and tm.ends_at is null

    union all

    select
      1 as sort_order,
      target_season_id as season_id,
      target_round_id as round_id,
      target_team_id as team_id,
      p.id as player_id,
      p.display_name,
      null::text as role,
      'substitute'::text as participation_type,
      pr.fargo_rating,
      pr.rating_status,
      'available'::text as availability_status,
      max(available_sub_ids.updated_at) as updated_at
    from available_sub_ids
    join __LANE__.players p on p.id = available_sub_ids.player_id
    left join __LANE__.player_ratings pr on pr.player_id = p.id
    where not exists (
      select 1 from __LANE__.team_memberships own_tm
      where own_tm.season_id = target_season_id
        and own_tm.team_id = target_team_id
        and own_tm.player_id = p.id
        and own_tm.ends_at is null
    )
    group by p.id, p.display_name, pr.fargo_rating, pr.rating_status
  )
  select
    c.season_id,
    c.round_id,
    c.team_id,
    c.player_id,
    c.display_name,
    c.role,
    c.participation_type,
    c.fargo_rating,
    c.rating_status,
    c.availability_status,
    c.updated_at,
    coalesce(pay.status, 'unpaid') as payment_status,
    coalesce(sc.match_count, 0) as regular_matches_scheduled,
    (
      coalesce(pay.status, 'unpaid') in ('paid', 'waived')
      and coalesce(sc.match_count, 0) < 7
    ) as eligible,
    case
      when coalesce(pay.status, 'unpaid') not in ('paid', 'waived') then 'Payment required before playing'
      when coalesce(sc.match_count, 0) >= 7 then 'Season limit reached (7/7)'
      else null
    end as eligibility_reason
  from candidates c
  left join __LANE___private.payment_status pay
    on pay.season_id = target_season_id and pay.player_id = c.player_id
  left join scheduled_counts sc on sc.player_id = c.player_id
  order by
    c.sort_order,
    case coalesce(c.availability_status, 'unsure')
      when 'available' then 0 when 'unsure' then 1 when 'unavailable' then 2 else 1 end,
    lower(c.display_name),
    c.player_id;
end;
$$;

