to service_role;


-- Replayed from supabase/migrations/20260811124500_player_team_match_choice.sql
-- A player who belongs to both teams in one head-to-head matchup chooses the
-- team they will represent before either captain may lock them into a lineup.
-- Every lineup path also enforces one appearance per player per team matchup.

create table __LANE___private.team_match_player_choices (
  team_match_id uuid not null references __LANE__.team_matches(id) on delete cascade,
  player_id uuid not null references __LANE__.players(id) on delete cascade,
  team_id uuid not null references __LANE__.teams(id) on delete cascade,
  chosen_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (team_match_id, player_id)
);

create index team_match_player_choices_player_idx
  on __LANE___private.team_match_player_choices (player_id, team_match_id);
create index team_match_player_choices_team_idx
  on __LANE___private.team_match_player_choices (team_id);

alter table __LANE___private.team_match_player_choices enable row level security;
revoke all on table __LANE___private.team_match_player_choices from public, anon, authenticated;
