create function __LANE__.list_my_team_match_choices(actor_user_id uuid)
returns table(
  team_match_id uuid,
  season_id uuid,
  round_id uuid,
  round_number integer,
  scheduled_on date,
  stage text,
  team_a_id uuid,
  team_a_name text,
