create or replace function __LANE__.set_league_admin_role(
  actor_user_id uuid,
  target_player_id uuid,
  enabled boolean,
  change_reason text default null
)
returns table (
  player_id uuid,
  is_league_admin boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  target_user_id uuid;
  was_admin boolean;
  normalized_reason text;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if target_player_id is null then
    raise exception 'target_player_id is required';
  end if;
  if enabled is null then
    raise exception 'enabled is required';
  end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  select p.user_id into target_user_id
  from __LANE__.players p
  where p.id = target_player_id
  for update;

  if not found then
    raise exception 'Player not found';
  end if;
  if target_user_id is null then
    raise exception 'Player must sign in before admin access can be granted';
  end if;

  normalized_reason := nullif(btrim(change_reason), '');
  if normalized_reason is not null and char_length(normalized_reason) > 500 then
    raise exception 'reason must be 500 characters or fewer';
  end if;

  select exists (
    select 1 from __LANE___private.league_admins la where la.user_id = target_user_id
  ) into was_admin;

  if enabled then
    insert into __LANE___private.league_admins (user_id, granted_by, note)
    values (target_user_id, actor_user_id, normalized_reason)
    on conflict (user_id) do update
      set granted_by = excluded.granted_by,
          note = excluded.note;
  else
    if was_admin and (
      select count(*) from __LANE___private.league_admins
    ) <= 1 then
      raise exception 'The last league admin cannot be removed';
    end if;
    delete from __LANE___private.league_admins where user_id = target_user_id;
  end if;

  if was_admin is distinct from enabled then
    insert into __LANE___private.audit_events (
      actor_user_id,
      action,
      entity_type,
      entity_id,
      reason,
      before_state,
      after_state
    ) values (
      actor_user_id,
      case when enabled then 'player.grant_admin' else 'player.revoke_admin' end,
      'player',
      target_player_id,
      normalized_reason,
      jsonb_build_object('isLeagueAdmin', was_admin),
      jsonb_build_object('isLeagueAdmin', enabled)
    );
  end if;

  return query select target_player_id, enabled;
end;
$$;

