CREATE OR REPLACE FUNCTION __LANE___private.assert_expected_score_history(target_player_match_id uuid, target_tracker_player_id uuid, expected_racks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_racks jsonb;
begin
  if expected_racks is null or jsonb_typeof(expected_racks) <> 'array' then
    raise exception 'expected_racks must be an array';
  end if;

  select coalesce(s.racks, '[]'::jsonb)
    into current_racks
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = target_tracker_player_id
  for update;

  if current_racks is null then
    current_racks := '[]'::jsonb;
  end if;

  if current_racks is distinct from expected_racks then
    raise exception 'Score changed on another device';
  end if;

  return current_racks;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.auto_register_new_player_for_open_season()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  open_season_count integer;
  open_season_id uuid;
  fee_cents integer;
begin
  select count(*)
  into open_season_count
  from __LANE__.seasons season
  where season.status = 'registration';

  if open_season_count <> 1 then
    return new;
  end if;

  select season.id
  into open_season_id
  from __LANE__.seasons season
  where season.status = 'registration'
  order by season.created_at desc, season.id desc
  limit 1;

  insert into __LANE__.season_players (
    season_id, player_id, participation_type, status
  ) values (
    open_season_id, new.id, 'free_agent', 'active'
  )
  on conflict (season_id, player_id) do nothing;

  select coalesce(configuration.entry_fee_cents, 0)
  into fee_cents
  from __LANE__.season_prize_configurations configuration
  where configuration.season_id = open_season_id
  order by configuration.version desc
  limit 1;

  insert into __LANE___private.payment_status (
    season_id, player_id, status, amount_due_cents, amount_paid_cents
  ) values (
    open_season_id, new.id, 'unpaid', coalesce(fee_cents, 0), 0
  )
  on conflict (season_id, player_id) do nothing;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.auto_register_rostered_member_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.ends_at is null and exists (
    select 1 from __LANE__.seasons s
    where s.id = new.season_id and s.status = 'registration'
  ) then
    insert into __LANE__.season_players(season_id, player_id, participation_type, status)
    values(new.season_id, new.player_id, 'rostered', 'active')
    on conflict on constraint season_players_season_id_player_id_key
    do update set participation_type = 'rostered', status = 'active';
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.can_score_player_match(actor_user_id uuid, target_match __LANE__.player_matches)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select exists(select 1 from __LANE__.players p where p.user_id=actor_user_id and p.id in (target_match.player_a_id,target_match.player_b_id)) or exists(select 1 from __LANE__.players p join __LANE__.team_memberships tm on tm.player_id=p.id where p.user_id=actor_user_id and tm.season_id=target_match.season_id and tm.team_id in (target_match.team_a_id,target_match.team_b_id) and tm.role='captain' and tm.ends_at is null); $function$;


CREATE OR REPLACE FUNCTION __LANE___private.committed_team_roster_count(target_team_id uuid, target_season_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select count(distinct tm.player_id)::integer
  from __LANE__.team_memberships tm
  join __LANE__.season_players sp
    on sp.season_id = tm.season_id
   and sp.player_id = tm.player_id
   and sp.status = 'active'
  where tm.team_id = target_team_id
    and tm.season_id = target_season_id
    and tm.ends_at is null;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.complete_team_trade_if_ready(target_trade_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  trade __LANE___private.team_trades%rowtype;
  offered_membership __LANE__.team_memberships%rowtype;
  requested_membership __LANE__.team_memberships%rowtype;
  completed_trade __LANE___private.team_trades%rowtype;
begin
  select *
    into trade
  from __LANE___private.team_trades tt
  where tt.id = target_trade_id
  for update;

  if not found or trade.status <> 'pending' then
    return;
  end if;

  if not trade.admin_exception
      and __LANE___private.season_roster_lock_has_passed(trade.season_id) then
    raise exception 'Roster lock has passed; admin exception required';
  end if;

  if trade.requesting_player_accepted_at is null
      or trade.requested_player_accepted_at is null
      or trade.requesting_captain_approved_at is null
      or trade.requested_captain_approved_at is null then
    return;
  end if;

  select *
    into offered_membership
  from __LANE__.team_memberships tm
  where tm.season_id = trade.season_id
    and tm.team_id = trade.requesting_team_id
    and tm.player_id = trade.offered_player_id
    and tm.role = 'player'
    and tm.ends_at is null
  for update;

  if not found then
    raise exception 'Offered player active membership changed';
  end if;

  select *
    into requested_membership
  from __LANE__.team_memberships tm
  where tm.season_id = trade.season_id
    and tm.team_id = trade.requested_team_id
    and tm.player_id = trade.requested_player_id
    and tm.role = 'player'
    and tm.ends_at is null
  for update;

  if not found then
    raise exception 'Requested player active membership changed';
  end if;

  update __LANE__.team_memberships
  set ends_at = now()
  where id in (offered_membership.id, requested_membership.id);

  insert into __LANE__.team_memberships (
    season_id,
    team_id,
    player_id,
    role
  ) values
    (
      trade.season_id,
      trade.requested_team_id,
      trade.offered_player_id,
      'player'
    ),
    (
      trade.season_id,
      trade.requesting_team_id,
      trade.requested_player_id,
      'player'
    );

  update __LANE___private.team_trades
  set status = 'completed',
      completed_at = now()
  where id = target_trade_id
  returning * into completed_trade;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    trade.proposed_by_user_id,
    'team_trade.complete',
    'team_trade',
    target_trade_id,
    jsonb_build_object(
      'offeredMembership', to_jsonb(offered_membership),
      'requestedMembership', to_jsonb(requested_membership)
    ),
    to_jsonb(completed_trade)
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.current_player_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select p.id
  from __LANE__.players p
  where p.user_id = (select auth.uid())
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_captain_contact_before_season_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.status in ('draft', 'registration') and new.status = 'active' and exists (
    select 1
    from __LANE___private.season_team_slots sts
    where sts.season_id = new.id
      and sts.status = 'confirmed'
      and not exists (
        select 1
        from __LANE__.team_memberships tm
        join __LANE___private.player_contacts pc on pc.player_id = tm.player_id
        where tm.season_id = new.id
          and tm.team_id = sts.team_id
          and tm.role = 'captain'
          and tm.ends_at is null
          and nullif(btrim(pc.phone), '') is not null
      )
  ) then
    raise exception 'Every confirmed team requires a captain with a phone number before publication';
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_committed_roster_on_slot_confirmation_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  minimum_count integer;
begin
  if old.status in ('approved_pending_roster', 'ready')
      and new.status = 'confirmed' then
    select s.minimum_committed_roster into minimum_count
    from __LANE__.seasons s where s.id = new.season_id;

    if __LANE___private.committed_team_roster_count(new.team_id, new.season_id) < minimum_count then
      raise exception 'Team must meet the minimum committed roster before confirmation';
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_one_player_per_team_match()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_lineup __LANE___private.team_lineups%rowtype;
  target_match __LANE__.team_matches%rowtype;
  selected_team_id uuid;
begin
  if new.player_id is null then return new; end if;

  select * into target_lineup
  from __LANE___private.team_lineups lineup
  where lineup.id = new.lineup_id;
  if not found then raise exception 'Lineup not found for slot'; end if;

  select * into target_match
  from __LANE__.team_matches tm
  where tm.id = target_lineup.team_match_id;
  if not found then raise exception 'Team matchup not found for lineup'; end if;

  if target_lineup.team_id not in (target_match.team_a_id, target_match.team_b_id) then
    raise exception 'Lineup team is not part of this matchup';
  end if;

  if exists (
    select 1
    from __LANE___private.team_lineup_slots other_slot
    join __LANE___private.team_lineups other_lineup on other_lineup.id = other_slot.lineup_id
    where other_lineup.team_match_id = target_lineup.team_match_id
      and other_slot.player_id = new.player_id
      and not (
        other_slot.lineup_id = new.lineup_id
        and other_slot.slot_number = new.slot_number
      )
  ) then
    raise exception 'A player cannot appear twice in the same team matchup';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships member_a
    where member_a.season_id = target_match.season_id
      and member_a.team_id = target_match.team_a_id
      and member_a.player_id = new.player_id
      and member_a.ends_at is null
  ) and exists (
    select 1 from __LANE__.team_memberships member_b
    where member_b.season_id = target_match.season_id
      and member_b.team_id = target_match.team_b_id
      and member_b.player_id = new.player_id
      and member_b.ends_at is null
  ) then
    select choice.team_id into selected_team_id
    from __LANE___private.team_match_player_choices choice
    where choice.team_match_id = target_lineup.team_match_id
      and choice.player_id = new.player_id;

    if selected_team_id is null then
      raise exception 'Player must choose a team for this matchup before lineups are locked';
    end if;
    if selected_team_id <> target_lineup.team_id then
      raise exception 'Player chose the opposing team for this matchup';
    end if;
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_phone_for_active_captain_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  season_status text;
begin
  if new.role = 'captain' and new.ends_at is null then
    select s.status into season_status
    from __LANE__.seasons s
    where s.id = new.season_id;

    if season_status in ('active', 'playoffs') and not exists (
      select 1 from __LANE___private.player_contacts pc
      where pc.player_id = new.player_id
        and nullif(btrim(pc.phone), '') is not null
    ) then
      raise exception 'Phone number is required before assigning an active captain';
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_regular_season_player_match_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  target_stage text;
  existing_appearances integer;
begin
  if new.player_id is null then
    return new;
  end if;

  select r.stage
    into target_stage
  from __LANE__.rounds r
  where r.id = new.round_id;

  if target_stage is distinct from 'regular' then
    return new;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(new.season_id::text || ':' || new.player_id::text, 0)
  );

  select count(*)::integer
    into existing_appearances
  from __LANE___private.team_lineup_slots tls
  join __LANE__.rounds r on r.id = tls.round_id
  where tls.season_id = new.season_id
    and tls.player_id = new.player_id
    and r.stage = 'regular'
    and not (
      tls.lineup_id = new.lineup_id
      and tls.slot_number = new.slot_number
    );

  if existing_appearances >= 7 then
    raise exception 'Player cannot be scheduled for more than seven regular-season matches';
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.enforce_viable_teams_before_season_publication_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  viable_count integer;
begin
  if old.status in ('draft', 'registration') and new.status = 'active' then
    perform __LANE___private.expire_season_team_registration(new.id);
    select count(*)::integer into viable_count
    from __LANE___private.season_team_slots sts
    where sts.season_id = new.id
      and sts.status = 'confirmed'
      and __LANE___private.committed_team_roster_count(sts.team_id, sts.season_id)
          >= new.minimum_committed_roster;

    if viable_count <> new.team_capacity then
      raise exception 'Season requires exactly % confirmed teams with at least % committed players before publication',
        new.team_capacity, new.minimum_committed_roster;
    end if;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.expire_season_team_registration(target_season_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update __LANE___private.season_team_slots sts
  set status = 'expired',
      resolved_at = now(),
      updated_at = now(),
      last_action_reason = coalesce(sts.last_action_reason, 'Reservation deadline passed')
  where sts.season_id = target_season_id
    and sts.status in ('reserved', 'transferred')
    and sts.reservation_expires_at is not null
    and sts.reservation_expires_at <= now();

  with expired_holds as (
    update __LANE___private.season_team_slots sts
    set status = 'expired',
        resolved_at = now(),
        updated_at = now(),
        last_action_reason = coalesce(sts.last_action_reason, 'Roster completion deadline passed')
    from __LANE__.seasons s
    where sts.season_id = target_season_id
      and s.id = sts.season_id
      and sts.status in ('approved_pending_roster', 'ready')
      and sts.hold_expires_at is not null
      and sts.hold_expires_at <= now()
      and __LANE___private.committed_team_roster_count(sts.team_id, sts.season_id)
          < s.minimum_committed_roster
    returning sts.id
  )
  update __LANE___private.team_applications ta
  set status = 'expired',
      updated_at = now(),
      admin_notes = coalesce(ta.admin_notes, 'Roster completion deadline passed')
  where ta.slot_id in (select id from expired_holds)
    and ta.status in ('approved_pending_roster', 'ready');
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.guard_explicit_season_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'complete'
     and old.status is distinct from 'complete'
     and coalesce(new.purpose, 'league') = 'league'
     and exists (
       select 1
       from __LANE__.rounds r
       join __LANE__.team_matches tm on tm.round_id = r.id
       where r.season_id = new.id
         and tm.status not in ('finalized', 'corrected')
     ) then
    raise exception 'Competitive team matchups still need final results before closing the season';
  end if;

  if new.status = 'complete'
     and old.status is distinct from 'complete'
     and coalesce(current_setting('fremont.explicit_season_close', true), '') <> 'on' then
    new.status := old.status;
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.is_active_season_participant(target_player_id uuid, target_season_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select exists (
    select 1
    from __LANE__.seasons s
    where s.id = target_season_id
      and s.status in ('registration', 'active', 'playoffs')
      and (
        exists (
          select 1
          from __LANE__.season_players sp
          where sp.season_id = s.id
            and sp.player_id = target_player_id
            and sp.status = 'active'
        )
        or exists (
          select 1
          from __LANE__.team_memberships tm
          where tm.season_id = s.id
            and tm.player_id = target_player_id
            and tm.ends_at is null
        )
      )
  );
$function$;


