CREATE OR REPLACE FUNCTION __LANE___private.lock_player_match_ratings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rating_a __LANE__.player_ratings%rowtype; rating_b __LANE__.player_ratings%rowtype; rating_band __LANE__.season_race_chart_bands%rowtype; match_season __LANE__.seasons%rowtype;
begin
select * into rating_a from __LANE__.player_ratings pr where pr.player_id=new.player_a_id;
select * into rating_b from __LANE__.player_ratings pr where pr.player_id=new.player_b_id;
select * into match_season from __LANE__.seasons s where s.id=new.season_id;
new.player_a_fargo_rating:=rating_a.fargo_rating; new.player_b_fargo_rating:=rating_b.fargo_rating; new.player_a_rating_status:=rating_a.rating_status; new.player_b_rating_status:=rating_b.rating_status; new.opening_block_length:=coalesce(match_season.opening_block_length,new.opening_block_length,3); new.opening_discipline:=coalesce(new.opening_discipline,'8-ball'); new.current_discipline:=coalesce(new.current_discipline,new.opening_discipline); new.first_break:=coalesce(new.first_break,'A');
if rating_a.fargo_rating is not null and rating_b.fargo_rating is not null then select * into rating_band from __LANE__.season_race_chart_bands band where band.season_id=new.season_id and abs(rating_a.fargo_rating-rating_b.fargo_rating)<=band.max_rating_diff order by band.max_rating_diff asc limit 1; if found then if rating_a.fargo_rating=rating_b.fargo_rating then new.race_to_a:=rating_band.stronger_race_to; new.race_to_b:=rating_band.stronger_race_to; elsif rating_a.fargo_rating>rating_b.fargo_rating then new.race_to_a:=rating_band.stronger_race_to; new.race_to_b:=rating_band.weaker_race_to; else new.race_to_a:=rating_band.weaker_race_to; new.race_to_b:=rating_band.stronger_race_to; end if; end if; end if; return new; end; $function$;


CREATE OR REPLACE FUNCTION __LANE___private.match_player_for_user(actor_user_id uuid, target_match __LANE__.player_matches)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with actor as (
    select p.id
    from __LANE__.players p
    where p.user_id = actor_user_id
    limit 1
  ), active_match_memberships as (
    select distinct tm.team_id
    from __LANE__.team_memberships tm
    join actor a on a.id = tm.player_id
    where tm.ends_at is null
      and tm.team_id in (target_match.team_a_id, target_match.team_b_id)
  )
  select case
    when coalesce(bool_or(team_id = target_match.team_a_id), false)
      and not coalesce(bool_or(team_id = target_match.team_b_id), false)
      then target_match.player_a_id
    when coalesce(bool_or(team_id = target_match.team_b_id), false)
      and not coalesce(bool_or(team_id = target_match.team_a_id), false)
      then target_match.player_b_id
    else null
  end
  from active_match_memberships;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.match_tracker_for_scoring_team(actor_user_id uuid, target_match __LANE__.player_matches, target_scoring_team_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare actor_player_id uuid; begin if actor_user_id is null then raise exception 'actor_user_id is required'; end if; if target_scoring_team_id is null then raise exception 'scoring_team_id is required'; end if; if target_scoring_team_id not in (target_match.team_a_id,target_match.team_b_id) then raise exception 'Scoring team is not part of this player match'; end if; select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id limit 1; if actor_player_id is null or not exists(select 1 from __LANE__.team_memberships tm where tm.player_id=actor_player_id and tm.season_id=target_match.season_id and tm.team_id=target_scoring_team_id and tm.ends_at is null) then raise exception 'Actor is not an active member of the scoring team'; end if; return case when target_scoring_team_id=target_match.team_a_id then target_match.player_a_id else target_match.player_b_id end; end; $function$;


CREATE OR REPLACE FUNCTION __LANE___private.prevent_final_prize_payout_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  raise exception 'Finalized prize payouts are immutable';
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.rebuild_generated_team_match_results(target_team_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.team_matches%rowtype;
  target_round __LANE__.rounds%rowtype;
  team_a_lineup_id uuid;
  team_b_lineup_id uuid;
  team_a_slot_count integer;
  team_b_slot_count integer;
  submitted_lineup_count integer;
  expected_slots integer;
begin
  select * into target_match
  from __LANE__.team_matches tm
  where tm.id = target_team_match_id;

  if not found then return; end if;

  select * into target_round
  from __LANE__.rounds r
  where r.id = target_match.round_id;

  if target_round.stage = 'tiebreaker' then return; end if;
  expected_slots := case when target_round.stage = 'regular' then 3 else 4 end;

  delete from __LANE__.player_matches pm where pm.team_match_id = target_team_match_id;
  delete from __LANE__.team_match_forfeits tmf where tmf.team_match_id = target_team_match_id;

  select count(*)::integer into submitted_lineup_count
  from __LANE___private.team_lineups tl where tl.team_match_id = target_team_match_id;

  select tl.id into team_a_lineup_id
  from __LANE___private.team_lineups tl
  where tl.team_match_id = target_team_match_id and tl.team_id = target_match.team_a_id;

  select tl.id into team_b_lineup_id
  from __LANE___private.team_lineups tl
  where tl.team_match_id = target_team_match_id and tl.team_id = target_match.team_b_id;

  if team_a_lineup_id is null or team_b_lineup_id is null then
    if submitted_lineup_count > 0 and target_match.status = 'scheduled' then
      update __LANE__.team_matches set status = 'lineups_due' where id = target_team_match_id;
    end if;
    return;
  end if;

  select count(*)::integer into team_a_slot_count
  from __LANE___private.team_lineup_slots tls where tls.lineup_id = team_a_lineup_id;
  select count(*)::integer into team_b_slot_count
  from __LANE___private.team_lineup_slots tls where tls.lineup_id = team_b_lineup_id;

  if team_a_slot_count <> expected_slots or team_b_slot_count <> expected_slots then return; end if;

  insert into __LANE__.player_matches (
    season_id, round_id, team_match_id, slot_number,
    team_a_id, team_b_id, player_a_id, player_b_id
  )
  select target_match.season_id, target_match.round_id, target_match.id,
         a.slot_number, target_match.team_a_id, target_match.team_b_id,
         a.player_id, b.player_id
  from __LANE___private.team_lineup_slots a
  join __LANE___private.team_lineup_slots b
    on b.lineup_id = team_b_lineup_id and b.slot_number = a.slot_number
  where a.lineup_id = team_a_lineup_id
    and a.player_id is not null and b.player_id is not null
  order by a.slot_number;

  insert into __LANE__.team_match_forfeits (
    season_id, round_id, team_match_id, slot_number, forfeiting_team_id, credited_team_id
  )
  select target_match.season_id, target_match.round_id, target_match.id,
         a.slot_number, target_match.team_a_id,
         case when b.player_id is not null then target_match.team_b_id else null end
  from __LANE___private.team_lineup_slots a
  join __LANE___private.team_lineup_slots b
    on b.lineup_id = team_b_lineup_id and b.slot_number = a.slot_number
  where a.lineup_id = team_a_lineup_id and a.player_id is null;

  insert into __LANE__.team_match_forfeits (
    season_id, round_id, team_match_id, slot_number, forfeiting_team_id, credited_team_id
  )
  select target_match.season_id, target_match.round_id, target_match.id,
         b.slot_number, target_match.team_b_id,
         case when a.player_id is not null then target_match.team_a_id else null end
  from __LANE___private.team_lineup_slots b
  join __LANE___private.team_lineup_slots a
    on a.lineup_id = team_a_lineup_id and a.slot_number = b.slot_number
  where b.lineup_id = team_b_lineup_id and b.player_id is null;

  update __LANE__.team_matches
  set status = 'in_progress'
  where id = target_team_match_id and status in ('scheduled', 'lineups_due');
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_generated_team_match_results_from_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare changed_lineup_id uuid; changed_team_match_id uuid;
begin changed_lineup_id:=coalesce(new.lineup_id,old.lineup_id); select tl.team_match_id into changed_team_match_id from __LANE___private.team_lineups tl where tl.id=changed_lineup_id; if changed_team_match_id is not null then perform __LANE___private.rebuild_generated_team_match_results(changed_team_match_id); end if; return null; end; $function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_postseason_team_match(target_team_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  tm __LANE__.team_matches%rowtype;
  rd __LANE__.rounds%rowtype;
  link __LANE___private.postseason_anchor_tiebreakers%rowtype;
  resolved_slots integer;
  score_a integer;
  score_b integer;
  anchor_a uuid;
  anchor_b uuid;
  tb_round_id uuid;
  tb_team_match_id uuid;
  tb_player_match_id uuid;
  next_tb_round integer;
  anchor_match __LANE__.player_matches%rowtype;
begin
  select * into tm from __LANE__.team_matches where id = target_team_match_id;
  if not found then return; end if;
  select * into rd from __LANE__.rounds where id = tm.round_id;

  if rd.stage = 'tiebreaker' then
    select * into link
    from __LANE___private.postseason_anchor_tiebreakers pat
    where pat.tiebreaker_team_match_id = tm.id;
    if not found then return; end if;

    select * into anchor_match
    from __LANE__.player_matches pm
    where pm.id = link.anchor_player_match_id;
    if anchor_match.status not in ('finalized', 'corrected') or anchor_match.winner_side is null then return; end if;

    update __LANE__.team_matches
    set status = 'finalized',
        winner_team_id = case when anchor_match.winner_side = 'A' then anchor_match.team_a_id else anchor_match.team_b_id end
    where id = tm.id;
    update __LANE__.rounds set status = 'finalized' where id = tm.round_id;
    update __LANE__.team_matches
    set status = 'finalized',
        winner_team_id = case when anchor_match.winner_side = 'A' then anchor_match.team_a_id else anchor_match.team_b_id end
    where id = link.parent_team_match_id;

    update __LANE__.rounds r
    set status = 'finalized'
    where r.id = link.parent_round_id
      and not exists (
        select 1 from __LANE__.team_matches sibling
        where sibling.round_id = r.id and sibling.status <> 'finalized'
      );

    if exists (select 1 from __LANE__.rounds pr where pr.id = link.parent_round_id and pr.stage = 'championship') then
      update __LANE__.seasons set status = 'complete' where id = link.season_id;
    end if;
    return;
  end if;

  if rd.stage not in ('semifinal', 'championship') then return; end if;

  select count(*)::integer,
         count(*) filter (where pm.winner_side = 'A')::integer,
         count(*) filter (where pm.winner_side = 'B')::integer
  into resolved_slots, score_a, score_b
  from __LANE__.player_matches pm
  where pm.team_match_id = tm.id
    and pm.slot_number between 1 and 4
    and pm.status in ('finalized', 'corrected')
    and pm.winner_side in ('A', 'B');

  if resolved_slots <> 4 then return; end if;

  if score_a <> score_b then
    update __LANE__.team_matches
    set status = 'finalized', winner_team_id = case when score_a > score_b then team_a_id else team_b_id end
    where id = tm.id;

    update __LANE__.rounds r
    set status = 'finalized'
    where r.id = tm.round_id
      and not exists (
        select 1 from __LANE__.team_matches sibling
        where sibling.round_id = r.id and sibling.status <> 'finalized'
      );

    if rd.stage = 'championship' then
      update __LANE__.seasons set status = 'complete' where id = tm.season_id;
    end if;
    return;
  end if;

  if exists (
    select 1 from __LANE___private.postseason_anchor_tiebreakers pat
    where pat.parent_team_match_id = tm.id
  ) then return; end if;

  select tl.anchor_player_id into anchor_a
  from __LANE___private.team_lineups tl
  where tl.team_match_id = tm.id and tl.team_id = tm.team_a_id;
  select tl.anchor_player_id into anchor_b
  from __LANE___private.team_lineups tl
  where tl.team_match_id = tm.id and tl.team_id = tm.team_b_id;

  if anchor_a is null or anchor_b is null then
    raise exception 'Both postseason anchors must be locked before scoring can resolve a 2-2 tie';
  end if;

  select coalesce(max(r.round_number), 0) + 1 into next_tb_round
  from __LANE__.rounds r
  where r.season_id = tm.season_id and r.stage = 'tiebreaker';

  insert into __LANE__.rounds (season_id, round_number, stage, status)
  values (tm.season_id, next_tb_round, 'tiebreaker', 'in_progress')
  returning id into tb_round_id;

  insert into __LANE__.team_matches (
    season_id, round_id, table_number, team_a_id, team_b_id, status
  ) values (
    tm.season_id, tb_round_id, 1, tm.team_a_id, tm.team_b_id, 'in_progress'
  ) returning id into tb_team_match_id;

  insert into __LANE__.player_matches (
    season_id, round_id, team_match_id, slot_number,
    team_a_id, team_b_id, player_a_id, player_b_id, status
  ) values (
    tm.season_id, tb_round_id, tb_team_match_id, 1,
    tm.team_a_id, tm.team_b_id, anchor_a, anchor_b, 'scheduled'
  ) returning id into tb_player_match_id;

  insert into __LANE___private.postseason_anchor_tiebreakers (
    season_id, parent_round_id, parent_team_match_id,
    tiebreaker_round_id, tiebreaker_team_match_id, anchor_player_match_id
  ) values (
    tm.season_id, tm.round_id, tm.id,
    tb_round_id, tb_team_match_id, tb_player_match_id
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_postseason_team_match_from_player_match()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status in ('finalized', 'corrected') and new.winner_side in ('A', 'B') then
    perform __LANE___private.refresh_postseason_team_match(new.team_match_id);
  end if;
  return null;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_team_slot_readiness(target_team_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  committed_count integer;
  minimum_count integer;
  target_slot_id uuid;
  target_status text;
  target_season_id uuid;
begin
  select sts.id, sts.status, sts.season_id, s.minimum_committed_roster
  into target_slot_id, target_status, target_season_id, minimum_count
  from __LANE___private.season_team_slots sts
  join __LANE__.seasons s on s.id = sts.season_id
  where sts.team_id = target_team_id
  order by sts.created_at desc
  limit 1
  for update of sts;

  if target_slot_id is null or target_status not in ('approved_pending_roster', 'ready') then
    return;
  end if;

  committed_count := __LANE___private.committed_team_roster_count(
    target_team_id,
    target_season_id
  );

  if committed_count >= minimum_count and target_status = 'approved_pending_roster' then
    update __LANE___private.season_team_slots
    set status = 'ready', updated_at = now()
    where id = target_slot_id;

    update __LANE___private.team_applications
    set status = 'ready', updated_at = now()
    where slot_id = target_slot_id
      and status = 'approved_pending_roster';
  elsif committed_count < minimum_count and target_status = 'ready' then
    update __LANE___private.season_team_slots
    set status = 'approved_pending_roster', updated_at = now()
    where id = target_slot_id;

    update __LANE___private.team_applications
    set status = 'approved_pending_roster', updated_at = now()
    where slot_id = target_slot_id
      and status = 'ready';
  end if;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_team_slot_readiness_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform __LANE___private.refresh_team_slot_readiness(old.team_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform __LANE___private.refresh_team_slot_readiness(new.team_id);
  end if;
  return coalesce(new, old);
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.refresh_team_slots_for_season_player_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  team_row record;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    for team_row in
      select distinct tm.team_id
      from __LANE__.team_memberships tm
      where tm.season_id = old.season_id
        and tm.player_id = old.player_id
    loop
      perform __LANE___private.refresh_team_slot_readiness(team_row.team_id);
    end loop;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    for team_row in
      select distinct tm.team_id
      from __LANE__.team_memberships tm
      where tm.season_id = new.season_id
        and tm.player_id = new.player_id
    loop
      perform __LANE___private.refresh_team_slot_readiness(team_row.team_id);
    end loop;
  end if;

  return coalesce(new, old);
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.reject_ineligible_lineup_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  restriction_reason text;
begin
  if new.player_id is null then return new; end if;

  select r.reason into restriction_reason
  from __LANE___private.player_competition_restrictions r
  where r.season_id = new.season_id
    and r.player_id = new.player_id
    and r.lifted_at is null
  limit 1;

  if restriction_reason is not null then
    raise exception 'Player is marked ineligible for competition: %', restriction_reason;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.reject_ineligible_score_advance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  restriction_reason text;
  old_rack_count integer := 0;
  new_rack_count integer := 0;
begin
  if tg_table_name = 'player_match_score_submissions' then
    new_rack_count := coalesce(jsonb_array_length(new.racks), 0);
    if tg_op = 'UPDATE' then
      old_rack_count := coalesce(jsonb_array_length(old.racks), 0);
    end if;
    if new_rack_count <= old_rack_count then return new; end if;
  end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = new.player_match_id;
  if not found then return new; end if;

  select r.reason into restriction_reason
  from __LANE___private.player_competition_restrictions r
  where r.season_id = target_match.season_id
    and r.player_id in (target_match.player_a_id, target_match.player_b_id)
    and r.lifted_at is null
  order by r.restricted_at
  limit 1;

  if restriction_reason is not null then
    raise exception 'Player is marked ineligible for competition: %', restriction_reason;
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.season_roster_lock_has_passed(target_season_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce((
    select exists (
      select 1
      from __LANE__.rounds r
      where r.season_id = s.id
        and r.stage = 'regular'
        and r.round_number >= s.roster_lock_round
        and r.scheduled_on <= current_date
    )
    from __LANE__.seasons s
    where s.id = target_season_id
      and s.roster_lock_round is not null
  ), false);
$function$;


CREATE OR REPLACE FUNCTION __LANE___private.validate_season_setup_table_numbers(table_numbers integer[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select table_numbers is not null
    and array_length(table_numbers, 1) = 4
    and not exists (
      select 1
      from unnest(table_numbers) as table_number(value)
      where value is null or value < 1
    )
    and (
      select count(distinct value)
      from unnest(table_numbers) as table_number(value)
    ) = 4;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_add_team_to_season(actor_user_id uuid, target_season_id uuid, candidate_team_id uuid)
 RETURNS TABLE(slot_id uuid, team_id uuid, team_name text, slot_status text, created_team boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 source_team __LANE__.teams%rowtype; target_season __LANE__.seasons%rowtype; assigned_team_id uuid; assigned_slot_id uuid; assigned_captain_player_id uuid; occupied_slots integer; created_new_team boolean:=false; initial_status text;
begin
 if not exists(select 1 from __LANE___private.league_admins la where la.user_id=actor_user_id) then raise exception 'Actor is not a league admin'; end if;
 if candidate_team_id is null then raise exception 'candidate_team_id is required'; end if;
 select * into target_season from __LANE__.seasons s where s.id=target_season_id for update;
 if not found then raise exception 'Season not found'; end if;
 if target_season.status not in('draft','registration') then raise exception 'Teams can only be added before season publication'; end if;
 select * into source_team from __LANE__.teams t where t.id=candidate_team_id;
 if not found then raise exception 'Team not found'; end if;
 perform pg_advisory_xact_lock(hashtextextended('season_team_capacity:'||target_season_id::text,0));
 perform __LANE___private.expire_season_team_registration(target_season_id);
 select sts.id,sts.team_id into assigned_slot_id,assigned_team_id from __LANE___private.season_team_slots sts
 where sts.season_id=target_season_id and sts.status in('reserved','transferred','approved_pending_roster','ready','confirmed') and(sts.team_id=candidate_team_id or sts.source_team_id=candidate_team_id)
 order by sts.created_at desc limit 1;
 if assigned_slot_id is not null then
   return query select sts.id,coalesce(sts.team_id,sts.source_team_id),coalesce(current_team.name,source_team_row.name),sts.status,false
   from __LANE___private.season_team_slots sts left join __LANE__.teams current_team on current_team.id=sts.team_id left join __LANE__.teams source_team_row on source_team_row.id=sts.source_team_id where sts.id=assigned_slot_id; return;
 end if;
 select count(*)::integer into occupied_slots from __LANE___private.season_team_slots sts where sts.season_id=target_season_id and sts.status in('reserved','transferred','approved_pending_roster','ready','confirmed');
 if occupied_slots>=target_season.team_capacity then raise exception 'No team slots are currently available'; end if;
 if source_team.season_id=target_season_id then assigned_team_id:=source_team.id; else
   select t.id into assigned_team_id from __LANE__.teams t where t.season_id=target_season_id and lower(btrim(t.name))=lower(btrim(source_team.name)) limit 1;
   if assigned_team_id is null then insert into __LANE__.teams(season_id,name,created_by) values(target_season_id,source_team.name,actor_user_id) returning __LANE__.teams.id into assigned_team_id; created_new_team:=true; end if;
 end if;
 select sts.id into assigned_slot_id from __LANE___private.season_team_slots sts where sts.season_id=target_season_id and sts.team_id=assigned_team_id and sts.status in('reserved','transferred','approved_pending_roster','ready','confirmed') order by sts.created_at desc limit 1;
 if assigned_slot_id is not null then return query select sts.id,sts.team_id,target_team.name,sts.status,false from __LANE___private.season_team_slots sts join __LANE__.teams target_team on target_team.id=sts.team_id where sts.id=assigned_slot_id; return; end if;
 select tm.player_id into assigned_captain_player_id from __LANE__.team_memberships tm where tm.team_id=assigned_team_id and tm.season_id=target_season_id and tm.role='captain' and tm.ends_at is null order by tm.starts_at desc limit 1;
 initial_status:=case when(select count(*) from __LANE__.team_memberships tm where tm.team_id=assigned_team_id and tm.season_id=target_season_id and tm.ends_at is null)>=target_season.minimum_committed_roster then 'ready' else 'approved_pending_roster' end;
 insert into __LANE___private.season_team_slots(season_id,source_team_id,team_id,assigned_captain_player_id,status,last_action_reason) values(target_season_id,case when source_team.season_id=target_season_id then null else source_team.id end,assigned_team_id,assigned_captain_player_id,initial_status,'Added manually by league admin') returning __LANE___private.season_team_slots.id into assigned_slot_id;
 insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,after_state) values(actor_user_id,'season.admin_add_team','season_team_slot',assigned_slot_id,jsonb_build_object('seasonId',target_season_id,'sourceTeamId',source_team.id,'teamId',assigned_team_id,'teamName',source_team.name,'createdSeasonTeam',created_new_team,'copiedRoster',false,'status',initial_status));
 return query select assigned_slot_id,assigned_team_id,source_team.name,initial_status,created_new_team;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_assign_team_captain(actor_user_id uuid, target_season_id uuid, target_team_id uuid, target_player_id uuid)
 RETURNS TABLE(team_id uuid, player_id uuid, display_name text, has_login boolean, has_phone boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_season_status text;
  target_player __LANE__.players%rowtype;
  existing_captain_id uuid;
  existing_captain_team_id uuid;
  target_has_phone boolean;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;

  select s.status into target_season_status
  from __LANE__.seasons s
  where s.id = target_season_id
  for update;
  if not found then raise exception 'Season not found'; end if;
  if target_season_status not in ('draft', 'registration', 'active', 'playoffs') then
    raise exception 'Captain cannot be assigned after the season is complete';
  end if;

  if not exists (
    select 1 from __LANE__.teams t
    where t.id = target_team_id and t.season_id = target_season_id
  ) then
    raise exception 'Team not found';
  end if;

  select * into target_player
  from __LANE__.players p
  where p.id = target_player_id
  for update;
  if not found then raise exception 'Player not found'; end if;

  select tm.player_id into existing_captain_id
  from __LANE__.team_memberships tm
  where tm.season_id = target_season_id
    and tm.team_id = target_team_id
    and tm.role = 'captain'
    and tm.ends_at is null
  order by tm.starts_at desc
  limit 1
  for update;

  if existing_captain_id = target_player_id then
    select nullif(btrim(pc.phone), '') is not null into target_has_phone
    from __LANE___private.player_contacts pc
    where pc.player_id = target_player_id;
    target_has_phone := coalesce(target_has_phone, false);
    return query select target_team_id, target_player.id, target_player.display_name,
      target_player.user_id is not null, target_has_phone;
    return;
  end if;
  if existing_captain_id is not null then
    raise exception 'Team already has an active captain. Use the captain change workflow.';
  end if;

  select tm.team_id into existing_captain_team_id
  from __LANE__.team_memberships tm
  where tm.season_id = target_season_id
    and tm.player_id = target_player_id
    and tm.role = 'captain'
    and tm.ends_at is null
  limit 1;
  if existing_captain_team_id is not null then
    raise exception 'Player already captains another team in this season';
  end if;

  select nullif(btrim(pc.phone), '') is not null into target_has_phone
  from __LANE___private.player_contacts pc
  where pc.player_id = target_player_id;
  target_has_phone := coalesce(target_has_phone, false);

  if target_season_status in ('active', 'playoffs') and not target_has_phone then
    raise exception 'Phone number is required before assigning an active captain';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = target_player_id
      and tm.ends_at is null
  ) then
    update __LANE__.team_memberships tm
    set role = 'captain'
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = target_player_id
      and tm.ends_at is null;
  else
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(target_season_id, target_team_id, target_player_id, 'captain');
  end if;

  update __LANE___private.season_team_slots sts
  set assigned_captain_player_id = target_player_id,
      updated_at = now()
  where sts.season_id = target_season_id
    and sts.team_id = target_team_id
    and sts.status in ('approved_pending_roster', 'ready', 'confirmed');

  perform __LANE___private.refresh_team_slot_readiness(target_team_id);

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'team.admin_assign_captain',
    'team',
    target_team_id,
    jsonb_build_object(
      'seasonId', target_season_id,
      'playerId', target_player_id,
      'hasLogin', target_player.user_id is not null,
      'hasPhone', target_has_phone
    )
  );

  return query select target_team_id, target_player.id, target_player.display_name,
    target_player.user_id is not null, target_has_phone;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_create_prepared_team(actor_user_id uuid, target_season_id uuid, team_name text)
 RETURNS TABLE(id uuid, season_id uuid, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_season __LANE__.seasons%rowtype;
  normalized_team_name text;
  inserted_team_id uuid;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;

  normalized_team_name := btrim(team_name);
  if normalized_team_name is null or normalized_team_name = '' then
    raise exception 'team_name is required';
  end if;
  if char_length(normalized_team_name) > 80 then
    raise exception 'team_name must be 80 characters or fewer';
  end if;

  select * into target_season
  from __LANE__.seasons s
  where s.id = target_season_id
  for update;
  if not found then raise exception 'Season not found'; end if;
  if target_season.status not in ('draft', 'registration') then
    raise exception 'Teams can only be prepared before season publication';
  end if;

  if exists (
    select 1
    from __LANE__.teams t
    where lower(btrim(t.name)) = lower(normalized_team_name)
  ) then
    raise exception 'A team with this name already exists. Search Returning or New to reuse it.';
  end if;

  insert into __LANE__.teams(season_id, name, created_by)
  values (target_season_id, normalized_team_name, actor_user_id)
  returning __LANE__.teams.id into inserted_team_id;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'team.admin_create_prepared',
    'team',
    inserted_team_id,
    jsonb_build_object(
      'seasonId', target_season_id,
      'teamName', normalized_team_name,
      'captainAssigned', false,
      'slotAssigned', false
    )
  );

  return query
  select t.id, t.season_id, t.name
  from __LANE__.teams t
  where t.id = inserted_team_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_create_unclaimed_player(actor_user_id uuid, target_display_name text, allow_exact_duplicate boolean DEFAULT false)
 RETURNS TABLE(player_id uuid, display_name text, has_login boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cleaned_name text;
  normalized_name text;
  created_player_id uuid;
  existing_name text;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  cleaned_name := btrim(regexp_replace(coalesce(target_display_name, ''), '\s+', ' ', 'g'));
  if char_length(cleaned_name) < 1 then raise exception 'Player name is required'; end if;
  if char_length(cleaned_name) > 80 then raise exception 'Player name must be 80 characters or fewer'; end if;
  normalized_name := lower(cleaned_name);

  select p.display_name into existing_name
  from __LANE__.players p
  where lower(btrim(regexp_replace(p.display_name, '\s+', ' ', 'g'))) = normalized_name
  order by p.created_at, p.id
  limit 1;

  if existing_name is not null and not allow_exact_duplicate then
    raise exception 'A player named "%" already exists. Use the existing player or explicitly confirm a duplicate.', existing_name;
  end if;

  insert into __LANE__.players(user_id, display_name)
  values (null, cleaned_name)
  returning id into created_player_id;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'player.admin_create',
    'player',
    created_player_id,
    jsonb_build_object(
      'displayName', cleaned_name,
      'hasLogin', false,
      'explicitDuplicateOverride', allow_exact_duplicate
    )
  );

  return query
  select created_player_id, cleaned_name, false;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_manage_team_slot(actor_user_id uuid, target_slot_id uuid, slot_action text, action_reason text, extension_days integer DEFAULT NULL::integer)
 RETURNS TABLE(slot_id uuid, slot_status text, hold_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  slot_row __LANE___private.season_team_slots%rowtype;
  minimum_count integer;
  active_count integer;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if slot_action not in ('confirm', 'release', 'extend', 'expire') then
    raise exception 'slot_action must be confirm, release, extend, or expire';
  end if;
  if slot_action in ('release', 'extend', 'expire')
      and nullif(btrim(action_reason), '') is null then
    raise exception 'An audit reason is required';
  end if;

  select * into slot_row
  from __LANE___private.season_team_slots sts
  where sts.id = target_slot_id
  for update;
  if not found then raise exception 'Team slot not found'; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'season_team_capacity:' || slot_row.season_id::text, 0
  ));
  perform __LANE___private.expire_season_team_registration(slot_row.season_id);

  if slot_action = 'confirm' then
    if slot_row.team_id is null then raise exception 'Team slot has no assigned team'; end if;
    select s.minimum_committed_roster into minimum_count
    from __LANE__.seasons s where s.id = slot_row.season_id;
    select count(*)::integer into active_count
    from __LANE__.team_memberships tm
    where tm.team_id = slot_row.team_id and tm.ends_at is null;
    if active_count < minimum_count then
      raise exception 'Team must meet the minimum committed roster before confirmation';
    end if;
    update __LANE___private.season_team_slots
    set status = 'confirmed', resolved_at = now(), updated_at = now()
    where id = target_slot_id and status in ('ready', 'approved_pending_roster');
    if not found then raise exception 'Team slot is not ready for confirmation'; end if;
    update __LANE___private.team_applications
    set status = 'confirmed', updated_at = now()
    where slot_id = target_slot_id;
  elsif slot_action = 'extend' then
    if extension_days is null or extension_days not between 1 and 90 then
      raise exception 'extension_days must be between 1 and 90';
    end if;
    update __LANE___private.season_team_slots
    set hold_expires_at = greatest(coalesce(hold_expires_at, now()), now())
          + make_interval(days => extension_days),
        last_action_reason = btrim(action_reason),
        updated_at = now()
    where id = target_slot_id and status in ('approved_pending_roster', 'ready');
    if not found then raise exception 'Only a roster hold can be extended'; end if;
  else
    update __LANE___private.season_team_slots
    set status = case when slot_action = 'release' then 'released' else 'expired' end,
        resolved_at = now(),
        last_action_reason = btrim(action_reason),
        updated_at = now()
    where id = target_slot_id
      and status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed');
    if not found then raise exception 'Team slot is no longer active'; end if;
    update __LANE___private.team_applications
    set status = case when slot_action = 'release' then 'deferred' else 'expired' end,
        updated_at = now()
    where slot_id = target_slot_id
      and status in ('approved_pending_roster', 'ready', 'confirmed');
  end if;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'team_slot.' || slot_action,
    'season_team_slot',
    target_slot_id,
    jsonb_build_object('reason', nullif(btrim(action_reason), ''), 'extensionDays', extension_days)
  );

  return query
  select sts.id, sts.status, sts.hold_expires_at
  from __LANE___private.season_team_slots sts where sts.id = target_slot_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_override_reconciled_player_match(actor_user_id uuid, target_player_match_id uuid, resolution_reason_text text, resolved_racks jsonb)
 RETURNS TABLE(player_match_id uuid, status text, winner_side text, winner_player_id uuid, score_a integer, score_b integer, finalized_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  finalized_match __LANE__.player_matches%rowtype;
  submission_a __LANE___private.player_match_score_submissions%rowtype;
  submission_b __LANE___private.player_match_score_submissions%rowtype;
  normalized_reason text;
  resolved_score_a integer;
  resolved_score_b integer;
  resolved_winner_side text;
  resolved_winner_player_id uuid;
  canonical_before jsonb;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_player_match_id is null then
    raise exception 'target_player_match_id is required';
  end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  normalized_reason := btrim(coalesce(resolution_reason_text, ''));
  if normalized_reason = '' then
    raise exception 'Resolution reason is required';
  end if;

  if resolved_racks is null
      or jsonb_typeof(resolved_racks) is distinct from 'array'
      or jsonb_array_length(resolved_racks) = 0 then
    raise exception 'Resolved rack history is required';
  end if;

  select *
    into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;

  if not found then
    raise exception 'Player match not found';
  end if;

  if target_match.status in ('finalized', 'corrected') then
    raise exception 'Player match is already finalized';
  end if;

  if target_match.race_to_a is null or target_match.race_to_b is null then
    raise exception 'Race targets are required before finalization';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(resolved_racks) with ordinality as rack(value, ordinality)
    where coalesce(rack.value ->> 'winnerSide', '') not in ('A', 'B')
       or nullif(rack.value ->> 'rackNumber', '')::integer is distinct from rack.ordinality::integer
       or coalesce(rack.value ->> 'discipline', '') is distinct from (
         case
           when rack.ordinality <= target_match.opening_block_length then target_match.opening_discipline
           when target_match.opening_discipline = '8-ball' then '9-ball'
           else '8-ball'
         end
       )
  ) then
    raise exception 'Resolved rack history is invalid';
  end if;

  select
    count(*) filter (where rack.value ->> 'winnerSide' = 'A')::integer,
    count(*) filter (where rack.value ->> 'winnerSide' = 'B')::integer
  into resolved_score_a, resolved_score_b
  from jsonb_array_elements(resolved_racks) as rack(value);

  if resolved_score_a >= target_match.race_to_a
      and resolved_score_b >= target_match.race_to_b then
    raise exception 'Resolved score cannot have both players reach the race target';
  end if;

  if resolved_score_a < target_match.race_to_a
      and resolved_score_b < target_match.race_to_b then
    raise exception 'Race target must be reached before finalization';
  end if;

  if resolved_score_a >= target_match.race_to_a then
    resolved_winner_side := 'A';
    resolved_winner_player_id := target_match.player_a_id;
  else
    resolved_winner_side := 'B';
    resolved_winner_player_id := target_match.player_b_id;
  end if;

  select * into submission_a
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = target_match.player_a_id;

  select * into submission_b
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = target_match.player_b_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rackNumber', pmr.rack_number,
        'discipline', pmr.discipline,
        'winnerSide', pmr.winner_side,
        'winnerPlayerId', pmr.winner_player_id,
        'recordedBy', pmr.recorded_by,
        'recordedAt', pmr.recorded_at
      ) order by pmr.rack_number
    ),
    '[]'::jsonb
  ) into canonical_before
  from __LANE__.player_match_racks pmr
  where pmr.player_match_id = target_player_match_id;

  delete from __LANE__.player_match_racks pmr
  where pmr.player_match_id = target_player_match_id;

  insert into __LANE__.player_match_racks (
    season_id,
    player_match_id,
    rack_number,
    discipline,
    winner_side,
    winner_player_id,
    recorded_by
  )
  select
    target_match.season_id,
    target_player_match_id,
    rack.ordinality::integer,
    rack.value ->> 'discipline',
    rack.value ->> 'winnerSide',
    case when rack.value ->> 'winnerSide' = 'A'
      then target_match.player_a_id else target_match.player_b_id end,
    actor_user_id
  from jsonb_array_elements(resolved_racks) with ordinality as rack(value, ordinality)
  order by rack.ordinality;

  update __LANE__.player_matches
  set score_a = resolved_score_a,
      score_b = resolved_score_b,
      winner_side = resolved_winner_side,
      winner_player_id = resolved_winner_player_id,
      status = 'finalized',
      finalized_by = actor_user_id,
      finalized_at = now()
  where player_matches.id = target_player_match_id
  returning * into finalized_match;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    reason,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'player_match.admin_override_reconciled',
    'player_match',
    target_player_match_id,
    normalized_reason,
    jsonb_build_object(
      'match', to_jsonb(target_match),
      'canonicalRacks', canonical_before,
      'playerASubmission', to_jsonb(submission_a),
      'playerBSubmission', to_jsonb(submission_b)
    ),
    jsonb_build_object(
      'match', to_jsonb(finalized_match),
      'resolvedRacks', resolved_racks
    )
  );

  return query
  select
    finalized_match.id,
    finalized_match.status,
    finalized_match.winner_side,
    finalized_match.winner_player_id,
    finalized_match.score_a,
    finalized_match.score_b,
    finalized_match.finalized_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_propose_team_trade_exception(actor_user_id uuid, actor_team_id uuid, offered_roster_player_id uuid, requested_roster_team_id uuid, requested_roster_player_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, requesting_team_id uuid, requested_team_id uuid, offered_player_id uuid, requested_player_id uuid, status text, admin_exception boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_season_id uuid;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if not exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  if actor_team_id is null or requested_roster_team_id is null then
    raise exception 'Both trade teams are required';
  end if;

  if offered_roster_player_id is null or requested_roster_player_id is null then
    raise exception 'Both trade players are required';
  end if;

  select t.season_id
    into target_season_id
  from __LANE__.teams t
  where t.id = actor_team_id;

  if not found then
    raise exception 'Team not found';
  end if;

  if not exists (
    select 1
    from __LANE__.teams t
    where t.id = requested_roster_team_id
      and t.season_id = target_season_id
  ) then
    raise exception 'Trade teams must be in the same season';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = actor_team_id
      and tm.player_id = offered_roster_player_id
      and tm.role = 'player'
      and tm.ends_at is null
  ) then
    raise exception 'Offered player must be an active non-captain roster member';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = requested_roster_team_id
      and tm.player_id = requested_roster_player_id
      and tm.role = 'player'
      and tm.ends_at is null
  ) then
    raise exception 'Requested player must be an active non-captain roster member';
  end if;

  if exists (
    select 1
    from __LANE___private.team_trades tt
    where tt.season_id = target_season_id
      and tt.status = 'pending'
      and (
        offered_roster_player_id in (tt.offered_player_id, tt.requested_player_id)
        or requested_roster_player_id in (tt.offered_player_id, tt.requested_player_id)
      )
  ) then
    raise exception 'A pending trade already includes one of these players';
  end if;

  return query
  insert into __LANE___private.team_trades (
    season_id,
    requesting_team_id,
    requested_team_id,
    offered_player_id,
    requested_player_id,
    proposed_by_user_id,
    admin_exception
  ) values (
    target_season_id,
    actor_team_id,
    requested_roster_team_id,
    offered_roster_player_id,
    requested_roster_player_id,
    actor_user_id,
    true
  )
  returning
    team_trades.id,
    team_trades.season_id,
    team_trades.requesting_team_id,
    team_trades.requested_team_id,
    team_trades.offered_player_id,
    team_trades.requested_player_id,
    team_trades.status,
    team_trades.admin_exception,
    team_trades.created_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.admin_review_team_application(actor_user_id uuid, target_application_id uuid, review_decision text, review_reason text)
 RETURNS TABLE(application_id uuid, application_status text, team_id uuid, slot_id uuid, hold_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  application_row __LANE___private.team_applications%rowtype;
  target_capacity integer;
  hold_days integer;
  occupied_slots integer;
  inserted_team_id uuid;
  inserted_slot_id uuid;
  target_hold_expires_at timestamptz;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if review_decision not in ('approve', 'defer', 'reject') then
    raise exception 'review_decision must be approve, defer, or reject';
  end if;

  select * into application_row
  from __LANE___private.team_applications ta
  where ta.id = target_application_id
  for update;
  if not found then raise exception 'Team application not found'; end if;
  if application_row.status not in ('applied', 'deferred') then
    raise exception 'Team application is no longer waiting for review';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'season_team_capacity:' || application_row.season_id::text, 0
  ));
  perform __LANE___private.expire_season_team_registration(application_row.season_id);

  if review_decision in ('defer', 'reject') then
    update __LANE___private.team_applications ta
    set status = case when review_decision = 'defer' then 'deferred' else 'rejected' end,
        admin_notes = nullif(btrim(review_reason), ''),
        reviewed_at = now(),
        reviewed_by_user_id = actor_user_id,
        updated_at = now()
    where ta.id = target_application_id;
  else
    select s.team_capacity, s.conditional_hold_days
    into target_capacity, hold_days
    from __LANE__.seasons s
    where s.id = application_row.season_id
      and s.status = 'registration'
    for update;
    if not found then raise exception 'Season is not open for team applications'; end if;

    select count(*)::integer into occupied_slots
    from __LANE___private.season_team_slots sts
    where sts.season_id = application_row.season_id
      and sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed');

    if occupied_slots >= target_capacity then
      raise exception 'No team slots are currently available';
    end if;

    if exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = application_row.season_id
        and tm.player_id = application_row.applicant_player_id
        and tm.role = 'captain'
        and tm.ends_at is null
    ) then
      raise exception 'Applicant already captains a team in this season';
    end if;

    if exists (
      select 1 from __LANE__.teams t
      where t.season_id = application_row.season_id
        and lower(btrim(t.name)) = lower(btrim(application_row.proposed_team_name))
    ) or exists (
      select 1
      from __LANE___private.season_team_slots sts
      join __LANE__.teams source_team on source_team.id = sts.source_team_id
      where sts.season_id = application_row.season_id
        and sts.status in ('reserved', 'transferred')
        and lower(btrim(source_team.name)) = lower(btrim(application_row.proposed_team_name))
    ) then
      raise exception 'That team name is already reserved for this season';
    end if;

    insert into __LANE__.teams(season_id, name, created_by)
    select application_row.season_id, application_row.proposed_team_name, p.user_id
    from __LANE__.players p where p.id = application_row.applicant_player_id
    returning __LANE__.teams.id into inserted_team_id;

    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values (
      application_row.season_id,
      inserted_team_id,
      application_row.applicant_player_id,
      'captain'
    );

    target_hold_expires_at := now() + make_interval(days => hold_days);
    insert into __LANE___private.season_team_slots(
      season_id, team_id, assigned_captain_player_id, status, hold_expires_at
    ) values (
      application_row.season_id,
      inserted_team_id,
      application_row.applicant_player_id,
      'approved_pending_roster',
      target_hold_expires_at
    ) returning __LANE___private.season_team_slots.id into inserted_slot_id;

    update __LANE___private.team_applications ta
    set status = 'approved_pending_roster',
        team_id = inserted_team_id,
        slot_id = inserted_slot_id,
        admin_notes = nullif(btrim(review_reason), ''),
        reviewed_at = now(),
        reviewed_by_user_id = actor_user_id,
        updated_at = now()
    where ta.id = target_application_id;

    perform __LANE___private.refresh_team_slot_readiness(inserted_team_id);
  end if;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'team_application.' || review_decision,
    'team_application',
    target_application_id,
    jsonb_build_object('reason', nullif(btrim(review_reason), ''))
  );

  return query
  select ta.id, ta.status, ta.team_id, ta.slot_id, sts.hold_expires_at
  from __LANE___private.team_applications ta
  left join __LANE___private.season_team_slots sts on sts.id = ta.slot_id
  where ta.id = target_application_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.advance_season_to_championship(target_season_id uuid, actor_user_id uuid)
 RETURNS TABLE(round_id uuid, championship_match_id uuid, championship_team_a_id uuid, championship_team_b_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing_round_id uuid;
  semifinal_round_id uuid;
  created_round_id uuid;
  created_match_id uuid;
  semifinal_match_count integer;
  resolved_semifinal_count integer;
  winner_team_ids uuid[];
begin
  if not exists (select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id) then
    raise exception 'Actor is not a league admin';
  end if;
  if not exists (select 1 from __LANE__.seasons s where s.id = target_season_id) then
    raise exception 'Season not found';
  end if;

  perform 1 from __LANE__.seasons s where s.id = target_season_id for update;

  select r.id into existing_round_id
  from __LANE__.rounds r
  where r.season_id = target_season_id and r.stage = 'championship'
  order by r.round_number limit 1;
  if existing_round_id is not null then
    return query
      select existing_round_id, tm.id, tm.team_a_id, tm.team_b_id
      from __LANE__.team_matches tm where tm.round_id = existing_round_id
      order by tm.table_number limit 1;
    return;
  end if;

  select r.id into semifinal_round_id
  from __LANE__.rounds r
  where r.season_id = target_season_id and r.stage = 'semifinal'
  order by r.round_number limit 1;
  if semifinal_round_id is null then raise exception 'Semifinals must be started before the championship'; end if;

  select count(*)::integer,
         count(*) filter (where tm.status = 'finalized' and tm.winner_team_id is not null)::integer,
         array_agg(tm.winner_team_id order by tm.table_number)
  into semifinal_match_count, resolved_semifinal_count, winner_team_ids
  from __LANE__.team_matches tm
  where tm.round_id = semifinal_round_id;

  if semifinal_match_count <> 2 then raise exception 'Exactly two semifinal team matchups are required'; end if;
  if resolved_semifinal_count <> 2 then
    raise exception 'Both semifinals must be finalized, including any required anchor tiebreaker';
  end if;
  if winner_team_ids[1] is null or winner_team_ids[2] is null or winner_team_ids[1] = winner_team_ids[2] then
    raise exception 'Two distinct semifinal winners are required';
  end if;

  update __LANE__.rounds set status = 'finalized' where id = semifinal_round_id;

  insert into __LANE__.rounds (season_id, round_number, stage, status)
  values (target_season_id, 9, 'championship', 'scheduled')
  returning id into created_round_id;

  insert into __LANE__.team_matches (
    season_id, round_id, table_number, team_a_id, team_b_id, status
  ) values (
    target_season_id, created_round_id, 1, winner_team_ids[1], winner_team_ids[2], 'scheduled'
  ) returning id into created_match_id;

  return query select created_round_id, created_match_id, winner_team_ids[1], winner_team_ids[2];
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.approve_team_trade_captain(actor_user_id uuid, target_trade_id uuid, response_status text)
 RETURNS TABLE(id uuid, season_id uuid, status text, requesting_captain_approved_at timestamp with time zone, requested_captain_approved_at timestamp with time zone, declined_at timestamp with time zone, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  trade __LANE___private.team_trades%rowtype;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_trade_id is null then
    raise exception 'target_trade_id is required';
  end if;

  if response_status not in ('approved', 'declined') then
    raise exception 'response_status must be approved or declined';
  end if;

  select *
    into trade
  from __LANE___private.team_trades tt
  where tt.id = target_trade_id
  for update;

  if not found then
    raise exception 'Trade not found';
  end if;

  if trade.status <> 'pending' then
    raise exception 'Trade is no longer pending';
  end if;

  if not __LANE___private.actor_captains_team(actor_user_id, trade.requesting_team_id)
      and not __LANE___private.actor_captains_team(actor_user_id, trade.requested_team_id) then
    raise exception 'Only an active captain for a trade team can approve';
  end if;

  if response_status = 'declined' then
    update __LANE___private.team_trades
    set status = 'declined',
        declined_by_user_id = actor_user_id,
        declined_at = now()
    where team_trades.id = target_trade_id;
  elsif __LANE___private.actor_captains_team(actor_user_id, trade.requesting_team_id) then
    update __LANE___private.team_trades
    set requesting_captain_approved_at = coalesce(requesting_captain_approved_at, now())
    where team_trades.id = target_trade_id;
  else
    update __LANE___private.team_trades
    set requested_captain_approved_at = coalesce(requested_captain_approved_at, now())
    where team_trades.id = target_trade_id;
  end if;

  if response_status = 'approved' then
    perform __LANE___private.complete_team_trade_if_ready(target_trade_id);
  end if;

  return query
  select
    tt.id,
    tt.season_id,
    tt.status,
    tt.requesting_captain_approved_at,
    tt.requested_captain_approved_at,
    tt.declined_at,
    tt.completed_at
  from __LANE___private.team_trades tt
  where tt.id = target_trade_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.block_player_chat(actor_user_id uuid, target_player_id uuid)
 RETURNS TABLE(blocked_player_id uuid, blocked_display_name text, blocked_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_player __LANE__.players%rowtype;
  saved_block __LANE__.player_chat_blocks%rowtype;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  select p.* into target_player
  from __LANE__.players p
  where p.id = target_player_id;
  if target_player.id is null then raise exception 'Player not found'; end if;
  if target_player.id = actor_player_id then raise exception 'Cannot block yourself'; end if;

  insert into __LANE__.player_chat_blocks (blocker_player_id, blocked_player_id)
  values (actor_player_id, target_player.id)
  on conflict on constraint player_chat_blocks_pkey
  do update set blocker_player_id = excluded.blocker_player_id
  returning * into saved_block;

  return query
  select saved_block.blocked_player_id, target_player.display_name, saved_block.created_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.cancel_captaincy_transfer(actor_user_id uuid, target_transfer_id uuid)
 RETURNS TABLE(id uuid, status text, resolved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_player_id uuid; transfer_row __LANE___private.captaincy_transfers%rowtype;
begin
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id;
if not found then raise exception 'Player profile is required'; end if;
select * into transfer_row from __LANE___private.captaincy_transfers ct where ct.id=target_transfer_id for update;
if not found then raise exception 'Captaincy transfer not found'; end if;
if transfer_row.status<>'pending' then raise exception 'Captaincy transfer is no longer pending'; end if;
if transfer_row.from_player_id<>actor_player_id then raise exception 'Only the current captain can cancel this transfer'; end if;
update __LANE___private.captaincy_transfers set status='cancelled',resolved_at=now() where __LANE___private.captaincy_transfers.id=target_transfer_id;
return query select ct.id,ct.status,ct.resolved_at from __LANE___private.captaincy_transfers ct where ct.id=target_transfer_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.cancel_team_invitation(actor_user_id uuid, target_invitation_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, invited_player_id uuid, status text, responded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare invitation __LANE___private.team_invitations%rowtype; actor_player_id uuid;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_invitation_id is null then raise exception 'target_invitation_id is required'; end if;
select * into invitation from __LANE___private.team_invitations ti where ti.id=target_invitation_id for update;
if not found then raise exception 'Invitation not found'; end if;
if invitation.status<>'pending' then raise exception 'Only pending invitations can be canceled'; end if;
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id;
if not found then raise exception 'Player profile is required before canceling invitations'; end if;
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=invitation.team_id and tm.player_id=actor_player_id and tm.role='captain' and tm.ends_at is null) then raise exception 'Only the active captain can cancel invitations'; end if;
update __LANE___private.team_invitations set status='canceled',responded_at=now() where team_invitations.id=target_invitation_id;
return query select ti.id,ti.season_id,ti.team_id,ti.invited_player_id,ti.status,ti.responded_at from __LANE___private.team_invitations ti where ti.id=target_invitation_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.cancel_team_membership_request(actor_user_id uuid, target_request_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, player_id uuid, status text, resolved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare request_row __LANE___private.team_membership_requests%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_request_id is null then raise exception 'target_request_id is required'; end if;
  select * into request_row from __LANE___private.team_membership_requests r where r.id=target_request_id for update;
  if not found then raise exception 'Membership request not found'; end if;
  if request_row.status <> 'pending' then raise exception 'Membership request is no longer pending'; end if;
  if not exists (select 1 from __LANE__.players p where p.id=request_row.player_id and p.user_id=actor_user_id) then raise exception 'Only the requesting player can cancel this membership request'; end if;
  update __LANE___private.team_membership_requests set status='cancelled',resolved_at=now(),resolved_by_user_id=actor_user_id where __LANE___private.team_membership_requests.id=target_request_id;
  return query select r.id,r.season_id,r.team_id,r.player_id,r.status,r.resolved_at from __LANE___private.team_membership_requests r where r.id=target_request_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.choose_team_match_team(actor_user_id uuid, target_team_match_id uuid, target_team_id uuid)
 RETURNS TABLE(team_match_id uuid, player_id uuid, team_id uuid, chosen_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_match __LANE__.team_matches%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_match_id is null then raise exception 'target_team_match_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before choosing a team'; end if;

  select * into target_match
  from __LANE__.team_matches tm
  where tm.id = target_team_match_id
  for update;
  if not found then raise exception 'Team matchup not found'; end if;

  if target_team_id not in (target_match.team_a_id, target_match.team_b_id) then
    raise exception 'Selected team is not part of this team matchup';
  end if;

  if not exists (
    select 1 from __LANE__.team_memberships member_a
    where member_a.season_id = target_match.season_id
      and member_a.team_id = target_match.team_a_id
      and member_a.player_id = actor_player_id
      and member_a.ends_at is null
  ) or not exists (
    select 1 from __LANE__.team_memberships member_b
    where member_b.season_id = target_match.season_id
      and member_b.team_id = target_match.team_b_id
      and member_b.player_id = actor_player_id
      and member_b.ends_at is null
  ) then
    raise exception 'You must be an active member of both teams to choose a side for this matchup';
  end if;

  if exists (
    select 1
    from __LANE___private.team_lineups lineup
    join __LANE___private.team_lineup_slots slot on slot.lineup_id = lineup.id
    where lineup.team_match_id = target_team_match_id
      and slot.player_id = actor_player_id
  ) then
    raise exception 'Team choice is locked after a lineup includes you';
  end if;

  insert into __LANE___private.team_match_player_choices (
    team_match_id, player_id, team_id
  ) values (
    target_team_match_id, actor_player_id, target_team_id
  )
  on conflict on constraint team_match_player_choices_pkey do update
    set team_id = excluded.team_id,
        updated_at = now();

  return query
  select choice.team_match_id, choice.player_id, choice.team_id,
         choice.chosen_at, choice.updated_at
  from __LANE___private.team_match_player_choices choice
  where choice.team_match_id = target_team_match_id
    and choice.player_id = actor_player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.claim_unclaimed_player(actor_user_id uuid, target_player_id uuid)
 RETURNS TABLE(player_id uuid, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_player __LANE__.players%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'player_self_claim_actor:' || actor_user_id::text,
    0
  ));

  select * into target_player
  from __LANE__.players p
  where p.id = target_player_id
  for update;

  if not found then raise exception 'Player not found'; end if;
  if target_player.user_id is not null then
    raise exception 'Player is already claimed';
  end if;

  if exists (
    select 1 from __LANE__.players owned where owned.user_id = actor_user_id
  ) then
    raise exception 'You already have a player profile';
  end if;

  if exists (
    select 1
    from __LANE__.player_matches pm
    where (pm.player_a_id = target_player_id or pm.player_b_id = target_player_id)
      and (
        exists (
          select 1
          from __LANE__.player_match_racks rack
          where rack.player_match_id = pm.id
        )
        or exists (
          select 1
          from __LANE___private.player_match_score_submissions submission
          where submission.player_match_id = pm.id
            and jsonb_array_length(coalesce(submission.racks, '[]'::jsonb)) > 0
        )
      )
  ) then
    raise exception 'Player has game history and cannot be self-claimed';
  end if;

  update __LANE__.players
  set user_id = actor_user_id,
      updated_at = now()
  where id = target_player_id;

  insert into __LANE___private.audit_events(
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'player.self_claim',
    'player',
    target_player_id,
    jsonb_build_object('hasLogin', false),
    jsonb_build_object('hasLogin', true)
  );

  return query
  select p.id, p.display_name
  from __LANE__.players p
  where p.id = target_player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.close_season(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(season_id uuid, season_status text, closed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare readiness record; effective_closed_at timestamptz := now();
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  perform 1 from __LANE__.seasons s where s.id = target_season_id for update;
  if not found then raise exception 'Season not found'; end if;
  select * into readiness from __LANE__.get_season_close_readiness(actor_user_id,target_season_id);
  if readiness.season_status = 'complete' then return query select target_season_id,'complete'::text,effective_closed_at; return; end if;
  if not readiness.ready then raise exception '%', readiness.reason; end if;
  perform set_config('fremont.explicit_season_close','on',true);
  update __LANE__.seasons set status='complete',updated_at=effective_closed_at where id=target_season_id;
  insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,after_state) values(actor_user_id,'season.close','season',target_season_id,jsonb_build_object('status','complete','closedAt',effective_closed_at,'championshipFinalized',readiness.championship_finalized,'unresolvedPostseasonMatches',readiness.unresolved_postseason_matches,'unresolvedPlayerMatches',readiness.unresolved_player_matches));
  return query select target_season_id,'complete'::text,effective_closed_at;
end;$function$;


CREATE OR REPLACE FUNCTION __LANE__.configure_season_prizes(actor_user_id uuid, target_season_id uuid, configured_entry_fee_cents integer, configured_administration_amount_cents integer, configured_team_allocation_basis_points integer, configured_individual_allocation_basis_points integer, configured_projected_field_size integer, payout_templates jsonb)
 RETURNS TABLE(configuration_id uuid, season_id uuid, version integer, entry_fee_cents integer, administration_amount_cents integer, team_allocation_basis_points integer, individual_allocation_basis_points integer, projected_field_size integer, projected_gross_cents integer, projected_prize_pool_cents integer, team_prize_pool_cents integer, individual_prize_pool_cents integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  next_version integer;
  inserted_configuration_id uuid;
  previous_configuration jsonb;
  projected_gross integer;
  projected_prize_pool integer;
  payout_item jsonb;
  payout_pool text;
  payout_place integer;
  payout_label text;
  payout_basis_points integer;
  team_template_total integer := 0;
  individual_template_total integer := 0;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_season_id is null then
    raise exception 'target_season_id is required';
  end if;

  if not exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  perform 1
  from __LANE__.seasons s
  where s.id = target_season_id
  for update;

  if not found then
    raise exception 'Season not found';
  end if;

  if configured_entry_fee_cents is null or configured_entry_fee_cents < 0 then
    raise exception 'entry_fee_cents must be zero or greater';
  end if;

  if configured_administration_amount_cents is null or configured_administration_amount_cents < 0 then
    raise exception 'administration_amount_cents must be zero or greater';
  end if;

  if configured_projected_field_size is null or configured_projected_field_size <= 0 then
    raise exception 'projected_field_size must be greater than zero';
  end if;

  if configured_team_allocation_basis_points is null
      or configured_individual_allocation_basis_points is null
      or configured_team_allocation_basis_points < 0
      or configured_individual_allocation_basis_points < 0
      or configured_team_allocation_basis_points + configured_individual_allocation_basis_points <> 10000 then
    raise exception 'Prize allocations must total 10000 basis points';
  end if;

  projected_gross := configured_entry_fee_cents * configured_projected_field_size;
  if configured_administration_amount_cents > projected_gross then
    raise exception 'administration_amount_cents cannot exceed projected gross';
  end if;

  if jsonb_typeof(payout_templates) is distinct from 'array' then
    raise exception 'payout_templates must be an array';
  end if;

  for payout_item in
    select value from jsonb_array_elements(payout_templates)
  loop
    if jsonb_typeof(payout_item) is distinct from 'object' then
      raise exception 'Each payout template must be an object';
    end if;

    payout_pool := payout_item ->> 'pool';
    payout_place := nullif(payout_item ->> 'place', '')::integer;
    payout_label := btrim(coalesce(payout_item ->> 'label', ''));
    payout_basis_points := coalesce(
      nullif(payout_item ->> 'allocationBasisPoints', '')::integer,
      nullif(payout_item ->> 'allocation_basis_points', '')::integer
    );

    if payout_pool not in ('team', 'individual') then
      raise exception 'Payout template pool must be team or individual';
    end if;

    if payout_place is null or payout_place <= 0 then
      raise exception 'Payout template place must be greater than zero';
    end if;

    if payout_label is null or char_length(payout_label) = 0 or char_length(payout_label) > 80 then
      raise exception 'Payout template label must be 80 characters or fewer';
    end if;

    if payout_basis_points is null or payout_basis_points < 0 or payout_basis_points > 10000 then
      raise exception 'Payout template allocation must be between 0 and 10000 basis points';
    end if;

    if payout_pool = 'team' then
      team_template_total := team_template_total + payout_basis_points;
    else
      individual_template_total := individual_template_total + payout_basis_points;
    end if;
  end loop;

  if team_template_total <> 10000 then
    raise exception 'Team payout templates must total 10000 basis points';
  end if;

  if individual_template_total <> 10000 then
    raise exception 'Individual payout templates must total 10000 basis points';
  end if;

  select to_jsonb(spc)
    into previous_configuration
  from __LANE__.season_prize_configurations spc
  where spc.season_id = target_season_id
  order by spc.version desc
  limit 1;

  select coalesce(max(spc.version), 0) + 1
    into next_version
  from __LANE__.season_prize_configurations spc
  where spc.season_id = target_season_id;

  insert into __LANE__.season_prize_configurations (
    season_id,
    version,
    entry_fee_cents,
    administration_amount_cents,
    team_allocation_basis_points,
    individual_allocation_basis_points,
    projected_field_size,
    created_by
  ) values (
    target_season_id,
    next_version,
    configured_entry_fee_cents,
    configured_administration_amount_cents,
    configured_team_allocation_basis_points,
    configured_individual_allocation_basis_points,
    configured_projected_field_size,
    actor_user_id
  )
  returning season_prize_configurations.id into inserted_configuration_id;

  for payout_item in
    select value from jsonb_array_elements(payout_templates)
  loop
    insert into __LANE__.season_prize_payout_templates (
      configuration_id,
      pool,
      place,
      label,
      allocation_basis_points
    ) values (
      inserted_configuration_id,
      payout_item ->> 'pool',
      nullif(payout_item ->> 'place', '')::integer,
      btrim(coalesce(payout_item ->> 'label', '')),
      coalesce(
        nullif(payout_item ->> 'allocationBasisPoints', '')::integer,
        nullif(payout_item ->> 'allocation_basis_points', '')::integer
      )
    );
  end loop;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'season.configure_prizes',
    'season',
    target_season_id,
    previous_configuration,
    jsonb_build_object(
      'configurationId', inserted_configuration_id,
      'version', next_version,
      'projectedFieldSize', configured_projected_field_size
    )
  );

  projected_prize_pool := greatest(projected_gross - configured_administration_amount_cents, 0);

  return query
  select
    spc.id,
    spc.season_id,
    spc.version,
    spc.entry_fee_cents,
    spc.administration_amount_cents,
    spc.team_allocation_basis_points,
    spc.individual_allocation_basis_points,
    spc.projected_field_size,
    projected_gross,
    projected_prize_pool,
    round(projected_prize_pool::numeric * spc.team_allocation_basis_points::numeric / 10000)::integer,
    round(projected_prize_pool::numeric * spc.individual_allocation_basis_points::numeric / 10000)::integer,
    spc.created_at
  from __LANE__.season_prize_configurations spc
  where spc.id = inserted_configuration_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.configure_season_registration(actor_user_id uuid, target_season_id uuid, configured_team_capacity integer, configured_minimum_committed_roster integer, configured_returning_reservation_deadline timestamp with time zone, configured_conditional_hold_days integer)
 RETURNS TABLE(season_id uuid, team_capacity integer, minimum_committed_roster integer, returning_reservation_deadline timestamp with time zone, conditional_hold_days integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if configured_team_capacity not between 2 and 32 then
    raise exception 'team_capacity must be between 2 and 32';
  end if;
  if configured_minimum_committed_roster not between 1 and 20 then
    raise exception 'minimum_committed_roster must be between 1 and 20';
  end if;
  if configured_conditional_hold_days not between 1 and 90 then
    raise exception 'conditional_hold_days must be between 1 and 90';
  end if;

  update __LANE__.seasons s
  set team_capacity = configured_team_capacity,
      minimum_committed_roster = configured_minimum_committed_roster,
      returning_reservation_deadline = configured_returning_reservation_deadline,
      conditional_hold_days = configured_conditional_hold_days,
      updated_at = now()
  where s.id = target_season_id
    and s.status in ('draft', 'registration');

  if not found then
    if exists (select 1 from __LANE__.seasons s where s.id = target_season_id) then
      raise exception 'Season registration settings can only change before publication';
    end if;
    raise exception 'Season not found';
  end if;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'season.configure_registration',
    'season',
    target_season_id,
    jsonb_build_object(
      'teamCapacity', configured_team_capacity,
      'minimumCommittedRoster', configured_minimum_committed_roster,
      'returningReservationDeadline', configured_returning_reservation_deadline,
      'conditionalHoldDays', configured_conditional_hold_days
    )
  );

  return query
  select s.id, s.team_capacity, s.minimum_committed_roster,
         s.returning_reservation_deadline, s.conditional_hold_days
  from __LANE__.seasons s where s.id = target_season_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.configure_season_setup(actor_user_id uuid, target_season_id uuid, configured_season_name text, configured_league_night text, configured_first_round_date date, configured_roster_lock_round integer, configured_opening_block_length integer, configured_individual_min_matches integer, configured_round_interval_days integer, configured_table_numbers integer[], configured_race_chart_version text, configured_playoff_team_count integer, configured_playoff_anchor_tiebreaker boolean)
 RETURNS TABLE(id uuid, name text, status text, league_night text, first_round_date date, roster_lock_round integer, opening_block_length integer, individual_min_matches integer, round_interval_days integer, default_table_numbers integer[], race_chart_version text, playoff_team_count integer, playoff_anchor_tiebreaker boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_name text;
  normalized_league_night text;
  normalized_race_chart_version text;
  before_state jsonb;
  configured_id uuid;
  registration_season_count integer;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if not exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  normalized_name := btrim(configured_season_name);
  if normalized_name is null or char_length(normalized_name) = 0 or char_length(normalized_name) > 80 then
    raise exception 'season_name must be 80 characters or fewer';
  end if;

  normalized_league_night := btrim(configured_league_night);
  if normalized_league_night is null or char_length(normalized_league_night) = 0 or char_length(normalized_league_night) > 40 then
    raise exception 'league_night must be 40 characters or fewer';
  end if;

  normalized_race_chart_version := btrim(configured_race_chart_version);
  if normalized_race_chart_version is null
      or char_length(normalized_race_chart_version) = 0
      or char_length(normalized_race_chart_version) > 80 then
    raise exception 'race_chart_version must be 80 characters or fewer';
  end if;

  if configured_first_round_date is null then
    raise exception 'first_round_date is required';
  end if;

  if configured_roster_lock_round is null or configured_roster_lock_round < 1 then
    raise exception 'roster_lock_round must be greater than zero';
  end if;

  if configured_opening_block_length is null or configured_opening_block_length < 1 then
    raise exception 'opening_block_length must be greater than zero';
  end if;

  if configured_individual_min_matches is null or configured_individual_min_matches < 1 then
    raise exception 'individual_min_matches must be greater than zero';
  end if;

  if configured_round_interval_days is null or configured_round_interval_days < 1 then
    raise exception 'round_interval_days must be greater than zero';
  end if;

  if not __LANE___private.validate_season_setup_table_numbers(configured_table_numbers) then
    raise exception 'table_numbers must contain four unique positive integers';
  end if;

  if configured_playoff_team_count is null or configured_playoff_team_count < 2 then
    raise exception 'playoff_team_count must be at least two';
  end if;

  if target_season_id is null then
    lock table __LANE__.seasons in share row exclusive mode;

    select count(*)::integer
      into registration_season_count
    from __LANE__.seasons s
    where s.status = 'registration';

    if registration_season_count > 1 then
      raise exception 'Multiple registration seasons exist; choose a season before saving setup';
    end if;

    if registration_season_count = 1 then
      select s.id
        into target_season_id
      from __LANE__.seasons s
      where s.status = 'registration'
      limit 1;
    end if;
  end if;

  if target_season_id is null then
    insert into __LANE__.seasons (
      name,
      status,
      roster_lock_round,
      opening_block_length,
      individual_min_matches,
      league_night,
      first_round_date,
      round_interval_days,
      default_table_numbers,
      race_chart_version,
      playoff_team_count,
      playoff_anchor_tiebreaker,
      updated_at
    ) values (
      normalized_name,
      'registration',
      configured_roster_lock_round,
      configured_opening_block_length,
      configured_individual_min_matches,
      normalized_league_night,
      configured_first_round_date,
      configured_round_interval_days,
      configured_table_numbers,
      normalized_race_chart_version,
      configured_playoff_team_count,
      coalesce(configured_playoff_anchor_tiebreaker, true),
      now()
    )
    returning seasons.id into configured_id;
  else
    select to_jsonb(s)
      into before_state
    from __LANE__.seasons s
    where s.id = target_season_id
    for update;

    if not found then
      raise exception 'Season not found';
    end if;

    if not exists (
      select 1
      from __LANE__.seasons s
      where s.id = target_season_id
        and s.status in ('draft', 'registration')
    ) then
      raise exception 'Season setup can only change before publication';
    end if;

    update __LANE__.seasons
    set name = normalized_name,
        roster_lock_round = configured_roster_lock_round,
        opening_block_length = configured_opening_block_length,
        individual_min_matches = configured_individual_min_matches,
        league_night = normalized_league_night,
        first_round_date = configured_first_round_date,
        round_interval_days = configured_round_interval_days,
        default_table_numbers = configured_table_numbers,
        race_chart_version = normalized_race_chart_version,
        playoff_team_count = configured_playoff_team_count,
        playoff_anchor_tiebreaker = coalesce(configured_playoff_anchor_tiebreaker, true),
        updated_at = now()
    where seasons.id = target_season_id
    returning seasons.id into configured_id;
  end if;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  )
  select
    actor_user_id,
    'season.configure_setup',
    'season',
    s.id,
    before_state,
    to_jsonb(s)
  from __LANE__.seasons s
  where s.id = configured_id;

  return query
  select
    s.id,
    s.name,
    s.status,
    s.league_night,
    s.first_round_date,
    s.roster_lock_round,
    s.opening_block_length,
    s.individual_min_matches,
    s.round_interval_days,
    s.default_table_numbers,
    s.race_chart_version,
    s.playoff_team_count,
    s.playoff_anchor_tiebreaker,
    s.updated_at
  from __LANE__.seasons s
  where s.id = configured_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.confirm_player_match_score(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, confirmed_at timestamp with time zone, histories_match boolean, both_confirmed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target_match __LANE__.player_matches%rowtype; tracker_id uuid; submission __LANE___private.player_match_score_submissions%rowtype; opponent_submission __LANE___private.player_match_score_submissions%rowtype; next_score_a integer; next_score_b integer; confirmed_time timestamptz; begin select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update; if not found then raise exception 'Player match not found'; end if; if target_match.status in ('finalized','corrected') then raise exception 'Player match is finalized'; end if; tracker_id:=__LANE___private.match_tracker_for_scoring_team(actor_user_id,target_match,target_scoring_team_id); select * into submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=tracker_id for update; if not found or jsonb_array_length(submission.racks)=0 then raise exception 'Score record is empty'; end if; select count(*) filter(where elem->>'winnerSide'='A')::integer,count(*) filter(where elem->>'winnerSide'='B')::integer into next_score_a,next_score_b from jsonb_array_elements(submission.racks) elem; if next_score_a<target_match.race_to_a and next_score_b<target_match.race_to_b then raise exception 'Race target must be reached before confirmation'; end if; confirmed_time:=now(); update __LANE___private.player_match_score_submissions set confirmed_at=confirmed_time,updated_at=confirmed_time where id=submission.id returning * into submission; select * into opponent_submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id<>tracker_id limit 1; insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.team_score_confirm','player_match',target_player_match_id,jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id),jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id,'confirmedAt',confirmed_time)); return query select target_player_match_id,target_scoring_team_id,tracker_id,confirmed_time,(opponent_submission.id is not null and opponent_submission.racks=submission.racks),(opponent_submission.confirmed_at is not null and submission.confirmed_at is not null); end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.confirm_player_match_score_checked(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, expected_racks jsonb)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, confirmed_at timestamp with time zone, histories_match boolean, both_confirmed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
begin
  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );
  perform __LANE___private.assert_expected_score_history(
    target_player_match_id,
    tracker_id,
    expected_racks
  );

  return query
  select * from __LANE__.confirm_player_match_score(
    actor_user_id,
    target_player_match_id,
    target_scoring_team_id
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.correct_player_match(actor_user_id uuid, target_player_match_id uuid, corrected_winner_side text, corrected_score_a integer, corrected_score_b integer, correction_reason_text text, corrected_racks jsonb)
 RETURNS TABLE(player_match_id uuid, status text, winner_side text, winner_player_id uuid, score_a integer, score_b integer, corrected_at timestamp with time zone, corrected_by uuid, correction_reason text, racks jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  corrected_match __LANE__.player_matches%rowtype;
  normalized_reason text;
  rack_count_a integer;
  rack_count_b integer;
  before_racks jsonb;
  after_racks jsonb;
  corrected_current_discipline text;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  if not exists (select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id) then raise exception 'Actor is not a league admin'; end if;
  normalized_reason := btrim(coalesce(correction_reason_text, ''));
  if normalized_reason = '' then raise exception 'Correction reason is required'; end if;
  if corrected_winner_side not in ('A', 'B') then raise exception 'corrected_winner_side must be A or B'; end if;
  if corrected_score_a is null or corrected_score_a < 0 or corrected_score_b is null or corrected_score_b < 0 then raise exception 'Corrected scores must be non-negative'; end if;
  if corrected_racks is null or jsonb_typeof(corrected_racks) is distinct from 'array' then raise exception 'corrected_racks must be an array'; end if;
  if jsonb_array_length(corrected_racks) = 0 then raise exception 'corrected_racks must not be empty'; end if;
  if jsonb_array_length(corrected_racks) <> corrected_score_a + corrected_score_b then raise exception 'Corrected rack history must match corrected score'; end if;
  if exists (select 1 from (select coalesce(rack_item.value ->> 'winnerSide', rack_item.value ->> 'winner_side') as winner_side from jsonb_array_elements(corrected_racks) as rack_item(value)) parsed_racks where parsed_racks.winner_side is null or parsed_racks.winner_side not in ('A', 'B')) then raise exception 'Corrected rack winnerSide must be A or B'; end if;
  select (count(*) filter (where parsed_racks.winner_side = 'A'))::integer,(count(*) filter (where parsed_racks.winner_side = 'B'))::integer into rack_count_a, rack_count_b from (select coalesce(rack_item.value ->> 'winnerSide', rack_item.value ->> 'winner_side') as winner_side from jsonb_array_elements(corrected_racks) as rack_item(value)) parsed_racks;
  if rack_count_a <> corrected_score_a or rack_count_b <> corrected_score_b then raise exception 'Corrected rack history must match corrected score'; end if;
  select * into target_match from __LANE__.player_matches pm where pm.id = target_player_match_id for update;
  if not found then raise exception 'Player match not found'; end if;
  if target_match.status not in ('finalized', 'corrected') then raise exception 'Player match must be finalized before correction'; end if;
  if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before correction'; end if;
  if corrected_winner_side = 'A' and (corrected_score_a < target_match.race_to_a or corrected_score_b >= target_match.race_to_b) then raise exception 'Player match is not in a valid corrected race state'; end if;
  if corrected_winner_side = 'B' and (corrected_score_b < target_match.race_to_b or corrected_score_a >= target_match.race_to_a) then raise exception 'Player match is not in a valid corrected race state'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('rackNumber', pmr.rack_number,'discipline', pmr.discipline,'winnerSide', pmr.winner_side,'winnerPlayerId', pmr.winner_player_id,'recordedBy', pmr.recorded_by,'recordedAt', pmr.recorded_at) order by pmr.rack_number),'[]'::jsonb) into before_racks from __LANE__.player_match_racks pmr where pmr.player_match_id = target_player_match_id;
  delete from __LANE__.player_match_racks pmr where pmr.player_match_id = target_player_match_id;
  insert into __LANE__.player_match_racks (season_id,player_match_id,rack_number,discipline,winner_side,winner_player_id,recorded_by)
  select target_match.season_id,target_player_match_id,parsed_racks.rack_number,case when parsed_racks.rack_number <= target_match.opening_block_length then target_match.opening_discipline when target_match.opening_discipline = '8-ball' then '9-ball' else '8-ball' end,parsed_racks.winner_side,case when parsed_racks.winner_side = 'A' then target_match.player_a_id else target_match.player_b_id end,actor_user_id
  from (select rack_item.ordinality::integer as rack_number,coalesce(rack_item.value ->> 'winnerSide', rack_item.value ->> 'winner_side') as winner_side from jsonb_array_elements(corrected_racks) with ordinality as rack_item(value, ordinality)) parsed_racks order by parsed_racks.rack_number;
  corrected_current_discipline := case when jsonb_array_length(corrected_racks) <= target_match.opening_block_length then target_match.opening_discipline when target_match.opening_discipline = '8-ball' then '9-ball' else '8-ball' end;
  update __LANE__.player_matches set score_a = corrected_score_a,score_b = corrected_score_b,current_discipline = corrected_current_discipline,winner_side = corrected_winner_side,winner_player_id = case when corrected_winner_side = 'A' then target_match.player_a_id else target_match.player_b_id end,status = 'corrected',corrected_by = actor_user_id,corrected_at = now(),correction_reason = normalized_reason where player_matches.id = target_player_match_id returning * into corrected_match;
  select coalesce(jsonb_agg(jsonb_build_object('rackNumber', pmr.rack_number,'discipline', pmr.discipline,'winnerSide', pmr.winner_side,'winnerPlayerId', pmr.winner_player_id,'recordedBy', pmr.recorded_by,'recordedAt', pmr.recorded_at) order by pmr.rack_number),'[]'::jsonb) into after_racks from __LANE__.player_match_racks pmr where pmr.player_match_id = target_player_match_id;
  insert into __LANE___private.audit_events (actor_user_id,action,entity_type,entity_id,reason,before_state,after_state) values (actor_user_id,'player_match.correct','player_match',target_player_match_id,normalized_reason,jsonb_build_object('match', to_jsonb(target_match),'racks', before_racks),jsonb_build_object('match', to_jsonb(corrected_match),'racks', after_racks));
  return query select corrected_match.id,corrected_match.status,corrected_match.winner_side,corrected_match.winner_player_id,corrected_match.score_a,corrected_match.score_b,corrected_match.corrected_at,corrected_match.corrected_by,corrected_match.correction_reason,after_racks;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.create_team_with_captain(actor_user_id uuid, target_season_id uuid, team_name text)
 RETURNS TABLE(id uuid, season_id uuid, name text, captain_player_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  raise exception 'New teams must apply for a season slot before a team is created';
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.edit_player_match_score_rack(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, target_rack_number integer, rack_winner_side text)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, old_winner_side text, new_winner_side text, score_a integer, score_b integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
  submission __LANE___private.player_match_score_submissions%rowtype;
  old_rack jsonb;
  old_side text;
  next_racks jsonb;
  next_score_a integer;
  next_score_b integer;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  if target_scoring_team_id is null then raise exception 'target_scoring_team_id is required'; end if;
  if target_rack_number is null or target_rack_number < 1 then raise exception 'rack_number must be positive'; end if;
  if rack_winner_side not in ('A', 'B') then raise exception 'rack_winner_side must be A or B'; end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;
  if target_match.status in ('finalized', 'corrected') then
    raise exception 'Player match is finalized; use the league-admin correction workflow';
  end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );

  select * into submission
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = tracker_id
  for update;
  if not found then raise exception 'Your team has no score record for this match'; end if;
  if target_rack_number > jsonb_array_length(coalesce(submission.racks, '[]'::jsonb)) then
    raise exception 'Rack is not present in your team score record';
  end if;

  old_rack := submission.racks -> (target_rack_number - 1);
  old_side := old_rack ->> 'winnerSide';
  if old_side is null then raise exception 'Rack winner is missing from your team score record'; end if;

  next_racks := jsonb_set(
    submission.racks,
    array[(target_rack_number - 1)::text, 'winnerSide'],
    to_jsonb(rack_winner_side),
    false
  );

  select
    count(*) filter (where elem ->> 'winnerSide' = 'A')::integer,
    count(*) filter (where elem ->> 'winnerSide' = 'B')::integer
  into next_score_a, next_score_b
  from jsonb_array_elements(next_racks) elem;

  update __LANE___private.player_match_score_submissions s
  set racks = next_racks,
      confirmed_at = null,
      updated_at = now()
  where s.id = submission.id;

  if old_side is distinct from rack_winner_side then
    insert into __LANE___private.audit_events(
      actor_user_id,
      action,
      entity_type,
      entity_id,
      before_state,
      after_state
    ) values (
      actor_user_id,
      'player_match.team_score_rack_edit',
      'player_match',
      target_player_match_id,
      jsonb_build_object(
        'scoringTeamId', target_scoring_team_id,
        'trackerPlayerId', tracker_id,
        'rackNumber', target_rack_number,
        'winnerSide', old_side,
        'racks', submission.racks,
        'confirmedAt', submission.confirmed_at
      ),
      jsonb_build_object(
        'scoringTeamId', target_scoring_team_id,
        'trackerPlayerId', tracker_id,
        'rackNumber', target_rack_number,
        'winnerSide', rack_winner_side,
        'racks', next_racks,
        'confirmedAt', null
      )
    );
  end if;

  return query
  select
    target_player_match_id,
    target_scoring_team_id,
    tracker_id,
    target_rack_number,
    old_side,
    rack_winner_side,
    next_score_a,
    next_score_b;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.finalize_player_match(actor_user_id uuid, target_player_match_id uuid)
 RETURNS TABLE(player_match_id uuid, status text, winner_side text, winner_player_id uuid, score_a integer, score_b integer, finalized_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_match __LANE__.player_matches%rowtype; finalized_match __LANE__.player_matches%rowtype;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update;
if not found then raise exception 'Player match not found'; end if;
if target_match.status in ('finalized','corrected') then raise exception 'Player match is already finalized'; end if;
if not __LANE___private.can_score_player_match(actor_user_id,target_match) then raise exception 'Only match players or active team captains can finalize matches'; end if;
if target_match.winner_side is null or target_match.winner_player_id is null then raise exception 'Race target must be reached before finalization'; end if;
if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before finalization'; end if;
if target_match.winner_side='A' and (target_match.score_a<target_match.race_to_a or target_match.winner_player_id<>target_match.player_a_id) then raise exception 'Player match is not in a valid completed race state'; end if;
if target_match.winner_side='B' and (target_match.score_b<target_match.race_to_b or target_match.winner_player_id<>target_match.player_b_id) then raise exception 'Player match is not in a valid completed race state'; end if;
update __LANE__.player_matches set status='finalized',finalized_by=actor_user_id,finalized_at=now() where player_matches.id=target_player_match_id returning * into finalized_match;
insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.finalize','player_match',target_player_match_id,to_jsonb(target_match),to_jsonb(finalized_match));
return query select finalized_match.id,finalized_match.status,finalized_match.winner_side,finalized_match.winner_player_id,finalized_match.score_a,finalized_match.score_b,finalized_match.finalized_at;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.finalize_reconciled_player_match(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid)
 RETURNS TABLE(player_match_id uuid, status text, winner_side text, winner_player_id uuid, score_a integer, score_b integer, finalized_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target_match __LANE__.player_matches%rowtype; finalized_match __LANE__.player_matches%rowtype; authorized_tracker_id uuid; submission_a __LANE___private.player_match_score_submissions%rowtype; submission_b __LANE___private.player_match_score_submissions%rowtype; reconciled_racks jsonb; reconciled_score_a integer; reconciled_score_b integer; resolved_winner_side text; resolved_winner_player_id uuid; canonical_before jsonb; begin if actor_user_id is null then raise exception 'actor_user_id is required'; end if; if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if; if target_scoring_team_id is null then raise exception 'scoring_team_id is required'; end if; select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update; if not found then raise exception 'Player match not found'; end if; if target_match.status in ('finalized','corrected') then raise exception 'Player match is already finalized'; end if; authorized_tracker_id:=__LANE___private.match_tracker_for_scoring_team(actor_user_id,target_match,target_scoring_team_id); if authorized_tracker_id is null then raise exception 'Actor is not an active member of the scoring team'; end if; if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before finalization'; end if; select * into submission_a from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=target_match.player_a_id for update; if not found then raise exception 'Both team score records are required before finalization'; end if; select * into submission_b from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=target_match.player_b_id for update; if not found then raise exception 'Both team score records are required before finalization'; end if; if submission_a.confirmed_at is null or submission_b.confirmed_at is null then raise exception 'Both teams must confirm the reconciled score before finalization'; end if; if submission_a.racks is distinct from submission_b.racks or jsonb_array_length(submission_a.racks)=0 then raise exception 'Team score histories must match before finalization'; end if; reconciled_racks:=submission_a.racks; if exists(select 1 from jsonb_array_elements(reconciled_racks) with ordinality as rack(value,ordinality) where coalesce(rack.value->>'winnerSide','') not in ('A','B') or nullif(rack.value->>'rackNumber','')::integer is distinct from rack.ordinality::integer or coalesce(rack.value->>'discipline','') is distinct from (case when rack.ordinality<=target_match.opening_block_length then target_match.opening_discipline when target_match.opening_discipline='8-ball' then '9-ball' else '8-ball' end)) then raise exception 'Reconciled rack history is invalid'; end if; select count(*) filter(where rack.value->>'winnerSide'='A')::integer,count(*) filter(where rack.value->>'winnerSide'='B')::integer into reconciled_score_a,reconciled_score_b from jsonb_array_elements(reconciled_racks) rack(value); if reconciled_score_a>=target_match.race_to_a and reconciled_score_b>=target_match.race_to_b then raise exception 'Reconciled score cannot have both players reach the race target'; end if; if reconciled_score_a<target_match.race_to_a and reconciled_score_b<target_match.race_to_b then raise exception 'Race target must be reached before finalization'; end if; if reconciled_score_a>=target_match.race_to_a then resolved_winner_side:='A'; resolved_winner_player_id:=target_match.player_a_id; else resolved_winner_side:='B'; resolved_winner_player_id:=target_match.player_b_id; end if; select coalesce(jsonb_agg(jsonb_build_object('rackNumber',pmr.rack_number,'discipline',pmr.discipline,'winnerSide',pmr.winner_side,'winnerPlayerId',pmr.winner_player_id,'recordedBy',pmr.recorded_by,'recordedAt',pmr.recorded_at) order by pmr.rack_number),'[]'::jsonb) into canonical_before from __LANE__.player_match_racks pmr where pmr.player_match_id=target_player_match_id; delete from __LANE__.player_match_racks pmr where pmr.player_match_id=target_player_match_id; insert into __LANE__.player_match_racks(season_id,player_match_id,rack_number,discipline,winner_side,winner_player_id,recorded_by) select target_match.season_id,target_player_match_id,rack.ordinality::integer,rack.value->>'discipline',rack.value->>'winnerSide',case when rack.value->>'winnerSide'='A' then target_match.player_a_id else target_match.player_b_id end,actor_user_id from jsonb_array_elements(reconciled_racks) with ordinality rack(value,ordinality) order by rack.ordinality; update __LANE__.player_matches set score_a=reconciled_score_a,score_b=reconciled_score_b,winner_side=resolved_winner_side,winner_player_id=resolved_winner_player_id,status='finalized',finalized_by=actor_user_id,finalized_at=now() where player_matches.id=target_player_match_id returning * into finalized_match; insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.finalize_reconciled','player_match',target_player_match_id,jsonb_build_object('match',to_jsonb(target_match),'canonicalRacks',canonical_before,'teamASubmission',to_jsonb(submission_a),'teamBSubmission',to_jsonb(submission_b),'scoringTeamId',target_scoring_team_id),jsonb_build_object('match',to_jsonb(finalized_match),'reconciledRacks',reconciled_racks,'scoringTeamId',target_scoring_team_id)); return query select finalized_match.id,finalized_match.status,finalized_match.winner_side,finalized_match.winner_player_id,finalized_match.score_a,finalized_match.score_b,finalized_match.finalized_at; end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.finalize_season_prize_payouts(actor_user_id uuid, target_season_id uuid, finalized_payouts jsonb)
 RETURNS TABLE(season_id uuid, pool text, place integer, label text, amount_cents integer, finalized_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payout_item jsonb;
  payout_pool text;
  payout_place integer;
  payout_label text;
  payout_amount_cents integer;
  inserted_payouts jsonb;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_season_id is null then
    raise exception 'target_season_id is required';
  end if;

  if not exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  perform 1
  from __LANE__.seasons s
  where s.id = target_season_id
  for update;

  if not found then
    raise exception 'Season not found';
  end if;

  if exists (
    select 1
    from __LANE__.season_final_prize_payouts sfpp
    where sfpp.season_id = target_season_id
  ) then
    raise exception 'Season prize payouts are already finalized';
  end if;

  if jsonb_typeof(finalized_payouts) is distinct from 'array' then
    raise exception 'finalized_payouts must be an array';
  end if;

  for payout_item in
    select value from jsonb_array_elements(finalized_payouts)
  loop
    if jsonb_typeof(payout_item) is distinct from 'object' then
      raise exception 'Each finalized payout must be an object';
    end if;

    payout_pool := payout_item ->> 'pool';
    payout_place := nullif(payout_item ->> 'place', '')::integer;
    payout_label := btrim(coalesce(payout_item ->> 'label', ''));
    payout_amount_cents := coalesce(
      nullif(payout_item ->> 'amountCents', '')::integer,
      nullif(payout_item ->> 'amount_cents', '')::integer
    );

    if payout_pool not in ('team', 'individual') then
      raise exception 'Finalized payout pool must be team or individual';
    end if;

    if payout_place is null or payout_place <= 0 then
      raise exception 'Finalized payout place must be greater than zero';
    end if;

    if payout_label is null or char_length(payout_label) = 0 or char_length(payout_label) > 80 then
      raise exception 'Finalized payout label must be 80 characters or fewer';
    end if;

    if payout_amount_cents is null or payout_amount_cents < 0 then
      raise exception 'Finalized payout amount must be zero or greater';
    end if;

    insert into __LANE__.season_final_prize_payouts (
      season_id,
      pool,
      place,
      label,
      amount_cents,
      finalized_by
    ) values (
      target_season_id,
      payout_pool,
      payout_place,
      payout_label,
      payout_amount_cents,
      actor_user_id
    );
  end loop;

  select jsonb_agg(to_jsonb(sfpp) order by sfpp.pool, sfpp.place)
    into inserted_payouts
  from __LANE__.season_final_prize_payouts sfpp
  where sfpp.season_id = target_season_id;

  insert into __LANE___private.audit_events (
    actor_user_id,
    action,
    entity_type,
    entity_id,
    after_state
  ) values (
    actor_user_id,
    'season.finalize_prize_payouts',
    'season',
    target_season_id,
    jsonb_build_object('payouts', inserted_payouts)
  );

  return query
  select
    sfpp.season_id,
    sfpp.pool,
    sfpp.place,
    sfpp.label,
    sfpp.amount_cents,
    sfpp.finalized_at
  from __LANE__.season_final_prize_payouts sfpp
  where sfpp.season_id = target_season_id
  order by sfpp.pool, sfpp.place;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_admin_player_phone(actor_user_id uuid, target_player_id uuid)
 RETURNS TABLE(player_id uuid, display_name text, phone text, has_phone boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  return query
  select p.id, p.display_name, pc.phone, nullif(btrim(pc.phone), '') is not null
  from __LANE__.players p
  left join __LANE___private.player_contacts pc on pc.player_id = p.id
  where p.id = target_player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_admin_season_registration(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(registration jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  perform __LANE___private.expire_season_team_registration(target_season_id);

  return query
  select jsonb_build_object(
    'seasonId', s.id,
    'seasonName', s.name,
    'seasonStatus', s.status,
    'teamCapacity', s.team_capacity,
    'minimumCommittedRoster', s.minimum_committed_roster,
    'returningReservationDeadline', s.returning_reservation_deadline,
    'conditionalHoldDays', s.conditional_hold_days,
    'counts', jsonb_build_object(
      'occupiedSlots', count(distinct sts.id) filter (
        where sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed')
      ),
      'confirmedTeams', count(distinct sts.team_id) filter (where sts.status = 'confirmed'),
      'reservedReturningSlots', count(distinct sts.id) filter (where sts.status in ('reserved', 'transferred')),
      'heldTeams', count(distinct sts.id) filter (where sts.status in ('approved_pending_roster', 'ready')),
      'availableSlots', greatest(0, s.team_capacity - count(distinct sts.id) filter (
        where sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed')
      )),
      'applicationsWaiting', count(distinct ta.id) filter (where ta.status in ('applied', 'deferred')),
      'rosteredPlayers', count(distinct tm.player_id) filter (where tm.ends_at is null),
      'registeredPlayers', count(distinct sp.player_id) filter (where sp.status = 'active'),
      'freeAgents', count(distinct sp.player_id) filter (
        where sp.status = 'active'
          and not exists (
            select 1 from __LANE__.team_memberships free_tm
            where free_tm.season_id = s.id
              and free_tm.player_id = sp.player_id
              and free_tm.ends_at is null
          )
      ),
      'openPrimaryRosterSpots', (
        select coalesce(sum(greatest(0, 4 - (
          select count(*)
          from __LANE__.team_memberships spot_tm
          where spot_tm.team_id = spot_slot.team_id
            and spot_tm.ends_at is null
        ))), 0)
        from __LANE___private.season_team_slots spot_slot
        where spot_slot.season_id = s.id
          and spot_slot.team_id is not null
          and spot_slot.status in ('approved_pending_roster', 'ready', 'confirmed')
      ),
      'pendingInvitations', count(distinct ti.id) filter (where ti.status = 'pending')
    ),
    'applications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'applicationId', app.id,
        'proposedTeamName', app.proposed_team_name,
        'status', app.status,
        'applicantPlayerId', p.id,
        'applicantDisplayName', p.display_name,
        'submittedAt', app.submitted_at,
        'reviewedAt', app.reviewed_at,
        'adminNotes', app.admin_notes,
        'teamId', app.team_id,
        'slotId', app.slot_id
      ) order by app.submitted_at)
      from __LANE___private.team_applications app
      join __LANE__.players p on p.id = app.applicant_player_id
      where app.season_id = s.id
    ), '[]'::jsonb),
    'slots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'slotId', slot.id,
        'status', slot.status,
        'teamId', slot.team_id,
        'teamName', current_team.name,
        'sourceTeamId', slot.source_team_id,
        'sourceTeamName', source_team.name,
        'captainPlayerId', slot.assigned_captain_player_id,
        'captainDisplayName', captain.display_name,
        'activeRosterCount', (
          select count(*) from __LANE__.team_memberships active_tm
          where active_tm.team_id = slot.team_id and active_tm.ends_at is null
        ),
        'committedRosterCount', __LANE___private.committed_team_roster_count(
          slot.team_id,
          slot.season_id
        ),
        'reservationExpiresAt', slot.reservation_expires_at,
        'holdExpiresAt', slot.hold_expires_at,
        'lastActionReason', slot.last_action_reason
      ) order by coalesce(current_team.name, source_team.name))
      from __LANE___private.season_team_slots slot
      left join __LANE__.teams current_team on current_team.id = slot.team_id
      left join __LANE__.teams source_team on source_team.id = slot.source_team_id
      left join __LANE__.players captain on captain.id = slot.assigned_captain_player_id
      where slot.season_id = s.id
    ), '[]'::jsonb)
  )
  from __LANE__.seasons s
  left join __LANE___private.season_team_slots sts on sts.season_id = s.id
  left join __LANE___private.team_applications ta on ta.season_id = s.id
  left join __LANE__.team_memberships tm on tm.season_id = s.id
  left join __LANE__.season_players sp on sp.season_id = s.id
  left join __LANE___private.team_invitations ti on ti.season_id = s.id
  where s.id = target_season_id
  group by s.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_my_direct_message_inbox(actor_user_id uuid)
 RETURNS TABLE(conversation_id uuid, season_id uuid, season_name text, other_player_id uuid, other_display_name text, last_message_body text, last_message_at timestamp with time zone, unread_count bigint, can_send boolean, blocked_by_me boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  return query
  select
    conversation.id,
    conversation.season_id,
    season.name,
    other_player.id,
    other_player.display_name,
    latest.body,
    latest.created_at,
    count(unread.id)::bigint,
    __LANE___private.is_active_season_participant(actor_player_id, conversation.season_id)
      and __LANE___private.is_active_season_participant(other_player.id, conversation.season_id)
      and not exists (
        select 1
        from __LANE__.player_chat_blocks block
        where (
          block.blocker_player_id = actor_player_id
          and block.blocked_player_id = other_player.id
        ) or (
          block.blocker_player_id = other_player.id
          and block.blocked_player_id = actor_player_id
        )
      ),
    exists (
      select 1
      from __LANE__.player_chat_blocks block
      where block.blocker_player_id = actor_player_id
        and block.blocked_player_id = other_player.id
    )
  from __LANE__.direct_conversations conversation
  join __LANE__.seasons season on season.id = conversation.season_id
  join __LANE__.players other_player on other_player.id = case
    when conversation.player_low_id = actor_player_id
      then conversation.player_high_id
    else conversation.player_low_id
  end
  left join __LANE__.direct_chat_reads read_state
    on read_state.conversation_id = conversation.id
    and read_state.player_id = actor_player_id
  left join lateral (
    select message.body, message.created_at
    from __LANE__.direct_messages message
    where message.conversation_id = conversation.id
      and message.removed_at is null
    order by message.created_at desc, message.id desc
    limit 1
  ) latest on true
  left join __LANE__.direct_messages unread
    on unread.conversation_id = conversation.id
    and unread.created_at > coalesce(read_state.last_read_at, conversation.created_at)
    and unread.author_player_id <> actor_player_id
    and unread.removed_at is null
  where actor_player_id in (conversation.player_low_id, conversation.player_high_id)
  group by conversation.id, conversation.season_id, season.name,
    other_player.id, other_player.display_name, latest.body, latest.created_at
  order by latest.created_at desc nulls last, other_player.display_name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_my_league_chat_inbox(actor_user_id uuid)
 RETURNS TABLE(season_id uuid, season_name text, last_message_body text, last_message_at timestamp with time zone, unread_count bigint, can_send boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select player.id into actor_player_id
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  return query
  with participant_seasons as (
    select season_player.season_id
    from __LANE__.season_players season_player
    where season_player.player_id = actor_player_id
      and season_player.status = 'active'
    union
    select membership.season_id
    from __LANE__.team_memberships membership
    where membership.player_id = actor_player_id
  )
  select season.id, season.name, latest.body, latest.created_at,
    count(unread.id)::bigint,
    __LANE___private.is_active_season_participant(actor_player_id, season.id)
  from participant_seasons participant
  join __LANE__.seasons season on season.id = participant.season_id
  left join __LANE__.league_chat_reads read_state
    on read_state.season_id = season.id
    and read_state.player_id = actor_player_id
  left join lateral (
    select message.body, message.created_at
    from __LANE__.league_chat_messages message
    where message.season_id = season.id and message.removed_at is null
    order by message.created_at desc, message.id desc
    limit 1
  ) latest on true
  left join __LANE__.league_chat_messages unread
    on unread.season_id = season.id
    and unread.created_at > coalesce(read_state.last_read_at, season.created_at)
    and unread.author_player_id <> actor_player_id
    and unread.removed_at is null
  group by season.id, season.name, latest.body, latest.created_at
  order by
    __LANE___private.is_active_season_participant(actor_player_id, season.id) desc,
    latest.created_at desc nulls last,
    season.created_at desc;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_my_matchup_chat_inbox(actor_user_id uuid)
 RETURNS TABLE(team_match_id uuid, season_id uuid, season_name text, round_number integer, scheduled_on date, team_a_name text, team_b_name text, last_message_body text, last_message_at timestamp with time zone, unread_count bigint, can_send boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actor_player_id uuid;
begin
  select player.id into actor_player_id from __LANE__.players player where player.user_id = actor_user_id;
  if actor_player_id is null then raise exception 'Player profile is required before using chat'; end if;

  return query
  select match.id, match.season_id, season.name, round.round_number, round.scheduled_on,
    team_a.name, team_b.name, latest.body, latest.created_at,
    count(unread.id)::bigint,
    season.status in ('registration', 'active', 'playoffs')
      and match.status not in ('finalized', 'corrected', 'cancelled')
      and exists (
        select 1 from __LANE__.team_memberships membership
        where membership.player_id = actor_player_id
          and membership.season_id = match.season_id
          and membership.team_id in (match.team_a_id, match.team_b_id)
          and membership.ends_at is null
      )
  from __LANE__.team_matches match
  join __LANE__.seasons season on season.id = match.season_id
  join __LANE__.rounds round on round.id = match.round_id
  join __LANE__.teams team_a on team_a.id = match.team_a_id
  join __LANE__.teams team_b on team_b.id = match.team_b_id
  left join __LANE__.matchup_chat_reads read_state
    on read_state.team_match_id = match.id and read_state.player_id = actor_player_id
  left join lateral (
    select message.body, message.created_at
    from __LANE__.matchup_chat_messages message
    where message.team_match_id = match.id and message.removed_at is null
      and exists (
        select 1 from __LANE__.team_memberships access_membership
        where access_membership.player_id = actor_player_id
          and access_membership.season_id = match.season_id
          and access_membership.team_id in (match.team_a_id, match.team_b_id)
          and access_membership.starts_at <= message.created_at
          and (access_membership.ends_at is null or message.created_at < access_membership.ends_at)
      )
    order by message.created_at desc, message.id desc limit 1
  ) latest on true
  left join __LANE__.matchup_chat_messages unread
    on unread.team_match_id = match.id
    and unread.created_at > coalesce(read_state.last_read_at, match.created_at)
    and unread.author_player_id <> actor_player_id and unread.removed_at is null
    and exists (
      select 1 from __LANE__.team_memberships access_membership
      where access_membership.player_id = actor_player_id
        and access_membership.season_id = match.season_id
        and access_membership.team_id in (match.team_a_id, match.team_b_id)
        and access_membership.starts_at <= unread.created_at
        and (access_membership.ends_at is null or unread.created_at < access_membership.ends_at)
    )
  where exists (
    select 1 from __LANE__.team_memberships membership
    where membership.player_id = actor_player_id
      and membership.season_id = match.season_id
      and membership.team_id in (match.team_a_id, match.team_b_id)
  )
  group by match.id, season.id, season.name, round.round_number, round.scheduled_on,
    team_a.name, team_b.name, latest.body, latest.created_at
  order by
    (match.status not in ('finalized', 'corrected', 'cancelled')) desc,
    round.scheduled_on desc nulls last, round.round_number desc;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_my_team_chat_inbox(actor_user_id uuid)
 RETURNS TABLE(team_id uuid, team_name text, season_id uuid, season_name text, member_role text, last_message_body text, last_message_at timestamp with time zone, unread_count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;

  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  return query
  select
    t.id,
    t.name,
    s.id,
    s.name,
    tm.role,
    latest.body,
    latest.created_at,
    count(unread.id)::bigint
  from __LANE__.team_memberships tm
  join __LANE__.teams t on t.id = tm.team_id and t.season_id = tm.season_id
  join __LANE__.seasons s on s.id = tm.season_id
  left join __LANE__.team_chat_reads tcr
    on tcr.team_id = tm.team_id and tcr.player_id = actor_player_id
  left join lateral (
    select m.body, m.created_at
    from __LANE__.team_chat_messages m
    where m.team_id = tm.team_id
      and m.created_at >= tm.starts_at
      and m.removed_at is null
    order by m.created_at desc, m.id desc
    limit 1
  ) latest on true
  left join __LANE__.team_chat_messages unread
    on unread.team_id = tm.team_id
    and unread.created_at > coalesce(tcr.last_read_at, tm.starts_at)
    and unread.author_player_id <> actor_player_id
    and unread.removed_at is null
  where tm.player_id = actor_player_id
    and tm.ends_at is null
  group by t.id, t.name, s.id, s.name, tm.role, latest.body, latest.created_at
  order by latest.created_at desc nulls last, t.name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_captaincy_transfers(actor_user_id uuid)
 RETURNS TABLE(outgoing jsonb, incoming jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with actor_player as (select p.id from __LANE__.players p where p.user_id=actor_user_id limit 1),
outgoing_rows as (select coalesce(jsonb_agg(jsonb_build_object('transferId',ct.id,'teamId',ct.team_id,'teamName',t.name,'seasonId',ct.season_id,'seasonName',s.name,'toPlayerId',ct.to_player_id,'toDisplayName',p.display_name,'departureMode',ct.departure_mode,'status',ct.status,'createdAt',ct.created_at) order by ct.created_at desc),'[]'::jsonb) as rows from actor_player ap join __LANE___private.captaincy_transfers ct on ct.from_player_id=ap.id join __LANE__.teams t on t.id=ct.team_id and t.season_id=ct.season_id join __LANE__.seasons s on s.id=ct.season_id join __LANE__.players p on p.id=ct.to_player_id where ct.status='pending'),
incoming_rows as (select coalesce(jsonb_agg(jsonb_build_object('transferId',ct.id,'teamId',ct.team_id,'teamName',t.name,'seasonId',ct.season_id,'seasonName',s.name,'fromPlayerId',ct.from_player_id,'fromDisplayName',p.display_name,'departureMode',ct.departure_mode,'status',ct.status,'createdAt',ct.created_at) order by ct.created_at desc),'[]'::jsonb) as rows from actor_player ap join __LANE___private.captaincy_transfers ct on ct.to_player_id=ap.id join __LANE__.teams t on t.id=ct.team_id and t.season_id=ct.season_id join __LANE__.seasons s on s.id=ct.season_id join __LANE__.players p on p.id=ct.from_player_id where ct.status='pending')
select outgoing_rows.rows,incoming_rows.rows from outgoing_rows cross join incoming_rows; $function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_date_availability(actor_user_id uuid, target_season_id uuid, target_availability_date date)
 RETURNS TABLE(season_id uuid, player_id uuid, availability_date date, availability_status text, registered boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_player_id uuid;
  is_registered boolean;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if target_availability_date is null then raise exception 'target_availability_date is required'; end if;
  select p.id into target_player_id from __LANE__.players p where p.user_id = actor_user_id;
  if target_player_id is null then raise exception 'Player profile is required'; end if;
  select exists (
    select 1 from __LANE__.season_players sp
    where sp.season_id = target_season_id and sp.player_id = target_player_id and sp.status = 'active'
  ) into is_registered;
  return query
  select target_season_id,target_player_id,target_availability_date,coalesce(pda.status,'unsure'::text),is_registered,pda.updated_at
  from (select 1) seed
  left join __LANE___private.player_date_availability pda
    on pda.season_id = target_season_id and pda.player_id = target_player_id and pda.availability_date = target_availability_date;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_player_phone(actor_user_id uuid)
 RETURNS TABLE(phone text, has_phone boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    pc.phone,
    nullif(btrim(pc.phone), '') is not null as has_phone
  from __LANE__.players p
  left join __LANE___private.player_contacts pc on pc.player_id = p.id
  where p.user_id = actor_user_id
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_player_profile(actor_user_id uuid)
 RETURNS TABLE(id uuid, user_id uuid, display_name text, fargo_rating integer, rating_status text, teams jsonb, seasons jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
select p.id,p.user_id,p.display_name,pr.fargo_rating,pr.rating_status,coalesce(team_rows.teams,'[]'::jsonb),coalesce(season_rows.seasons,'[]'::jsonb)
from __LANE__.players p
left join __LANE__.player_ratings pr on pr.player_id=p.id
left join lateral (
 select jsonb_agg(jsonb_build_object('seasonId',tm.season_id,'seasonName',s.name,'teamId',tm.team_id,'teamName',t.name,'role',tm.role,'startsAt',tm.starts_at,'endsAt',tm.ends_at) order by s.name,t.name,tm.starts_at) teams
 from __LANE__.team_memberships tm join __LANE__.teams t on t.id=tm.team_id and t.season_id=tm.season_id join __LANE__.seasons s on s.id=tm.season_id where tm.player_id=p.id
) team_rows on true
left join lateral (
 select jsonb_agg(jsonb_build_object('seasonId',sp.season_id,'seasonName',s.name,'participationType',sp.participation_type,'status',sp.status) order by s.name,sp.participation_type) seasons
 from __LANE__.season_players sp join __LANE__.seasons s on s.id=sp.season_id where sp.player_id=p.id
) season_rows on true
where p.user_id=actor_user_id limit 1;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_season_registration(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(season_id uuid, player_id uuid, participation_type text, registration_status text, registered_at timestamp with time zone, payment_status text, amount_due_cents integer, amount_paid_cents integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select
    sp.season_id,
    sp.player_id,
    sp.participation_type,
    sp.status,
    sp.created_at,
    coalesce(ps.status, 'unpaid'::text),
    coalesce(ps.amount_due_cents, 0),
    coalesce(ps.amount_paid_cents, 0)
  from __LANE__.players p
  join __LANE__.season_players sp on sp.player_id = p.id
  left join __LANE___private.payment_status ps
    on ps.season_id = sp.season_id and ps.player_id = sp.player_id
  where p.user_id = actor_user_id
    and sp.season_id = target_season_id
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_team_management(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, captain_teams jsonb, invitations jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with actor_player as (
  select p.id from __LANE__.players p where p.user_id = actor_user_id limit 1
)
select
  ap.id as player_id,
  coalesce(captain_rows.captain_teams, '[]'::jsonb) as captain_teams,
  coalesce(invitation_rows.invitations, '[]'::jsonb) as invitations
from actor_player ap
left join lateral (
  select jsonb_agg(
    jsonb_build_object(
      'seasonId', t.season_id,
      'seasonName', s.name,
      'teamId', t.id,
      'teamName', t.name,
      'captainMembershipId', captain.id,
      'roster', coalesce(roster_rows.roster, '[]'::jsonb),
      'pendingInvitations', coalesce(pending_rows.pending_invitations, '[]'::jsonb),
      'postseason', postseason_rows.postseason
    )
    order by s.name, t.name
  ) as captain_teams
  from __LANE__.team_memberships captain
  join __LANE__.teams t on t.id = captain.team_id and t.season_id = captain.season_id
  join __LANE__.seasons s on s.id = captain.season_id
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'membershipId', tm.id,
        'playerId', p.id,
        'displayName', p.display_name,
        'role', tm.role,
        'startsAt', tm.starts_at,
        'endsAt', tm.ends_at,
        'fargoRating', pr.fargo_rating,
        'ratingStatus', pr.rating_status
      )
      order by case when tm.role = 'captain' then 0 else 1 end, p.display_name
    ) as roster
    from __LANE__.team_memberships tm
    join __LANE__.players p on p.id = tm.player_id
    left join __LANE__.player_ratings pr on pr.player_id = p.id
    where tm.team_id = t.id
      and tm.season_id = t.season_id
      and tm.ends_at is null
  ) roster_rows on true
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'invitationId', ti.id,
        'playerId', p.id,
        'displayName', p.display_name,
        'status', ti.status,
        'createdAt', ti.created_at
      )
      order by ti.created_at
    ) as pending_invitations
    from __LANE___private.team_invitations ti
    join __LANE__.players p on p.id = ti.invited_player_id
    where ti.team_id = t.id and ti.status = 'pending'
  ) pending_rows on true
  left join lateral (
    select jsonb_build_object(
      'stage', r.stage,
      'roundId', r.id,
      'roundNumber', r.round_number,
      'roundStatus', r.status,
      'scheduledOn', r.scheduled_on,
      'teamMatchId', mt.id,
      'teamMatchStatus', mt.status,
      'winnerTeamId', mt.winner_team_id,
      'opponentTeamId', opponent.id,
      'opponentTeamName', opponent.name,
      'lineupLocked', own_lineup.id is not null,
      'anchorPlayerId', own_lineup.anchor_player_id,
      'lineup', coalesce(lineup_rows.lineup, '[]'::jsonb),
      'eligiblePlayers', coalesce(eligible_rows.players, '[]'::jsonb),
      'anchorTiebreaker', tiebreaker_rows.tiebreaker
    ) as postseason
    from __LANE__.rounds r
    join __LANE__.team_matches mt
      on mt.round_id = r.id and mt.season_id = r.season_id
    join __LANE__.teams opponent
      on opponent.id = case when mt.team_a_id = t.id then mt.team_b_id else mt.team_a_id end
    left join __LANE___private.team_lineups own_lineup
      on own_lineup.team_match_id = mt.id and own_lineup.team_id = t.id
    left join lateral (
      select jsonb_agg(
        jsonb_build_object(
          'slotNumber', tls.slot_number,
          'playerId', tls.player_id,
          'displayName', p.display_name
        )
        order by tls.slot_number
      ) as lineup
      from __LANE___private.team_lineup_slots tls
      join __LANE__.players p on p.id = tls.player_id
      where tls.lineup_id = own_lineup.id
    ) lineup_rows on true
    left join lateral (
      select jsonb_agg(
        jsonb_build_object(
          'playerId', p.id,
          'displayName', p.display_name,
          'fargoRating', pr.fargo_rating,
          'ratingStatus', pr.rating_status,
          'teamMatchesPlayed', counts.team_matches_played,
          'qualifiesThree', counts.team_matches_played >= 3,
          'qualifiesFour', counts.team_matches_played >= 4
        )
        order by counts.team_matches_played desc, p.display_name
      ) as players
      from __LANE__.team_memberships member
      join __LANE__.players p on p.id = member.player_id
      left join __LANE__.player_ratings pr on pr.player_id = p.id
      cross join lateral (
        select count(*)::integer as team_matches_played
        from __LANE__.player_matches pm
        join __LANE__.rounds regular_round on regular_round.id = pm.round_id
        where pm.season_id = t.season_id
          and regular_round.stage = 'regular'
          and pm.status in ('finalized', 'corrected')
          and (
            (pm.team_a_id = t.id and pm.player_a_id = p.id)
            or (pm.team_b_id = t.id and pm.player_b_id = p.id)
          )
      ) counts
      where member.season_id = t.season_id
        and member.team_id = t.id
        and member.ends_at is null
    ) eligible_rows on true
    left join lateral (
      select jsonb_build_object(
        'teamMatchId', tie_match.id,
        'playerMatchId', anchor_match.id,
        'status', anchor_match.status,
        'playerAName', player_a.display_name,
        'playerBName', player_b.display_name,
        'winnerPlayerId', anchor_match.winner_player_id
      ) as tiebreaker
      from __LANE___private.postseason_anchor_tiebreakers link
      join __LANE__.team_matches tie_match on tie_match.id = link.tiebreaker_team_match_id
      join __LANE__.player_matches anchor_match on anchor_match.id = link.anchor_player_match_id
      join __LANE__.players player_a on player_a.id = anchor_match.player_a_id
      join __LANE__.players player_b on player_b.id = anchor_match.player_b_id
      where link.parent_team_match_id = mt.id
      limit 1
    ) tiebreaker_rows on true
    where r.season_id = t.season_id
      and r.stage in ('semifinal', 'championship')
      and (mt.team_a_id = t.id or mt.team_b_id = t.id)
    order by
      case r.stage when 'championship' then 2 else 1 end desc,
      r.round_number desc
    limit 1
  ) postseason_rows on true
  where captain.player_id = ap.id
    and captain.role = 'captain'
    and captain.ends_at is null
) captain_rows on true
left join lateral (
  select jsonb_agg(
    jsonb_build_object(
      'invitationId', ti.id,
      'seasonId', ti.season_id,
      'seasonName', s.name,
      'teamId', t.id,
      'teamName', t.name,
      'status', ti.status,
      'createdAt', ti.created_at
    )
    order by ti.created_at
  ) as invitations
  from __LANE___private.team_invitations ti
  join __LANE__.teams t on t.id = ti.team_id and t.season_id = ti.season_id
  join __LANE__.seasons s on s.id = ti.season_id
  where ti.invited_player_id = ap.id and ti.status = 'pending'
) invitation_rows on true;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_team_membership_requests(actor_user_id uuid)
 RETURNS TABLE(player_requests jsonb, captain_requests jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with actor_player as (select p.id from __LANE__.players p where p.user_id=actor_user_id limit 1),
player_rows as (
  select coalesce(jsonb_agg(jsonb_build_object('requestId',r.id,'seasonId',r.season_id,'seasonName',s.name,'teamId',r.team_id,'teamName',t.name,'status',r.status,'createdAt',r.created_at,'resolvedAt',r.resolved_at) order by r.created_at desc),'[]'::jsonb) as rows
  from actor_player ap join __LANE___private.team_membership_requests r on r.player_id=ap.id join __LANE__.teams t on t.id=r.team_id and t.season_id=r.season_id join __LANE__.seasons s on s.id=r.season_id
),
captain_team_ids as (
  select tm.team_id,tm.season_id from actor_player ap join __LANE__.team_memberships tm on tm.player_id=ap.id where tm.role='captain' and tm.ends_at is null
),
captain_rows as (
  select coalesce(jsonb_agg(jsonb_build_object('requestId',r.id,'seasonId',r.season_id,'seasonName',s.name,'teamId',r.team_id,'teamName',t.name,'playerId',p.id,'displayName',p.display_name,'status',r.status,'createdAt',r.created_at) order by r.created_at),'[]'::jsonb) as rows
  from captain_team_ids c join __LANE___private.team_membership_requests r on r.team_id=c.team_id and r.season_id=c.season_id and r.status='pending' join __LANE__.teams t on t.id=r.team_id and t.season_id=r.season_id join __LANE__.seasons s on s.id=r.season_id join __LANE__.players p on p.id=r.player_id
)
select player_rows.rows,captain_rows.rows from player_rows cross join captain_rows; $function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_team_registration(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(registration jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required'; end if;
  perform __LANE___private.expire_season_team_registration(target_season_id);

  return query
  select jsonb_build_object(
    'seasonId', s.id,
    'seasonName', s.name,
    'seasonStatus', s.status,
    'teamCapacity', s.team_capacity,
    'minimumCommittedRoster', s.minimum_committed_roster,
    'applications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'applicationId', ta.id,
        'proposedTeamName', ta.proposed_team_name,
        'status', ta.status,
        'submittedAt', ta.submitted_at,
        'teamId', ta.team_id,
        'holdExpiresAt', sts.hold_expires_at
      ) order by ta.submitted_at desc)
      from __LANE___private.team_applications ta
      left join __LANE___private.season_team_slots sts on sts.id = ta.slot_id
      where ta.season_id = s.id and ta.applicant_player_id = actor_player_id
    ), '[]'::jsonb),
    'returningSlots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'slotId', sts.id,
        'sourceTeamId', sts.source_team_id,
        'sourceTeamName', source_team.name,
        'status', sts.status,
        'reservationExpiresAt', sts.reservation_expires_at
      ) order by source_team.name)
      from __LANE___private.season_team_slots sts
      join __LANE__.teams source_team on source_team.id = sts.source_team_id
      where sts.season_id = s.id
        and sts.assigned_captain_player_id = actor_player_id
        and sts.status in ('reserved', 'transferred')
    ), '[]'::jsonb)
  )
  from __LANE__.seasons s where s.id = target_season_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_own_team_trades(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, trades jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with actor_player as (
    select p.id
    from __LANE__.players p
    where p.user_id = actor_user_id
    limit 1
  ),
  visible_trades as (
    select tt.*
    from __LANE___private.team_trades tt
    cross join actor_player ap
    where tt.offered_player_id = ap.id
       or tt.requested_player_id = ap.id
       or exists (
        select 1
        from __LANE__.team_memberships tm
        where tm.player_id = ap.id
          and tm.role = 'captain'
          and tm.ends_at is null
          and tm.team_id in (tt.requesting_team_id, tt.requested_team_id)
       )
  )
  select
    ap.id as player_id,
    coalesce(jsonb_agg(
      jsonb_build_object(
        'tradeId', vt.id,
        'seasonId', vt.season_id,
        'seasonName', s.name,
        'status', vt.status,
        'adminException', vt.admin_exception,
        'requestingTeamId', requesting_team.id,
        'requestingTeamName', requesting_team.name,
        'requestedTeamId', requested_team.id,
        'requestedTeamName', requested_team.name,
        'offeredPlayerId', offered_player.id,
        'offeredPlayerName', offered_player.display_name,
        'requestedPlayerId', requested_player.id,
        'requestedPlayerName', requested_player.display_name,
        'requestingPlayerAcceptedAt', vt.requesting_player_accepted_at,
        'requestedPlayerAcceptedAt', vt.requested_player_accepted_at,
        'requestingCaptainApprovedAt', vt.requesting_captain_approved_at,
        'requestedCaptainApprovedAt', vt.requested_captain_approved_at,
        'declinedAt', vt.declined_at,
        'completedAt', vt.completed_at,
        'createdAt', vt.created_at
      )
      order by vt.created_at desc
    ) filter (where vt.id is not null), '[]'::jsonb) as trades
  from actor_player ap
  left join visible_trades vt on true
  left join __LANE__.seasons s on s.id = vt.season_id
  left join __LANE__.teams requesting_team on requesting_team.id = vt.requesting_team_id
  left join __LANE__.teams requested_team on requested_team.id = vt.requested_team_id
  left join __LANE__.players offered_player on offered_player.id = vt.offered_player_id
  left join __LANE__.players requested_player on requested_player.id = vt.requested_player_id
  group by ap.id;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_player_claim_options(actor_user_id uuid, search_text text DEFAULT NULL::text)
 RETURNS TABLE(options jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cleaned_search text;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;

  if exists (
    select 1 from __LANE__.players owned where owned.user_id = actor_user_id
  ) then
    return query select jsonb_build_object(
      'canClaim', false,
      'reason', 'already_has_profile',
      'players', '[]'::jsonb
    );
    return;
  end if;

  cleaned_search := nullif(btrim(regexp_replace(coalesce(search_text, ''), '\s+', ' ', 'g')), '');

  return query
  select jsonb_build_object(
    'canClaim', true,
    'reason', null,
    'players', coalesce((
      select jsonb_agg(candidate order by candidate ->> 'displayName')
      from (
        select jsonb_build_object(
          'playerId', p.id,
          'displayName', p.display_name,
          'teamNames', coalesce((
            select jsonb_agg(team_name order by team_name)
            from (
              select distinct t.name as team_name
              from __LANE__.team_memberships tm
              join __LANE__.teams t on t.id = tm.team_id
              where tm.player_id = p.id
                and tm.ends_at is null
            ) team_names
          ), '[]'::jsonb),
          'seasonNames', coalesce((
            select jsonb_agg(season_name order by season_name)
            from (
              select distinct s.name as season_name
              from __LANE__.season_players sp
              join __LANE__.seasons s on s.id = sp.season_id
              where sp.player_id = p.id
                and sp.status = 'active'
            ) season_names
          ), '[]'::jsonb)
        ) as candidate
        from __LANE__.players p
        where p.user_id is null
          and (cleaned_search is null or p.display_name ilike '%' || cleaned_search || '%')
          and not exists (
            select 1
            from __LANE__.player_matches pm
            where (pm.player_a_id = p.id or pm.player_b_id = p.id)
              and (
                exists (
                  select 1
                  from __LANE__.player_match_racks rack
                  where rack.player_match_id = pm.id
                )
                or exists (
                  select 1
                  from __LANE___private.player_match_score_submissions submission
                  where submission.player_match_id = pm.id
                    and jsonb_array_length(coalesce(submission.racks, '[]'::jsonb)) > 0
                )
              )
          )
        order by lower(p.display_name), p.created_at, p.id
        limit 30
      ) candidates
    ), '[]'::jsonb)
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_player_match_live_context(actor_user_id uuid, target_player_match_id uuid)
 RETURNS TABLE(player_match_id uuid, round_number integer, match_number integer, match_count integer, team_a_name text, team_b_name text, team_score_a integer, team_score_b integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id;
  if not found then raise exception 'Player match not found'; end if;

  if not __LANE___private.can_score_player_match(actor_user_id, target_match) then
    raise exception 'Only match players or active team captains can view the scorecard';
  end if;

  return query
  select
    target_match.id,
    r.round_number,
    target_match.slot_number,
    (
      select count(*)::integer
      from __LANE__.player_matches sibling
      where sibling.team_match_id = target_match.team_match_id
    ),
    team_a.name,
    team_b.name,
    (
      select count(*)::integer
      from __LANE__.player_matches sibling
      where sibling.team_match_id = target_match.team_match_id
        and sibling.status in ('finalized', 'corrected')
        and sibling.winner_side = 'A'
    ),
    (
      select count(*)::integer
      from __LANE__.player_matches sibling
      where sibling.team_match_id = target_match.team_match_id
        and sibling.status in ('finalized', 'corrected')
        and sibling.winner_side = 'B'
    )
  from __LANE__.rounds r
  join __LANE__.teams team_a on team_a.id = target_match.team_a_id
  join __LANE__.teams team_b on team_b.id = target_match.team_b_id
  where r.id = target_match.round_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_player_match_score_comparison(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, opponent_player_id uuid, own_racks jsonb, opponent_racks jsonb, own_confirmed_at timestamp with time zone, opponent_confirmed_at timestamp with time zone, histories_match boolean, mismatch_rack_number integer, both_confirmed boolean, ready_to_finalize boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target_match __LANE__.player_matches%rowtype; tracker_id uuid; opponent_id uuid; own_submission __LANE___private.player_match_score_submissions%rowtype; opponent_submission __LANE___private.player_match_score_submissions%rowtype; own_history jsonb; opponent_history jsonb; mismatch_number integer; begin if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if; select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id; if not found then raise exception 'Player match not found'; end if; tracker_id:=__LANE___private.match_tracker_for_scoring_team(actor_user_id,target_match,target_scoring_team_id); opponent_id:=case when tracker_id=target_match.player_a_id then target_match.player_b_id else target_match.player_a_id end; select * into own_submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=tracker_id; select * into opponent_submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=opponent_id; own_history:=coalesce(own_submission.racks,'[]'::jsonb); opponent_history:=coalesce(opponent_submission.racks,'[]'::jsonb); select gs+1 into mismatch_number from generate_series(0,greatest(jsonb_array_length(own_history),jsonb_array_length(opponent_history))-1) gs where (own_history->gs) is distinct from (opponent_history->gs) order by gs limit 1; return query select target_player_match_id,target_scoring_team_id,tracker_id,opponent_id,own_history,opponent_history,own_submission.confirmed_at,opponent_submission.confirmed_at,(own_history=opponent_history and jsonb_array_length(own_history)>0),mismatch_number,(own_submission.confirmed_at is not null and opponent_submission.confirmed_at is not null),(own_history=opponent_history and jsonb_array_length(own_history)>0 and own_submission.confirmed_at is not null and opponent_submission.confirmed_at is not null); end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.get_player_match_scorecard(actor_user_id uuid, target_player_match_id uuid)
 RETURNS TABLE(player_match_id uuid, season_id uuid, round_id uuid, team_match_id uuid, team_a_id uuid, team_b_id uuid, player_a_id uuid, player_a_display_name text, player_a_fargo_rating integer, player_a_rating_status text, player_b_id uuid, player_b_display_name text, player_b_fargo_rating integer, player_b_rating_status text, race_to_a integer, race_to_b integer, opening_block_length integer, opening_discipline text, current_discipline text, first_break text, score_a integer, score_b integer, winner_side text, winner_player_id uuid, status text, racks jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_match __LANE__.player_matches%rowtype;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id;
if not found then raise exception 'Player match not found'; end if;
if not __LANE___private.can_score_player_match(actor_user_id,target_match) then raise exception 'Only match players or active team captains can view the scorecard'; end if;
return query select pm.id,pm.season_id,pm.round_id,pm.team_match_id,pm.team_a_id,pm.team_b_id,pm.player_a_id,pa.display_name,pm.player_a_fargo_rating,pm.player_a_rating_status,pm.player_b_id,pb.display_name,pm.player_b_fargo_rating,pm.player_b_rating_status,pm.race_to_a,pm.race_to_b,pm.opening_block_length,pm.opening_discipline,pm.current_discipline,pm.first_break,pm.score_a,pm.score_b,pm.winner_side,pm.winner_player_id,pm.status,coalesce(rr.racks,'[]'::jsonb) from __LANE__.player_matches pm join __LANE__.players pa on pa.id=pm.player_a_id join __LANE__.players pb on pb.id=pm.player_b_id left join lateral (select jsonb_agg(jsonb_build_object('rackNumber',r.rack_number,'discipline',r.discipline,'winnerSide',r.winner_side,'winnerPlayerId',r.winner_player_id,'recordedAt',r.recorded_at) order by r.rack_number) racks from __LANE__.player_match_racks r where r.player_match_id=pm.id) rr on true where pm.id=target_player_match_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.get_season_close_readiness(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(season_id uuid, season_status text, championship_exists boolean, championship_finalized boolean, unresolved_postseason_matches integer, unresolved_player_matches integer, ready boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_status text; championship_count integer; finalized_championship_count integer; unresolved_postseason integer; unresolved_players integer;
begin
  if not exists (select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id) then raise exception 'Actor is not a league admin'; end if;
  select s.status into current_status from __LANE__.seasons s where s.id = target_season_id;
  if current_status is null then raise exception 'Season not found'; end if;
  select count(*)::integer,count(*) filter (where tm.status = 'finalized')::integer into championship_count,finalized_championship_count from __LANE__.rounds r join __LANE__.team_matches tm on tm.round_id = r.id where r.season_id = target_season_id and r.stage = 'championship';
  select count(*)::integer into unresolved_postseason from __LANE__.rounds r join __LANE__.team_matches tm on tm.round_id = r.id where r.season_id = target_season_id and r.stage in ('semifinal','championship','tiebreaker') and tm.status <> 'finalized';
  select count(*)::integer into unresolved_players from __LANE__.player_matches pm where pm.season_id = target_season_id and pm.status not in ('finalized','corrected');
  return query select target_season_id,current_status,championship_count > 0,championship_count = 1 and finalized_championship_count = 1,unresolved_postseason,unresolved_players,(current_status = 'complete' or (current_status = 'playoffs' and championship_count = 1 and finalized_championship_count = 1 and unresolved_postseason = 0 and unresolved_players = 0)),case when current_status = 'complete' then 'Season is already closed.' when current_status <> 'playoffs' then 'Finish the regular season and postseason before closing.' when championship_count = 0 then 'Championship must be created before closing.' when championship_count <> 1 then 'Exactly one championship matchup is required before closing.' when finalized_championship_count <> 1 then 'Championship must be finalized before closing.' when unresolved_postseason > 0 then 'Postseason still has unresolved matchups.' when unresolved_players > 0 then 'Competitive player matches still need final scores.' else 'All competition is finalized. Season is ready to close.' end;
end;$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_season_prize_summary(target_season_id uuid)
 RETURNS TABLE(season_id uuid, season_name text, season_status text, player_count integer, paid_amount_cents integer, committed_amount_cents integer, entry_fee_cents integer, administration_amount_cents integer, projected_field_size integer, projected_gross_cents integer, projected_prize_pool_cents integer, team_allocation_basis_points integer, individual_allocation_basis_points integer, team_prize_pool_cents integer, individual_prize_pool_cents integer, configuration_version integer, configured_at timestamp with time zone, projected_payouts jsonb, finalized_payouts jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select summary.* from __LANE__.get_season_prize_summary_internal(target_season_id) summary where exists(select 1 from __LANE__.seasons season where season.id=target_season_id and season.purpose='league'); $function$;


CREATE OR REPLACE FUNCTION __LANE__.get_season_prize_summary_internal(target_season_id uuid)
 RETURNS TABLE(season_id uuid, season_name text, season_status text, player_count integer, paid_amount_cents integer, committed_amount_cents integer, entry_fee_cents integer, administration_amount_cents integer, projected_field_size integer, projected_gross_cents integer, projected_prize_pool_cents integer, team_allocation_basis_points integer, individual_allocation_basis_points integer, team_prize_pool_cents integer, individual_prize_pool_cents integer, configuration_version integer, configured_at timestamp with time zone, projected_payouts jsonb, finalized_payouts jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with target_season as (
    select s.id, s.name, s.status
    from __LANE__.seasons s
    where s.id = target_season_id
  ),
  participant_players as (
    select tm.player_id
    from __LANE__.team_memberships tm
    join target_season ts on ts.id = tm.season_id
    where tm.ends_at is null
    union
    select sp.player_id
    from __LANE__.season_players sp
    join target_season ts on ts.id = sp.season_id
    where sp.status = 'active'
  ),
  player_totals as (
    select count(distinct pp.player_id)::integer as player_count
    from participant_players pp
  ),
  payment_totals as (
    select coalesce(sum(ps.amount_paid_cents), 0)::integer as paid_amount_cents
    from __LANE___private.payment_status ps
    join target_season ts on ts.id = ps.season_id
  ),
  latest_configuration as (
    select spc.*
    from __LANE__.season_prize_configurations spc
    join target_season ts on ts.id = spc.season_id
    order by spc.version desc
    limit 1
  ),
  computed as (
    select
      ts.id,
      ts.name,
      ts.status,
      pt.player_count,
      pay.paid_amount_cents,
      lc.id as configuration_id,
      lc.entry_fee_cents,
      lc.administration_amount_cents,
      lc.projected_field_size,
      (coalesce(lc.entry_fee_cents, 0) * pt.player_count)::integer as committed_amount_cents,
      (coalesce(lc.entry_fee_cents, 0) * coalesce(lc.projected_field_size, 0))::integer as projected_gross_cents,
      greatest(
        (coalesce(lc.entry_fee_cents, 0) * coalesce(lc.projected_field_size, 0))
          - coalesce(lc.administration_amount_cents, 0),
        0
      )::integer as projected_prize_pool_cents,
      lc.team_allocation_basis_points,
      lc.individual_allocation_basis_points,
      lc.version,
      lc.created_at
    from target_season ts
    cross join player_totals pt
    cross join payment_totals pay
    left join latest_configuration lc on true
  )
  select
    c.id,
    c.name,
    c.status,
    c.player_count,
    c.paid_amount_cents,
    c.committed_amount_cents,
    coalesce(c.entry_fee_cents, 0),
    coalesce(c.administration_amount_cents, 0),
    coalesce(c.projected_field_size, 0),
    c.projected_gross_cents,
    c.projected_prize_pool_cents,
    coalesce(c.team_allocation_basis_points, 0),
    coalesce(c.individual_allocation_basis_points, 0),
    round(c.projected_prize_pool_cents::numeric * coalesce(c.team_allocation_basis_points, 0)::numeric / 10000)::integer,
    round(c.projected_prize_pool_cents::numeric * coalesce(c.individual_allocation_basis_points, 0)::numeric / 10000)::integer,
    c.version,
    c.created_at,
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'pool', sppt.pool,
          'place', sppt.place,
          'label', sppt.label,
          'allocationBasisPoints', sppt.allocation_basis_points,
          'amountCents', round(
            (
              case sppt.pool
                when 'team' then c.projected_prize_pool_cents::numeric
                  * coalesce(c.team_allocation_basis_points, 0)::numeric / 10000
                else c.projected_prize_pool_cents::numeric
                  * coalesce(c.individual_allocation_basis_points, 0)::numeric / 10000
              end
            ) * sppt.allocation_basis_points::numeric / 10000
          )::integer
        )
        order by sppt.pool, sppt.place
      )
      from __LANE__.season_prize_payout_templates sppt
      where sppt.configuration_id = c.configuration_id
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'pool', sfpp.pool,
          'place', sfpp.place,
          'label', sfpp.label,
          'amountCents', sfpp.amount_cents,
          'finalizedAt', sfpp.finalized_at
        )
        order by sfpp.pool, sfpp.place
      )
      from __LANE__.season_final_prize_payouts sfpp
      where sfpp.season_id = c.id
    ), '[]'::jsonb)
  from computed c;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.get_season_setup(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(id uuid, name text, status text, league_night text, first_round_date date, roster_lock_round integer, opening_block_length integer, individual_min_matches integer, round_interval_days integer, default_table_numbers integer[], race_chart_version text, playoff_team_count integer, playoff_anchor_tiebreaker boolean, teams jsonb, rounds jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_season_id is null then
    raise exception 'target_season_id is required';
  end if;

  if not exists (
    select 1
    from __LANE___private.league_admins la
    where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  return query
  select
    s.id,
    s.name,
    s.status,
    s.league_night,
    s.first_round_date,
    s.roster_lock_round,
    s.opening_block_length,
    s.individual_min_matches,
    s.round_interval_days,
    s.default_table_numbers,
    s.race_chart_version,
    s.playoff_team_count,
    s.playoff_anchor_tiebreaker,
    coalesce(team_rows.teams, '[]'::jsonb) as teams,
    coalesce(round_rows.rounds, '[]'::jsonb) as rounds
  from __LANE__.seasons s
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'teamId', t.id,
        'teamName', t.name,
        'activeRosterCount', coalesce(roster_rows.active_roster_count, 0)
      )
      order by t.name
    ) as teams
    from __LANE__.teams t
    left join lateral (
      select count(*)::integer as active_roster_count
      from __LANE__.team_memberships tm
      where tm.team_id = t.id
        and tm.ends_at is null
    ) roster_rows on true
    where t.season_id = s.id
  ) team_rows on true
  left join lateral (
    select jsonb_agg(
      jsonb_build_object(
        'roundId', r.id,
        'roundNumber', r.round_number,
        'stage', r.stage,
        'scheduledOn', r.scheduled_on,
        'matches', coalesce(match_rows.matches, '[]'::jsonb)
      )
      order by r.stage, r.round_number
    ) as rounds
    from __LANE__.rounds r
    left join lateral (
      select jsonb_agg(
        jsonb_build_object(
          'teamMatchId', tm.id,
          'tableNumber', tm.table_number,
          'teamAId', tm.team_a_id,
          'teamAName', team_a.name,
          'teamBId', tm.team_b_id,
          'teamBName', team_b.name
        )
        order by tm.table_number
      ) as matches
      from __LANE__.team_matches tm
      join __LANE__.teams team_a on team_a.id = tm.team_a_id
      join __LANE__.teams team_b on team_b.id = tm.team_b_id
      where tm.round_id = r.id
    ) match_rows on true
    where r.season_id = s.id
  ) round_rows on true
  where s.id = target_season_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.invite_player_to_team(actor_user_id uuid, target_team_id uuid, target_player_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, invited_player_id uuid, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  inserted_invitation_id uuid;
  pending_request_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;

  select t.season_id into target_season_id
  from __LANE__.teams t
  where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before inviting players'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can invite players';
  end if;

  if not exists (select 1 from __LANE__.players p where p.id = target_player_id) then
    raise exception 'Invited player not found';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = target_player_id
      and tm.ends_at is null
  ) then
    raise exception 'Player is already an active member of this team';
  end if;

  select r.id into pending_request_id
  from __LANE___private.team_membership_requests r
  where r.season_id = target_season_id
    and r.team_id = target_team_id
    and r.player_id = target_player_id
    and r.status = 'pending'
  order by r.created_at
  limit 1
  for update;

  insert into __LANE___private.team_invitations(
    season_id, team_id, invited_player_id, invited_by_user_id,
    status, responded_at
  ) values (
    target_season_id, target_team_id, target_player_id, actor_user_id,
    case when pending_request_id is null then 'pending' else 'accepted' end,
    case when pending_request_id is null then null else now() end
  ) returning __LANE___private.team_invitations.id into inserted_invitation_id;

  if pending_request_id is not null then
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(target_season_id, target_team_id, target_player_id, 'player');

    update __LANE___private.team_membership_requests
    set status = 'approved', resolved_at = now(), resolved_by_user_id = actor_user_id
    where __LANE___private.team_membership_requests.season_id = target_season_id
      and __LANE___private.team_membership_requests.team_id = target_team_id
      and __LANE___private.team_membership_requests.player_id = target_player_id
      and __LANE___private.team_membership_requests.status = 'pending';
  end if;

  return query
  select ti.id, ti.season_id, ti.team_id, ti.invited_player_id, ti.status, ti.created_at
  from __LANE___private.team_invitations ti
  where ti.id = inserted_invitation_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_admin_player_contact_readiness(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, has_phone boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  return query
  select p.id, nullif(btrim(pc.phone), '') is not null
  from __LANE__.players p
  left join __LANE___private.player_contacts pc on pc.player_id = p.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_admin_players(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, display_name text, has_login boolean, is_league_admin boolean, teams jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  return query
  select
    p.id,
    p.display_name,
    p.user_id is not null,
    exists (
      select 1 from __LANE___private.league_admins la where la.user_id = p.user_id
    ),
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'teamId', t.id,
          'teamName', t.name,
          'seasonId', s.id,
          'seasonName', s.name,
          'role', tm.role
        ) order by s.created_at desc, t.name
      )
      from __LANE__.team_memberships tm
      join __LANE__.teams t on t.id = tm.team_id
      join __LANE__.seasons s on s.id = tm.season_id
      where tm.player_id = p.id
        and tm.ends_at is null
    ), '[]'::jsonb)
  from __LANE__.players p
  order by lower(p.display_name), p.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_admin_players_for_management(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, display_name text, has_login boolean, is_league_admin boolean, teams jsonb, current_season_id uuid, current_season_name text, registration_status text, payment_status text, competition_eligible boolean, ineligibility_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  active_season __LANE__.seasons%rowtype;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  select * into active_season
  from __LANE__.seasons s
  where s.status <> 'complete'
  order by s.created_at desc, s.id desc
  limit 1;

  return query
  select
    p.id,
    p.display_name,
    p.user_id is not null,
    exists (
      select 1 from __LANE___private.league_admins la where la.user_id = p.user_id
    ),
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'membershipId', tm.id,
          'teamId', t.id,
          'teamName', t.name,
          'seasonId', s.id,
          'seasonName', s.name,
          'role', tm.role
        ) order by s.created_at desc, t.name
      )
      from __LANE__.team_memberships tm
      join __LANE__.teams t on t.id = tm.team_id
      join __LANE__.seasons s on s.id = tm.season_id
      where tm.player_id = p.id
        and tm.ends_at is null
    ), '[]'::jsonb),
    active_season.id,
    active_season.name,
    (
      select sp.status
      from __LANE__.season_players sp
      where sp.season_id = active_season.id and sp.player_id = p.id
      limit 1
    ),
    (
      select ps.status
      from __LANE___private.payment_status ps
      where ps.season_id = active_season.id and ps.player_id = p.id
      limit 1
    ),
    not exists (
      select 1
      from __LANE___private.player_competition_restrictions r
      where r.season_id = active_season.id
        and r.player_id = p.id
        and r.lifted_at is null
    ),
    (
      select r.reason
      from __LANE___private.player_competition_restrictions r
      where r.season_id = active_season.id
        and r.player_id = p.id
        and r.lifted_at is null
      limit 1
    )
  from __LANE__.players p
  order by lower(p.display_name), p.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_admin_roster_teams(actor_user_id uuid)
 RETURNS TABLE(season_id uuid, season_name text, team_id uuid, team_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
