CREATE OR REPLACE FUNCTION __LANE__.list_admin_season_team_candidates(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(candidate_kind text, team_id uuid, team_name text, source_season_id uuid, source_season_name text, captain_player_id uuid, captain_display_name text, active_roster_count integer, slot_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if not exists (select 1 from __LANE__.seasons s where s.id = target_season_id) then
    raise exception 'Season not found';
  end if;
  perform __LANE___private.expire_season_team_registration(target_season_id);
  return query
  with target_season as (
    select s.id, s.created_at from __LANE__.seasons s where s.id = target_season_id
  ), active_slots as (
    select sts.* from __LANE___private.season_team_slots sts
    where sts.season_id = target_season_id
      and sts.status in ('reserved','transferred','approved_pending_roster','ready','confirmed')
  ), in_season as (
    select 'in_season'::text, coalesce(slot.team_id,slot.source_team_id),
      coalesce(current_team.name,source_team.name),
      coalesce(current_team.season_id,source_team.season_id),
      coalesce(current_season.name,source_season.name),
      slot.assigned_captain_player_id,captain.display_name,
      case when slot.team_id is null then 0 else (
        select count(*)::integer from __LANE__.team_memberships tm
        where tm.team_id=slot.team_id and tm.season_id=target_season_id and tm.ends_at is null
      ) end, slot.status
    from active_slots slot
    left join __LANE__.teams current_team on current_team.id=slot.team_id
    left join __LANE__.teams source_team on source_team.id=slot.source_team_id
    left join __LANE__.seasons current_season on current_season.id=current_team.season_id
    left join __LANE__.seasons source_season on source_season.id=source_team.season_id
    left join __LANE__.players captain on captain.id=slot.assigned_captain_player_id
  ), new_teams as (
    select 'new'::text,t.id,t.name,t.season_id,s.name,captain_membership.player_id,captain.display_name,
      (select count(*)::integer from __LANE__.team_memberships roster where roster.team_id=t.id and roster.season_id=t.season_id and roster.ends_at is null),null::text
    from __LANE__.teams t join __LANE__.seasons s on s.id=t.season_id
    left join lateral (
      select tm.player_id from __LANE__.team_memberships tm
      where tm.team_id=t.id and tm.season_id=t.season_id and tm.role='captain' and tm.ends_at is null
      order by tm.starts_at desc limit 1
    ) captain_membership on true
    left join __LANE__.players captain on captain.id=captain_membership.player_id
    where t.season_id=target_season_id
      and not exists (select 1 from active_slots slot where slot.team_id=t.id or slot.source_team_id=t.id)
  ), returning_source as (
    select distinct on (lower(btrim(t.name))) t.id,t.name,t.season_id,s.name as season_name,s.created_at as season_created_at
    from __LANE__.teams t join __LANE__.seasons s on s.id=t.season_id
    join target_season target on s.created_at<target.created_at
    where t.season_id<>target_season_id
      and not exists (select 1 from __LANE__.teams target_team where target_team.season_id=target_season_id and lower(btrim(target_team.name))=lower(btrim(t.name)))
      and not exists (select 1 from active_slots slot where slot.source_team_id=t.id)
    order by lower(btrim(t.name)),s.created_at desc,t.created_at desc
  ), returning_teams as (
    select 'returning'::text,source.id,source.name,source.season_id,source.season_name,captain_membership.player_id,captain.display_name,
      (select count(*)::integer from __LANE__.team_memberships roster where roster.team_id=source.id and roster.season_id=source.season_id and roster.ends_at is null),null::text
    from returning_source source
    left join lateral (
      select tm.player_id from __LANE__.team_memberships tm
      where tm.team_id=source.id and tm.season_id=source.season_id and tm.role='captain' and tm.ends_at is null
      order by tm.starts_at desc limit 1
    ) captain_membership on true
    left join __LANE__.players captain on captain.id=captain_membership.player_id
  ), combined as (
    select * from in_season union all select * from returning_teams union all select * from new_teams
  )
  select combined.* from combined order by combined.candidate_kind,combined.team_name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_admin_team_captain_candidates(actor_user_id uuid, target_season_id uuid, target_team_id uuid)
 RETURNS TABLE(player_id uuid, display_name text, has_login boolean, has_phone boolean, rostered_on_team boolean, captain_team_id uuid, captain_team_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if not exists (
    select 1 from __LANE__.teams t
    where t.id = target_team_id and t.season_id = target_season_id
  ) then
    raise exception 'Team not found';
  end if;

  return query
  select
    p.id,
    p.display_name,
    p.user_id is not null,
    nullif(btrim(pc.phone), '') is not null,
    exists (
      select 1 from __LANE__.team_memberships target_tm
      where target_tm.season_id = target_season_id
        and target_tm.team_id = target_team_id
        and target_tm.player_id = p.id
        and target_tm.ends_at is null
    ),
    captain_tm.team_id,
    captain_team.name
  from __LANE__.players p
  left join __LANE___private.player_contacts pc on pc.player_id = p.id
  left join lateral (
    select tm.team_id
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.player_id = p.id
      and tm.role = 'captain'
      and tm.ends_at is null
    order by tm.starts_at desc
    limit 1
  ) captain_tm on true
  left join __LANE__.teams captain_team on captain_team.id = captain_tm.team_id
  order by
    exists (
      select 1 from __LANE__.team_memberships target_tm
      where target_tm.season_id = target_season_id
        and target_tm.team_id = target_team_id
        and target_tm.player_id = p.id
        and target_tm.ends_at is null
    ) desc,
    lower(p.display_name),
    p.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_all_season_registration_internal()
 RETURNS TABLE(id uuid, name text, status text, first_round_date date, team_capacity integer, minimum_committed_roster integer, team_count integer, confirmed_team_count integer, occupied_slots integer, open_team_slots integer, reserved_returning_slots integer, held_team_slots integer, applications_waiting integer, rostered_player_count integer, registered_player_count integer, free_agent_count integer, open_primary_roster_spots integer, at_risk_team_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  season_row record;
begin
  for season_row in select s.id from __LANE__.seasons s loop
    perform __LANE___private.expire_season_team_registration(season_row.id);
  end loop;

  return query
  select
    s.id,
    s.name,
    s.status,
    s.first_round_date,
    s.team_capacity,
    s.minimum_committed_roster,
    count(distinct sts.team_id) filter (
      where sts.team_id is not null
        and sts.status in ('approved_pending_roster', 'ready', 'confirmed')
    )::integer,
    count(distinct sts.team_id) filter (
      where sts.team_id is not null and sts.status = 'confirmed'
    )::integer,
    count(distinct sts.id) filter (
      where sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed')
    )::integer,
    greatest(0, s.team_capacity - count(distinct sts.id) filter (
      where sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed')
    ))::integer,
    count(distinct sts.id) filter (where sts.status in ('reserved', 'transferred'))::integer,
    count(distinct sts.id) filter (where sts.status in ('approved_pending_roster', 'ready'))::integer,
    count(distinct ta.id) filter (where ta.status in ('applied', 'deferred'))::integer,
    count(distinct tm.player_id) filter (where tm.ends_at is null)::integer,
    count(distinct sp.player_id) filter (where sp.status = 'active')::integer,
    count(distinct sp.player_id) filter (
      where sp.status = 'active'
                and not exists (
          select 1 from __LANE__.team_memberships active_tm
          where active_tm.season_id = s.id
            and active_tm.player_id = sp.player_id
            and active_tm.ends_at is null
        )
    )::integer,
    (
      select coalesce(sum(greatest(0, 4 - (
        select count(*)
        from __LANE__.team_memberships spot_tm
        where spot_tm.team_id = spot_slot.team_id
          and spot_tm.ends_at is null
      ))), 0)::integer
      from __LANE___private.season_team_slots spot_slot
      where spot_slot.season_id = s.id
        and spot_slot.team_id is not null
        and spot_slot.status in ('approved_pending_roster', 'ready', 'confirmed')
    ),
    count(distinct sts.team_id) filter (
      where sts.status = 'confirmed'
        and __LANE___private.committed_team_roster_count(sts.team_id, sts.season_id)
            < s.minimum_committed_roster
    )::integer
  from __LANE__.seasons s
  left join __LANE___private.season_team_slots sts on sts.season_id = s.id
  left join __LANE___private.team_applications ta on ta.season_id = s.id
  left join __LANE__.team_memberships tm on tm.season_id = s.id
  left join __LANE__.season_players sp on sp.season_id = s.id
  group by s.id
  order by s.created_at desc;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_blocked_chat_players(actor_user_id uuid)
 RETURNS TABLE(player_id uuid, display_name text, blocked_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  return query
  select blocked.id, blocked.display_name, block.created_at
  from __LANE__.player_chat_blocks block
  join __LANE__.players blocked on blocked.id = block.blocked_player_id
  where block.blocker_player_id = actor_player_id
  order by blocked.display_name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_chat_message_reports(actor_user_id uuid, result_limit integer DEFAULT 50)
 RETURNS TABLE(report_id uuid, target_type text, message_id uuid, context_label text, reporter_display_name text, author_display_name text, message_body text, reason text, details text, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if not exists (select 1 from __LANE___private.league_admins admin where admin.user_id = actor_user_id) then raise exception 'League admin access is required'; end if;
  if result_limit < 1 or result_limit > 100 then raise exception 'Report limit must be between 1 and 100'; end if;
  return query select report.id, report.target_type,
    coalesce(report.team_message_id, report.direct_message_id, report.league_message_id, report.matchup_message_id),
    case report.target_type
      when 'team' then team.name || ' · ' || team_season.name
      when 'league' then 'League · ' || league_season.name
      when 'matchup' then matchup_team_a.name || ' vs ' || matchup_team_b.name || ' · Round ' || matchup_round.round_number
      else 'Direct message'
    end,
    reporter.display_name,
    coalesce(team_author.display_name, direct_author.display_name, league_author.display_name, matchup_author.display_name),
    coalesce(team_message.body, direct_message.body, league_message.body, matchup_message.body),
    report.reason, report.details, report.status, report.created_at
  from __LANE__.chat_message_reports report
  join __LANE__.players reporter on reporter.id = report.reporter_player_id
  left join __LANE__.team_chat_messages team_message on team_message.id = report.team_message_id
  left join __LANE__.players team_author on team_author.id = team_message.author_player_id
  left join __LANE__.teams team on team.id = team_message.team_id
  left join __LANE__.seasons team_season on team_season.id = team_message.season_id
  left join __LANE__.direct_messages direct_message on direct_message.id = report.direct_message_id
  left join __LANE__.players direct_author on direct_author.id = direct_message.author_player_id
  left join __LANE__.league_chat_messages league_message on league_message.id = report.league_message_id
  left join __LANE__.players league_author on league_author.id = league_message.author_player_id
  left join __LANE__.seasons league_season on league_season.id = league_message.season_id
  left join __LANE__.matchup_chat_messages matchup_message on matchup_message.id = report.matchup_message_id
  left join __LANE__.players matchup_author on matchup_author.id = matchup_message.author_player_id
  left join __LANE__.team_matches matchup on matchup.id = matchup_message.team_match_id
  left join __LANE__.teams matchup_team_a on matchup_team_a.id = matchup.team_a_id
  left join __LANE__.teams matchup_team_b on matchup_team_b.id = matchup.team_b_id
  left join __LANE__.rounds matchup_round on matchup_round.id = matchup.round_id
  order by (report.status in ('open', 'reviewing')) desc, report.created_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_direct_message_candidates(actor_user_id uuid)
 RETURNS TABLE(season_id uuid, season_name text, player_id uuid, display_name text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  return query
  with participants as (
    select sp.season_id, sp.player_id
    from __LANE__.season_players sp
    where sp.status = 'active'
    union
    select tm.season_id, tm.player_id
    from __LANE__.team_memberships tm
    where tm.ends_at is null
  ),
  actor_seasons as (
    select participant.season_id
    from participants participant
    where participant.player_id = actor_player_id
  )
  select s.id, s.name, candidate.id, candidate.display_name
  from actor_seasons actor_season
  join __LANE__.seasons s on s.id = actor_season.season_id
  join participants participant on participant.season_id = s.id
  join __LANE__.players candidate on candidate.id = participant.player_id
  where s.status in ('registration', 'active', 'playoffs')
    and candidate.id <> actor_player_id
    and not exists (
      select 1
      from __LANE__.player_chat_blocks block
      where (
        block.blocker_player_id = actor_player_id
        and block.blocked_player_id = candidate.id
      ) or (
        block.blocker_player_id = candidate.id
        and block.blocked_player_id = actor_player_id
      )
    )
  group by s.id, s.name, candidate.id, candidate.display_name
  order by candidate.display_name, s.name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_direct_messages(actor_user_id uuid, target_conversation_id uuid, before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, before_message_id uuid DEFAULT NULL::uuid, result_limit integer DEFAULT 50)
 RETURNS TABLE(message_id uuid, conversation_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  if result_limit < 1 or result_limit > 100 then
    raise exception 'Message limit must be between 1 and 100';
  end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  if not exists (
    select 1
    from __LANE__.direct_conversations conversation
    where conversation.id = target_conversation_id
      and actor_player_id in (conversation.player_low_id, conversation.player_high_id)
  ) then
    raise exception 'Direct conversation not found';
  end if;

  return query
  select page.message_id, page.conversation_id, page.author_player_id,
    page.author_display_name, page.body, page.created_at, page.is_own
  from (
    select message.id as message_id, message.conversation_id,
      message.author_player_id, author.display_name as author_display_name,
      message.body, message.created_at,
      message.author_player_id = actor_player_id as is_own
    from __LANE__.direct_messages message
    join __LANE__.players author on author.id = message.author_player_id
    where message.conversation_id = target_conversation_id
      and message.removed_at is null
      and (
        before_created_at is null
        or (message.created_at, message.id) < (
          before_created_at,
          coalesce(before_message_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
        )
      )
    order by message.created_at desc, message.id desc
    limit result_limit
  ) page
  order by page.created_at, page.message_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_eligible_free_agents(actor_user_id uuid, target_team_id uuid, target_round_id uuid)
 RETURNS TABLE(season_id uuid, round_id uuid, player_id uuid, display_name text, fargo_rating integer, rating_status text, availability_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  active_roster_count integer;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;
  select p.id into actor_player_id from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before listing eligible free agents'; end if;
  select t.season_id into target_season_id from __LANE__.teams t where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;
  if not exists (select 1 from __LANE__.rounds r where r.id = target_round_id and r.season_id = target_season_id) then raise exception 'Round not found for team season'; end if;
  if not exists (select 1 from __LANE__.team_matches tm where tm.round_id = target_round_id and (tm.team_a_id = target_team_id or tm.team_b_id = target_team_id)) then raise exception 'Team is not scheduled for target round'; end if;
  if not exists (select 1 from __LANE__.team_memberships tm where tm.team_id = target_team_id and tm.player_id = actor_player_id and tm.role='captain' and tm.ends_at is null) then raise exception 'Only the active captain can view eligible free agents'; end if;
  select __LANE___private.active_team_roster_count(target_team_id) into active_roster_count;
  if active_roster_count >= 4 then return; end if;
  return query
  select sp.season_id,fa.round_id,p.id as player_id,p.display_name,pr.fargo_rating,pr.rating_status,fa.status as availability_status
  from __LANE___private.free_agent_availability fa
  join __LANE__.season_players sp on sp.season_id=fa.season_id and sp.player_id=fa.player_id
  join __LANE__.players p on p.id=sp.player_id
  left join __LANE__.player_ratings pr on pr.player_id=sp.player_id
  where fa.round_id=target_round_id and fa.season_id=target_season_id and fa.status='available' and sp.participation_type='free_agent' and sp.status='active'
    and not exists(select 1 from __LANE__.team_memberships active_tm where active_tm.season_id=target_season_id and active_tm.player_id=sp.player_id and active_tm.ends_at is null)
  order by lower(p.display_name), p.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_individual_standings(target_season_id uuid)
 RETURNS TABLE(season_id uuid, player_id uuid, display_name text, standings_rank integer, prize_rank integer, matches_played integer, minimum_matches integer, is_prize_eligible boolean, wins integer, losses integer, win_percentage numeric, games_won integer, games_lost integer, game_differential integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select standings.* from __LANE__.list_individual_standings_internal(target_season_id) standings where exists(select 1 from __LANE__.seasons season where season.id=target_season_id and season.purpose='league'); $function$;


CREATE OR REPLACE FUNCTION __LANE__.list_individual_standings_internal(target_season_id uuid)
 RETURNS TABLE(season_id uuid, player_id uuid, display_name text, standings_rank integer, prize_rank integer, matches_played integer, minimum_matches integer, is_prize_eligible boolean, wins integer, losses integer, win_percentage numeric, games_won integer, games_lost integer, game_differential integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
with target_season as (select s.id season_id,s.individual_min_matches from __LANE__.seasons s where s.id=target_season_id),
regular_player_results as (
select pm.season_id,pm.player_a_id player_id,case when pm.winner_side='A' then 1 else 0 end wins,case when pm.winner_side='B' then 1 else 0 end losses,pm.score_a games_won,pm.score_b games_lost from __LANE__.player_matches pm join __LANE__.rounds r on r.id=pm.round_id and r.season_id=pm.season_id where pm.season_id=target_season_id and r.stage='regular' and pm.status in ('finalized','corrected') and pm.winner_side in ('A','B')
union all
select pm.season_id,pm.player_b_id,case when pm.winner_side='B' then 1 else 0 end,case when pm.winner_side='A' then 1 else 0 end,pm.score_b,pm.score_a from __LANE__.player_matches pm join __LANE__.rounds r on r.id=pm.round_id and r.season_id=pm.season_id where pm.season_id=target_season_id and r.stage='regular' and pm.status in ('finalized','corrected') and pm.winner_side in ('A','B')),
player_pool as (select ts.season_id,tm.player_id from target_season ts join __LANE__.team_memberships tm on tm.season_id=ts.season_id union select ts.season_id,sp.player_id from target_season ts join __LANE__.season_players sp on sp.season_id=ts.season_id union select rpr.season_id,rpr.player_id from regular_player_results rpr),
player_totals as (select pp.season_id,pp.player_id,coalesce(sum(rpr.wins+rpr.losses),0)::integer matches_played,coalesce(sum(rpr.wins),0)::integer wins,coalesce(sum(rpr.losses),0)::integer losses,coalesce(sum(rpr.games_won),0)::integer games_won,coalesce(sum(rpr.games_lost),0)::integer games_lost from player_pool pp left join regular_player_results rpr on rpr.season_id=pp.season_id and rpr.player_id=pp.player_id group by pp.season_id,pp.player_id),
standings as (select pt.season_id,pt.player_id,p.display_name,pt.matches_played,ts.individual_min_matches::integer minimum_matches,(pt.matches_played>=ts.individual_min_matches) is_prize_eligible,pt.wins,pt.losses,case when pt.matches_played=0 then 0::numeric else round((pt.wins::numeric/pt.matches_played::numeric),4) end win_percentage,pt.games_won,pt.games_lost,(pt.games_won-pt.games_lost)::integer game_differential from player_totals pt join target_season ts on ts.season_id=pt.season_id join __LANE__.players p on p.id=pt.player_id),
eligible_standings as (select standings.player_id,(dense_rank() over(order by standings.win_percentage desc,standings.wins desc))::integer prize_rank from standings where standings.is_prize_eligible)
select standings.season_id,standings.player_id,standings.display_name,(dense_rank() over(order by standings.win_percentage desc,standings.wins desc))::integer standings_rank,eligible_standings.prize_rank,standings.matches_played,standings.minimum_matches,standings.is_prize_eligible,standings.wins,standings.losses,standings.win_percentage,standings.games_won,standings.games_lost,standings.game_differential from standings left join eligible_standings on eligible_standings.player_id=standings.player_id order by standings_rank,standings.is_prize_eligible desc,standings.display_name;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_joinable_team_registration()
 RETURNS TABLE(team_id uuid, team_name text, season_id uuid, season_name text, season_status text, slot_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  season_row record;
begin
  for season_row in
    select s.id from __LANE__.seasons s where s.status in ('registration', 'active')
  loop
    perform __LANE___private.expire_season_team_registration(season_row.id);
  end loop;

  return query
  select
    t.id,
    t.name,
    s.id,
    s.name,
    s.status,
    sts.status
  from __LANE___private.season_team_slots sts
  join __LANE__.teams t on t.id = sts.team_id
  join __LANE__.seasons s on s.id = sts.season_id
  where s.status in ('registration', 'active')
    and sts.status in ('approved_pending_roster', 'ready', 'confirmed')
  order by s.created_at desc, t.name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_league_chat_messages(actor_user_id uuid, target_season_id uuid, before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, before_message_id uuid DEFAULT NULL::uuid, result_limit integer DEFAULT 50)
 RETURNS TABLE(message_id uuid, season_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  if result_limit < 1 or result_limit > 100 then
    raise exception 'Message limit must be between 1 and 100';
  end if;
  select player.id into actor_player_id
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;
  if not __LANE___private.is_season_chat_participant(actor_player_id, target_season_id) then
    raise exception 'League chat access is required';
  end if;

  return query
  select page.message_id, page.season_id, page.author_player_id,
    page.author_display_name, page.body, page.created_at, page.is_own
  from (
    select message.id as message_id, message.season_id,
      message.author_player_id, author.display_name as author_display_name,
      message.body, message.created_at,
      message.author_player_id = actor_player_id as is_own
    from __LANE__.league_chat_messages message
    join __LANE__.players author on author.id = message.author_player_id
    where message.season_id = target_season_id
      and message.removed_at is null
      and (
        before_created_at is null
        or (message.created_at, message.id) < (
          before_created_at,
          coalesce(before_message_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
        )
      )
    order by message.created_at desc, message.id desc
    limit result_limit
  ) page
  order by page.created_at, page.message_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_matchup_chat_messages(actor_user_id uuid, target_team_match_id uuid, before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, before_message_id uuid DEFAULT NULL::uuid, result_limit integer DEFAULT 50)
 RETURNS TABLE(message_id uuid, team_match_id uuid, author_player_id uuid, author_display_name text, author_team_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare actor_player_id uuid;
begin
  if result_limit < 1 or result_limit > 100 then raise exception 'Message limit must be between 1 and 100'; end if;
  select player.id into actor_player_id from __LANE__.players player where player.user_id = actor_user_id;
  if actor_player_id is null then raise exception 'Player profile is required before using chat'; end if;
  if not exists (
    select 1 from __LANE__.team_matches match
    join __LANE__.team_memberships membership
      on membership.season_id = match.season_id
      and membership.team_id in (match.team_a_id, match.team_b_id)
      and membership.player_id = actor_player_id
    where match.id = target_team_match_id
  ) then raise exception 'Matchup chat access is required'; end if;

  return query
  select page.message_id, page.team_match_id, page.author_player_id,
    page.author_display_name, page.author_team_name, page.body, page.created_at, page.is_own
  from (
    select message.id message_id, message.team_match_id, message.author_player_id,
      author.display_name author_display_name, author_team.name author_team_name,
      message.body, message.created_at, message.author_player_id = actor_player_id is_own
    from __LANE__.matchup_chat_messages message
    join __LANE__.team_matches match on match.id = message.team_match_id
    join __LANE__.players author on author.id = message.author_player_id
    join __LANE__.teams author_team on author_team.id = message.author_team_id
    where message.team_match_id = target_team_match_id and message.removed_at is null
      and exists (
        select 1 from __LANE__.team_memberships membership
        where membership.player_id = actor_player_id
          and membership.season_id = match.season_id
          and membership.team_id in (match.team_a_id, match.team_b_id)
          and membership.starts_at <= message.created_at
          and (membership.ends_at is null or message.created_at < membership.ends_at)
      )
      and (
        before_created_at is null
        or (message.created_at, message.id) < (
          before_created_at,
          coalesce(before_message_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)
        )
      )
    order by message.created_at desc, message.id desc limit result_limit
  ) page
  order by page.created_at, page.message_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_my_team_match_choices(actor_user_id uuid)
 RETURNS TABLE(team_match_id uuid, season_id uuid, round_id uuid, round_number integer, scheduled_on date, stage text, team_a_id uuid, team_a_name text, team_b_id uuid, team_b_name text, selected_team_id uuid, choice_locked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before choosing a team'; end if;

  return query
  select
    tm.id,
    tm.season_id,
    tm.round_id,
    r.round_number,
    r.scheduled_on,
    r.stage::text,
    tm.team_a_id,
    team_a.name,
    tm.team_b_id,
    team_b.name,
    choice.team_id,
    exists (
      select 1
      from __LANE___private.team_lineups lineup
      join __LANE___private.team_lineup_slots slot on slot.lineup_id = lineup.id
      where lineup.team_match_id = tm.id
        and slot.player_id = actor_player_id
    )
  from __LANE__.team_matches tm
  join __LANE__.rounds r on r.id = tm.round_id
  join __LANE__.teams team_a on team_a.id = tm.team_a_id
  join __LANE__.teams team_b on team_b.id = tm.team_b_id
  left join __LANE___private.team_match_player_choices choice
    on choice.team_match_id = tm.id and choice.player_id = actor_player_id
  where tm.status not in ('finalized', 'corrected')
    and exists (
      select 1 from __LANE__.team_memberships member_a
      where member_a.season_id = tm.season_id
        and member_a.team_id = tm.team_a_id
        and member_a.player_id = actor_player_id
        and member_a.ends_at is null
    )
    and exists (
      select 1 from __LANE__.team_memberships member_b
      where member_b.season_id = tm.season_id
        and member_b.team_id = tm.team_b_id
        and member_b.player_id = actor_player_id
        and member_b.ends_at is null
    )
  order by r.scheduled_on nulls last, r.round_number, tm.table_number, tm.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_public_season_registration()
 RETURNS TABLE(id uuid, name text, status text, first_round_date date, team_capacity integer, minimum_committed_roster integer, team_count integer, confirmed_team_count integer, occupied_slots integer, open_team_slots integer, reserved_returning_slots integer, held_team_slots integer, applications_waiting integer, rostered_player_count integer, registered_player_count integer, free_agent_count integer, open_primary_roster_spots integer, at_risk_team_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select registration.* from __LANE__.list_all_season_registration_internal() registration join __LANE__.seasons season on season.id=registration.id where season.purpose='league'; $function$;


CREATE OR REPLACE FUNCTION __LANE__.list_publishable_season_teams(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(id uuid, active boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  perform __LANE___private.expire_season_team_registration(target_season_id);

  return query
  select sts.team_id, true
  from __LANE___private.season_team_slots sts
  join __LANE__.seasons s on s.id = sts.season_id
  join __LANE__.teams t on t.id = sts.team_id
  where sts.season_id = target_season_id
    and sts.status = 'confirmed'
    and __LANE___private.committed_team_roster_count(sts.team_id, sts.season_id)
        >= s.minimum_committed_roster
  order by t.name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_sandbox_feedback(actor_user_id uuid, status_filter text DEFAULT 'open'::text, result_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, feedback_actor_user_id uuid, surface text, page_path text, context jsonb, comment text, status text, created_at timestamp with time zone, reviewed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'League admin access is required';
  end if;
  if status_filter is not null and status_filter not in ('open', 'reviewed') then
    raise exception 'Invalid feedback status';
  end if;
  if result_limit not between 1 and 250 then
    raise exception 'result_limit must be between 1 and 250';
  end if;

  return query
  select sf.id,
         sf.actor_user_id,
         sf.surface,
         sf.page_path,
         sf.context,
         sf.comment,
         sf.status,
         sf.created_at,
         sf.reviewed_at
  from __LANE___private.sandbox_feedback sf
  where status_filter is null or sf.status = status_filter
  order by sf.created_at desc
  limit result_limit;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_scorable_player_matches(actor_user_id uuid)
 RETURNS TABLE(player_match_id uuid, season_id uuid, season_name text, round_id uuid, round_number integer, scheduled_on date, team_match_id uuid, slot_number integer, status text, team_a_name text, team_b_name text, player_a_name text, player_b_name text, scoring_team_id uuid, scoring_team_name text, editable_side text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ with actor as(select p.id as player_id from __LANE__.players p where p.user_id=actor_user_id limit 1) select pm.id,pm.season_id,s.name,pm.round_id,r.round_number,r.scheduled_on,pm.team_match_id,pm.slot_number,pm.status,ta.name,tb.name,pa.display_name,pb.display_name,tm.team_id,case when tm.team_id=pm.team_a_id then ta.name else tb.name end,case when tm.team_id=pm.team_a_id then 'A' else 'B' end from __LANE__.player_matches pm join actor a on true join __LANE__.team_memberships tm on tm.player_id=a.player_id and tm.season_id=pm.season_id and tm.ends_at is null and tm.team_id in(pm.team_a_id,pm.team_b_id) join __LANE__.seasons s on s.id=pm.season_id join __LANE__.rounds r on r.id=pm.round_id join __LANE__.teams ta on ta.id=pm.team_a_id join __LANE__.teams tb on tb.id=pm.team_b_id join __LANE__.players pa on pa.id=pm.player_a_id join __LANE__.players pb on pb.id=pm.player_b_id where pm.status not in('finalized','corrected') order by case when r.scheduled_on>=current_date then 0 else 1 end,abs(r.scheduled_on-current_date),r.round_number,pm.slot_number,tm.team_id; $function$;


CREATE OR REPLACE FUNCTION __LANE__.list_team_chat_messages(actor_user_id uuid, target_team_id uuid, before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, result_limit integer DEFAULT 50)
 RETURNS TABLE(message_id uuid, team_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  if result_limit < 1 or result_limit > 100 then
    raise exception 'Message limit must be between 1 and 100';
  end if;

  if not exists (select 1 from __LANE__.teams t where t.id = target_team_id) then
    raise exception 'Team not found';
  end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;

  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player_id
  ) then
    raise exception 'No team chat access';
  end if;

  return query
  select page.message_id, page.team_id, page.author_player_id,
    page.author_display_name, page.body, page.created_at, page.is_own
  from (
    select m.id as message_id, m.team_id, m.author_player_id,
      author.display_name as author_display_name, m.body, m.created_at,
      m.author_player_id = actor_player_id as is_own
    from __LANE__.team_chat_messages m
    join __LANE__.players author on author.id = m.author_player_id
    where m.team_id = target_team_id
      and m.removed_at is null
      and (before_created_at is null or m.created_at < before_created_at)
      and exists (
        select 1
        from __LANE__.team_memberships access_membership
        where access_membership.team_id = m.team_id
          and access_membership.player_id = actor_player_id
          and m.created_at >= access_membership.starts_at
          and (
            access_membership.ends_at is null
            or m.created_at <= access_membership.ends_at
          )
      )
    order by m.created_at desc, m.id desc
    limit result_limit
  ) page
  order by page.created_at, page.message_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_team_round_availability(actor_user_id uuid, target_team_id uuid, target_round_id uuid)
 RETURNS TABLE(season_id uuid, round_id uuid, team_id uuid, player_id uuid, display_name text, role text, participation_type text, fargo_rating integer, rating_status text, availability_status text, updated_at timestamp with time zone, payment_status text, regular_matches_scheduled integer, eligible boolean, eligibility_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_round __LANE__.rounds%rowtype;
  target_match __LANE__.team_matches%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before viewing team availability'; end if;

  select r.* into target_round
  from __LANE__.rounds r
  join __LANE__.teams t on t.season_id = r.season_id
  where r.id = target_round_id
    and t.id = target_team_id
    and r.stage = 'regular';
  if not found then raise exception 'Regular-season round not found for team season'; end if;
  if target_round.scheduled_on is null then raise exception 'Round does not have a scheduled date'; end if;

  select * into target_match
  from __LANE__.team_matches tm
  where tm.round_id = target_round_id
    and (tm.team_a_id = target_team_id or tm.team_b_id = target_team_id);
  if not found then raise exception 'Team is not scheduled for target round'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships membership
    where membership.team_id = target_team_id
      and membership.player_id = actor_player_id
      and membership.role = 'captain'
      and membership.ends_at is null
  ) then raise exception 'Only the active captain can view team round availability'; end if;

  return query
  with scheduled_counts as (
    select slot.player_id, count(*)::integer as match_count
    from __LANE___private.team_lineup_slots slot
    join __LANE__.rounds r on r.id = slot.round_id
    where slot.season_id = target_round.season_id
      and slot.player_id is not null
      and r.stage = 'regular'
    group by slot.player_id
  ),
  candidates as (
    -- Full own roster. Missing date response is explicitly Unsure.
    select
      0 as sort_order,
      membership.season_id,
      target_round_id as round_id,
      membership.team_id,
      p.id as player_id,
      p.display_name,
      membership.role,
      'roster'::text as participation_type,
      rating.fargo_rating,
      rating.rating_status,
      coalesce(availability.status, 'unsure'::text) as availability_status,
      availability.updated_at
    from __LANE__.team_memberships membership
    join __LANE__.players p on p.id = membership.player_id
    left join __LANE__.player_ratings rating on rating.player_id = membership.player_id
    left join __LANE___private.player_date_availability availability
      on availability.season_id = target_round.season_id
     and availability.player_id = membership.player_id
     and availability.availability_date = target_round.scheduled_on
    where membership.team_id = target_team_id
      and membership.season_id = target_round.season_id
      and membership.ends_at is null

    union all

    -- Any active season player outside this roster may substitute when that player
    -- explicitly marked the selected calendar date Available. Team membership is
    -- not required, and membership on another team does not hide the player.
    select
      1 as sort_order,
      sp.season_id,
      target_round_id,
      target_team_id,
      p.id,
      p.display_name,
      null::text,
      'substitute'::text,
      rating.fargo_rating,
      rating.rating_status,
      availability.status,
      availability.updated_at
    from __LANE__.season_players sp
    join __LANE__.players p on p.id = sp.player_id
    join __LANE___private.player_date_availability availability
      on availability.season_id = sp.season_id
     and availability.player_id = sp.player_id
     and availability.availability_date = target_round.scheduled_on
     and availability.status = 'available'
    left join __LANE__.player_ratings rating on rating.player_id = p.id
    where sp.season_id = target_round.season_id
      and sp.status = 'active'
      and not exists (
        select 1 from __LANE__.team_memberships own_membership
        where own_membership.season_id = target_round.season_id
          and own_membership.team_id = target_team_id
          and own_membership.player_id = p.id
          and own_membership.ends_at is null
      )
  ),
  choice_state as (
    select
      candidate.*,
      exists (
        select 1 from __LANE__.team_memberships member_a
        where member_a.season_id = target_round.season_id
          and member_a.team_id = target_match.team_a_id
          and member_a.player_id = candidate.player_id
          and member_a.ends_at is null
      ) and exists (
        select 1 from __LANE__.team_memberships member_b
        where member_b.season_id = target_round.season_id
          and member_b.team_id = target_match.team_b_id
          and member_b.player_id = candidate.player_id
          and member_b.ends_at is null
      ) as needs_choice,
      (
        select choice.team_id
        from __LANE___private.team_match_player_choices choice
        where choice.team_match_id = target_match.id
          and choice.player_id = candidate.player_id
      ) as selected_team_id,
      exists (
        select 1
        from __LANE___private.team_lineups opposing_lineup
        join __LANE___private.team_lineup_slots opposing_slot
          on opposing_slot.lineup_id = opposing_lineup.id
        where opposing_lineup.team_match_id = target_match.id
          and opposing_lineup.team_id <> target_team_id
          and opposing_slot.player_id = candidate.player_id
      ) as already_opponent
    from candidates candidate
  )
  select
    state.season_id,
    state.round_id,
    state.team_id,
    state.player_id,
    state.display_name,
    state.role,
    state.participation_type,
    state.fargo_rating,
    state.rating_status,
    state.availability_status,
    state.updated_at,
    coalesce(payment.status, 'unpaid') as payment_status,
    coalesce(scheduled.match_count, 0) as regular_matches_scheduled,
    (
      coalesce(payment.status, 'unpaid') in ('paid', 'waived')
      and coalesce(scheduled.match_count, 0) < 7
      and not state.already_opponent
      and (not state.needs_choice or state.selected_team_id = target_team_id)
    ) as eligible,
    case
      when coalesce(payment.status, 'unpaid') not in ('paid', 'waived')
        then 'Payment required before playing'
      when coalesce(scheduled.match_count, 0) >= 7
        then 'Season limit reached (7/7)'
      when state.already_opponent
        then 'Already committed in this matchup'
      when state.needs_choice and state.selected_team_id is null
        then 'Player must choose a team for this matchup'
      when state.needs_choice and state.selected_team_id <> target_team_id
        then 'Playing for the opponent in this matchup'
      else null
    end as eligibility_reason
  from choice_state state
  left join __LANE___private.payment_status payment
    on payment.season_id = target_round.season_id
   and payment.player_id = state.player_id
  left join scheduled_counts scheduled on scheduled.player_id = state.player_id
  order by
    state.sort_order,
    case state.availability_status
      when 'available' then 0 when 'unsure' then 1 when 'unavailable' then 2 else 1 end,
    lower(state.display_name),
    state.player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_team_standings(target_season_id uuid)
 RETURNS TABLE(season_id uuid, team_id uuid, team_name text, standings_rank integer, games_played integer, maximum_matches integer, standing_points integer, team_wins integer, team_losses integer, team_draws integer, match_points integer, match_points_against integer, point_differential integer, player_match_wins integer, player_match_losses integer, forfeits_won integer, forfeits_lost integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select standings.* from __LANE__.list_team_standings_internal(target_season_id) standings where exists(select 1 from __LANE__.seasons season where season.id=target_season_id and season.purpose='league'); $function$;


CREATE OR REPLACE FUNCTION __LANE__.list_team_standings_internal(target_season_id uuid)
 RETURNS TABLE(season_id uuid, team_id uuid, team_name text, standings_rank integer, games_played integer, maximum_matches integer, standing_points integer, team_wins integer, team_losses integer, team_draws integer, match_points integer, match_points_against integer, point_differential integer, player_match_wins integer, player_match_losses integer, forfeits_won integer, forfeits_lost integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with season_teams as (
    select t.season_id, t.id as team_id, t.name as team_name
    from __LANE__.teams t
    where t.season_id = target_season_id
  ),
  regular_team_matches as (
    select tm.*
    from __LANE__.team_matches tm
    join __LANE__.rounds r
      on r.id = tm.round_id
     and r.season_id = tm.season_id
    where tm.season_id = target_season_id
      and r.stage = 'regular'
  ),
  team_schedule as (
    select scheduled.team_id, count(*)::integer as maximum_matches
    from (
      select rtm.team_a_id as team_id
      from regular_team_matches rtm
      union all
      select rtm.team_b_id as team_id
      from regular_team_matches rtm
    ) scheduled
    group by scheduled.team_id
  ),
  slot_results as (
    select pm.team_match_id, pm.slot_number
    from __LANE__.player_matches pm
    join regular_team_matches rtm
      on rtm.id = pm.team_match_id
    where pm.status in ('finalized', 'corrected')
      and pm.winner_side in ('A', 'B')

    union

    select tmf.team_match_id, tmf.slot_number
    from __LANE__.team_match_forfeits tmf
    join regular_team_matches rtm
      on rtm.id = tmf.team_match_id
  ),
  complete_team_matches as (
    select rtm.*
    from regular_team_matches rtm
    join slot_results sr
      on sr.team_match_id = rtm.id
    group by rtm.id, rtm.season_id, rtm.round_id, rtm.table_number, rtm.team_a_id, rtm.team_b_id,
      rtm.status, rtm.winner_team_id, rtm.created_at
    having count(distinct sr.slot_number) = 3
      and not exists (
        select 1
        from __LANE__.team_match_forfeits unresolved
        where unresolved.team_match_id = rtm.id
          and unresolved.credited_team_id is null
      )
  ),
  team_match_sides as (
    select
      ctm.id as team_match_id,
      ctm.season_id,
      ctm.team_a_id as team_id,
      ctm.team_b_id as opponent_team_id
    from complete_team_matches ctm

    union all

    select
      ctm.id as team_match_id,
      ctm.season_id,
      ctm.team_b_id as team_id,
      ctm.team_a_id as opponent_team_id
    from complete_team_matches ctm
  ),
  slot_points as (
    select
      pm.team_match_id,
      pm.team_a_id as team_id,
      case when pm.winner_side = 'A' then 1 else 0 end as match_points,
      case when pm.winner_side = 'A' then 1 else 0 end as player_match_wins,
      case when pm.winner_side = 'B' then 1 else 0 end as player_match_losses,
      0 as forfeits_won,
      0 as forfeits_lost
    from __LANE__.player_matches pm
    join complete_team_matches ctm
      on ctm.id = pm.team_match_id
    where pm.status in ('finalized', 'corrected')
      and pm.winner_side in ('A', 'B')

    union all

    select
      pm.team_match_id,
      pm.team_b_id as team_id,
      case when pm.winner_side = 'B' then 1 else 0 end as match_points,
      case when pm.winner_side = 'B' then 1 else 0 end as player_match_wins,
      case when pm.winner_side = 'A' then 1 else 0 end as player_match_losses,
      0 as forfeits_won,
      0 as forfeits_lost
    from __LANE__.player_matches pm
    join complete_team_matches ctm
      on ctm.id = pm.team_match_id
    where pm.status in ('finalized', 'corrected')
      and pm.winner_side in ('A', 'B')

    union all

    select
      tmf.team_match_id,
      tmf.credited_team_id as team_id,
      1 as match_points,
      0 as player_match_wins,
      0 as player_match_losses,
      1 as forfeits_won,
      0 as forfeits_lost
    from __LANE__.team_match_forfeits tmf
    join complete_team_matches ctm
      on ctm.id = tmf.team_match_id
    where tmf.credited_team_id is not null

    union all

    select
      tmf.team_match_id,
      tmf.forfeiting_team_id as team_id,
      0 as match_points,
      0 as player_match_wins,
      0 as player_match_losses,
      0 as forfeits_won,
      1 as forfeits_lost
    from __LANE__.team_match_forfeits tmf
    join complete_team_matches ctm
      on ctm.id = tmf.team_match_id
  ),
  team_match_points as (
    select
      sp.team_match_id,
      sp.team_id,
      coalesce(sum(sp.match_points), 0)::integer as match_points,
      coalesce(sum(sp.player_match_wins), 0)::integer as player_match_wins,
      coalesce(sum(sp.player_match_losses), 0)::integer as player_match_losses,
      coalesce(sum(sp.forfeits_won), 0)::integer as forfeits_won,
      coalesce(sum(sp.forfeits_lost), 0)::integer as forfeits_lost
    from slot_points sp
    group by sp.team_match_id, sp.team_id
  ),
  team_match_results as (
    select
      sides.season_id,
      sides.team_match_id,
      sides.team_id,
      coalesce(own.match_points, 0)::integer as match_points,
      coalesce(opponent.match_points, 0)::integer as match_points_against,
      coalesce(own.player_match_wins, 0)::integer as player_match_wins,
      coalesce(own.player_match_losses, 0)::integer as player_match_losses,
      coalesce(own.forfeits_won, 0)::integer as forfeits_won,
      coalesce(own.forfeits_lost, 0)::integer as forfeits_lost,
      case
        when coalesce(own.match_points, 0) > coalesce(opponent.match_points, 0) then 1
        else 0
      end as team_wins,
      case
        when coalesce(own.match_points, 0) < coalesce(opponent.match_points, 0) then 1
        else 0
      end as team_losses,
      0::integer as team_draws
    from team_match_sides sides
    left join team_match_points own
      on own.team_match_id = sides.team_match_id
     and own.team_id = sides.team_id
    left join team_match_points opponent
      on opponent.team_match_id = sides.team_match_id
     and opponent.team_id = sides.opponent_team_id
  ),
  team_totals as (
    select
      tmr.season_id,
      tmr.team_id,
      count(*)::integer as games_played,
      coalesce(sum(tmr.team_wins), 0)::integer as team_wins,
      coalesce(sum(tmr.team_losses), 0)::integer as team_losses,
      0::integer as team_draws,
      coalesce(sum(tmr.team_wins * 2), 0)::integer as standing_points,
      coalesce(sum(tmr.match_points), 0)::integer as match_points,
      coalesce(sum(tmr.match_points_against), 0)::integer as match_points_against,
      coalesce(sum(tmr.player_match_wins), 0)::integer as player_match_wins,
      coalesce(sum(tmr.player_match_losses), 0)::integer as player_match_losses,
      coalesce(sum(tmr.forfeits_won), 0)::integer as forfeits_won,
      coalesce(sum(tmr.forfeits_lost), 0)::integer as forfeits_lost
    from team_match_results tmr
    group by tmr.season_id, tmr.team_id
  ),
  standings as (
    select
      st.season_id,
      st.team_id,
      st.team_name,
      coalesce(tt.games_played, 0)::integer as games_played,
      coalesce(ts.maximum_matches, 0)::integer as maximum_matches,
      coalesce(tt.standing_points, 0)::integer as standing_points,
      coalesce(tt.team_wins, 0)::integer as team_wins,
      coalesce(tt.team_losses, 0)::integer as team_losses,
      0::integer as team_draws,
      coalesce(tt.match_points, 0)::integer as match_points,
      coalesce(tt.match_points_against, 0)::integer as match_points_against,
      (coalesce(tt.match_points, 0) - coalesce(tt.match_points_against, 0))::integer as point_differential,
      coalesce(tt.player_match_wins, 0)::integer as player_match_wins,
      coalesce(tt.player_match_losses, 0)::integer as player_match_losses,
      coalesce(tt.forfeits_won, 0)::integer as forfeits_won,
      coalesce(tt.forfeits_lost, 0)::integer as forfeits_lost
    from season_teams st
    left join team_totals tt
      on tt.team_id = st.team_id
    left join team_schedule ts
      on ts.team_id = st.team_id
  )
  select
    standings.season_id,
    standings.team_id,
    standings.team_name,
    dense_rank() over (
      order by
        standings.standing_points desc,
        standings.match_points desc,
        standings.point_differential desc
    )::integer as standings_rank,
    standings.games_played,
    standings.maximum_matches,
    standings.standing_points,
    standings.team_wins,
    standings.team_losses,
    standings.team_draws,
    standings.match_points,
    standings.match_points_against,
    standings.point_differential,
    standings.player_match_wins,
    standings.player_match_losses,
    standings.forfeits_won,
    standings.forfeits_lost
  from standings
  order by standings_rank, standings.team_name;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.list_visible_team_lineups(actor_user_id uuid, target_team_id uuid, target_round_id uuid)
 RETURNS TABLE(lineup_id uuid, season_id uuid, round_id uuid, team_match_id uuid, team_id uuid, is_own_team boolean, opponent_lineup_visible boolean, slot_number integer, player_id uuid, display_name text, fargo_rating integer, rating_status text, participation_type text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_player_id uuid; target_round __LANE__.rounds%rowtype; target_match __LANE__.team_matches%rowtype; opponent_visible boolean;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_team_id is null then raise exception 'target_team_id is required'; end if;
if target_round_id is null then raise exception 'target_round_id is required'; end if;
select * into target_round from __LANE__.rounds r where r.id=target_round_id; if not found then raise exception 'Round not found'; end if;
select * into target_match from __LANE__.team_matches tm where tm.round_id=target_round_id and (tm.team_a_id=target_team_id or tm.team_b_id=target_team_id); if not found then raise exception 'Team is not scheduled for target round'; end if;
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id; if not found then raise exception 'Player profile is required before viewing lineups'; end if;
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=target_team_id and tm.player_id=actor_player_id and tm.role='captain' and tm.ends_at is null) then raise exception 'Only the active captain can view team lineups'; end if;
opponent_visible := (exists(select 1 from __LANE___private.team_lineups h where h.team_match_id=target_match.id and h.team_id=target_match.team_a_id) and exists(select 1 from __LANE___private.team_lineups a where a.team_match_id=target_match.id and a.team_id=target_match.team_b_id));
return query select tl.id,tl.season_id,tl.round_id,tl.team_match_id,tl.team_id,tl.team_id=target_team_id,opponent_visible,tls.slot_number,tls.player_id,p.display_name,pr.fargo_rating,pr.rating_status,tls.participation_type,tl.submitted_at from __LANE___private.team_lineups tl join __LANE___private.team_lineup_slots tls on tls.lineup_id=tl.id left join __LANE__.players p on p.id=tls.player_id left join __LANE__.player_ratings pr on pr.player_id=tls.player_id where tl.team_match_id=target_match.id and (tl.team_id=target_team_id or opponent_visible) order by case when tl.team_id=target_team_id then 0 else 1 end,tls.slot_number;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.mark_direct_chat_read(actor_user_id uuid, target_conversation_id uuid, read_through_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(conversation_id uuid, player_id uuid, last_read_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  effective_read_at timestamptz := least(coalesce(read_through_at, now()), now());
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  if not exists (
    select 1
    from __LANE__.direct_conversations conversation
    where conversation.id = target_conversation_id
      and actor_player_id in (conversation.player_low_id, conversation.player_high_id)
  ) then
    raise exception 'Direct conversation not found';
  end if;

  insert into __LANE__.direct_chat_reads (conversation_id, player_id, last_read_at)
  values (target_conversation_id, actor_player_id, effective_read_at)
  on conflict on constraint direct_chat_reads_pkey
  do update set last_read_at = greatest(
    __LANE__.direct_chat_reads.last_read_at,
    excluded.last_read_at
  );

  return query
  select read_state.conversation_id, read_state.player_id, read_state.last_read_at
  from __LANE__.direct_chat_reads read_state
  where read_state.conversation_id = target_conversation_id
    and read_state.player_id = actor_player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.mark_league_chat_read(actor_user_id uuid, target_season_id uuid, read_through_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(season_id uuid, player_id uuid, last_read_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select player.id into actor_player_id
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;
  if not __LANE___private.is_season_chat_participant(actor_player_id, target_season_id) then
    raise exception 'League chat access is required';
  end if;

  return query
  insert into __LANE__.league_chat_reads (season_id, player_id, last_read_at)
  values (target_season_id, actor_player_id, coalesce(read_through_at, clock_timestamp()))
  on conflict on constraint league_chat_reads_pkey
  do update set
    last_read_at = greatest(__LANE__.league_chat_reads.last_read_at, excluded.last_read_at),
    updated_at = clock_timestamp()
  returning __LANE__.league_chat_reads.season_id,
    __LANE__.league_chat_reads.player_id,
    __LANE__.league_chat_reads.last_read_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.mark_matchup_chat_read(actor_user_id uuid, target_team_match_id uuid, read_through_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(team_match_id uuid, player_id uuid, last_read_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select player.id into actor_player_id
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;
  if not exists (
    select 1
    from __LANE__.team_matches match
    join __LANE__.team_memberships membership
      on membership.season_id = match.season_id
      and membership.team_id in (match.team_a_id, match.team_b_id)
      and membership.player_id = actor_player_id
    where match.id = target_team_match_id
  ) then
    raise exception 'Matchup chat access is required';
  end if;

  return query
  insert into __LANE__.matchup_chat_reads (team_match_id, player_id, last_read_at)
  values (target_team_match_id, actor_player_id, coalesce(read_through_at, clock_timestamp()))
  on conflict on constraint matchup_chat_reads_pkey
  do update set
    last_read_at = greatest(__LANE__.matchup_chat_reads.last_read_at, excluded.last_read_at),
    updated_at = clock_timestamp()
  returning __LANE__.matchup_chat_reads.team_match_id,
    __LANE__.matchup_chat_reads.player_id,
    __LANE__.matchup_chat_reads.last_read_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.mark_team_chat_read(actor_user_id uuid, target_team_id uuid, read_through_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(team_id uuid, player_id uuid, last_read_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  effective_read_at timestamptz := least(coalesce(read_through_at, now()), now());
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  select tm.season_id into target_season_id
  from __LANE__.team_memberships tm
  where tm.team_id = target_team_id
    and tm.player_id = actor_player_id
    and tm.ends_at is null;
  if target_season_id is null then
    raise exception 'Active team membership is required to mark chat read';
  end if;

  insert into __LANE__.team_chat_reads (season_id, team_id, player_id, last_read_at)
  values (target_season_id, target_team_id, actor_player_id, effective_read_at)
  on conflict on constraint team_chat_reads_pkey
  do update set last_read_at = greatest(
    __LANE__.team_chat_reads.last_read_at,
    excluded.last_read_at
  );

  return query
  select read_state.team_id, read_state.player_id, read_state.last_read_at
  from __LANE__.team_chat_reads read_state
  where read_state.team_id = target_team_id
    and read_state.player_id = actor_player_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.moderate_chat_message_report(actor_user_id uuid, target_report_id uuid, resolution text, moderation_note text DEFAULT NULL::text, remove_message boolean DEFAULT false)
 RETURNS TABLE(report_id uuid, status text, reviewed_at timestamp with time zone, message_removed boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare report __LANE__.chat_message_reports%rowtype; resolved_at timestamptz := clock_timestamp();
begin
  if not exists (select 1 from __LANE___private.league_admins admin where admin.user_id = actor_user_id) then raise exception 'League admin access is required'; end if;
  resolution := lower(btrim(resolution)); moderation_note := nullif(btrim(moderation_note), '');
  if resolution not in ('resolved', 'dismissed') then raise exception 'Resolution must be resolved or dismissed'; end if;
  if remove_message and resolution <> 'resolved' then raise exception 'A removed message must use resolved status'; end if;
  if moderation_note is not null and char_length(moderation_note) > 2000 then raise exception 'Moderation note cannot exceed 2000 characters'; end if;
  select target.* into report from __LANE__.chat_message_reports target where target.id = target_report_id for update;
  if report.id is null then raise exception 'Chat report not found'; end if;
  if remove_message then
    if report.target_type = 'team' then update __LANE__.team_chat_messages set removed_at = resolved_at, removed_by = actor_user_id where id = report.team_message_id;
    elsif report.target_type = 'direct' then update __LANE__.direct_messages set removed_at = resolved_at, removed_by = actor_user_id where id = report.direct_message_id;
    elsif report.target_type = 'league' then update __LANE__.league_chat_messages set removed_at = resolved_at, removed_by = actor_user_id where id = report.league_message_id;
    else update __LANE__.matchup_chat_messages set removed_at = resolved_at, removed_by = actor_user_id where id = report.matchup_message_id;
    end if;
  end if;
  update __LANE__.chat_message_reports target set status = resolution, reviewed_at = resolved_at,
    reviewed_by = actor_user_id, resolution_note = moderation_note where target.id = report.id;
  return query select report.id, resolution, resolved_at, remove_message;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.propose_team_trade(actor_user_id uuid, actor_team_id uuid, offered_roster_player_id uuid, requested_roster_team_id uuid, requested_roster_player_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, requesting_team_id uuid, requested_team_id uuid, offered_player_id uuid, requested_player_id uuid, status text, admin_exception boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_season_id uuid;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if actor_team_id is null or requested_roster_team_id is null then
    raise exception 'Both trade teams are required';
  end if;

  if offered_roster_player_id is null or requested_roster_player_id is null then
    raise exception 'Both trade players are required';
  end if;

  select t.season_id
    into target_season_id
  from __LANE__.teams t
  where t.id = actor_team_id;

  if not found then
    raise exception 'Team not found';
  end if;

  if not exists (
    select 1
    from __LANE__.teams t
    where t.id = requested_roster_team_id
      and t.season_id = target_season_id
  ) then
    raise exception 'Trade teams must be in the same season';
  end if;

  if __LANE___private.season_roster_lock_has_passed(target_season_id) then
    raise exception 'Roster lock has passed; admin exception required';
  end if;

  if not __LANE___private.actor_captains_team(actor_user_id, actor_team_id) then
    raise exception 'Only the active captain can propose a trade';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = actor_team_id
      and tm.player_id = offered_roster_player_id
      and tm.role = 'player'
      and tm.ends_at is null
  ) then
    raise exception 'Offered player must be an active non-captain roster member';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = requested_roster_team_id
      and tm.player_id = requested_roster_player_id
      and tm.role = 'player'
      and tm.ends_at is null
  ) then
    raise exception 'Requested player must be an active non-captain roster member';
  end if;

  if exists (
    select 1
    from __LANE___private.team_trades tt
    where tt.season_id = target_season_id
      and tt.status = 'pending'
      and (
        offered_roster_player_id in (tt.offered_player_id, tt.requested_player_id)
        or requested_roster_player_id in (tt.offered_player_id, tt.requested_player_id)
      )
  ) then
    raise exception 'A pending trade already includes one of these players';
  end if;

  return query
  insert into __LANE___private.team_trades (
    season_id,
    requesting_team_id,
    requested_team_id,
    offered_player_id,
    requested_player_id,
    proposed_by_user_id,
    requesting_captain_approved_at
  ) values (
    target_season_id,
    actor_team_id,
    requested_roster_team_id,
    offered_roster_player_id,
    requested_roster_player_id,
    actor_user_id,
    now()
  )
  returning
    team_trades.id,
    team_trades.season_id,
    team_trades.requesting_team_id,
    team_trades.requested_team_id,
    team_trades.offered_player_id,
    team_trades.requested_player_id,
    team_trades.status,
    team_trades.admin_exception,
    team_trades.created_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.publish_season_schedule(target_season_id uuid, actor_user_id uuid, expected_previous_status text, rounds_payload jsonb)
 RETURNS TABLE(round_count integer, team_match_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_status text;
  required_team_count integer;
  viable_team_count integer;
  existing_round_count integer;
  existing_match_count integer;
  inserted_round_id uuid;
  inserted_round_count integer := 0;
  inserted_match_count integer := 0;
  round_item jsonb;
  match_item jsonb;
begin
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if not exists(select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id) then
    raise exception 'Actor is not a league admin';
  end if;
  if jsonb_typeof(rounds_payload) is distinct from 'array' then
    raise exception 'rounds_payload must be an array';
  end if;

  perform __LANE___private.expire_season_team_registration(target_season_id);
  select s.status, s.team_capacity into current_status, required_team_count
  from __LANE__.seasons s where s.id = target_season_id for update;
  if not found then raise exception 'Season not found'; end if;

  if current_status = 'active' then
    select count(*)::integer into existing_round_count
    from __LANE__.rounds r
    where r.season_id = target_season_id;

    select count(*)::integer into existing_match_count
    from __LANE__.team_matches tm
    where tm.season_id = target_season_id;

    if existing_round_count <> 7 or existing_match_count <> 28 then
      raise exception 'Active season schedule is incomplete';
    end if;

    round_count := existing_round_count;
    team_match_count := existing_match_count;
    return next;
    return;
  end if;

  if current_status is distinct from expected_previous_status then raise exception 'Season status changed'; end if;
  if current_status not in ('draft', 'registration') then
    raise exception 'Season must be draft or registration to publish';
  end if;

  select count(*)::integer into viable_team_count
  from __LANE___private.season_team_slots sts
  where sts.season_id = target_season_id
    and sts.status = 'confirmed'
    and (
      select count(*) from __LANE__.team_memberships tm
      where tm.team_id = sts.team_id and tm.ends_at is null
    ) >= (
      select s.minimum_committed_roster from __LANE__.seasons s where s.id = target_season_id
    );

  if viable_team_count <> required_team_count then
    raise exception 'Season requires exactly % confirmed teams meeting the minimum roster before publication', required_team_count;
  end if;
  if exists(select 1 from __LANE__.rounds r where r.season_id = target_season_id) then
    raise exception 'Season schedule already exists';
  end if;

  update __LANE__.seasons set status = 'active' where id = target_season_id;
  for round_item in select value from jsonb_array_elements(rounds_payload) loop
    if jsonb_typeof(round_item->'matches') is distinct from 'array' then
      raise exception 'round matches must be an array';
    end if;
    insert into __LANE__.rounds(season_id, round_number, stage, scheduled_on)
    values(
      target_season_id,
      (round_item->>'roundNumber')::integer,
      coalesce(round_item->>'stage', 'regular'),
      (round_item->>'scheduledOn')::date
    ) returning id into inserted_round_id;
    inserted_round_count := inserted_round_count + 1;
    for match_item in select value from jsonb_array_elements(round_item->'matches') loop
      insert into __LANE__.team_matches(season_id, round_id, table_number, team_a_id, team_b_id)
      values(
        target_season_id,
        inserted_round_id,
        (match_item->>'tableNumber')::integer,
        (match_item->>'teamAId')::uuid,
        (match_item->>'teamBId')::uuid
      );
      inserted_match_count := inserted_match_count + 1;
    end loop;
  end loop;
  if inserted_round_count <> 7 then raise exception 'Season 1 publication requires 7 rounds'; end if;
  if inserted_match_count <> 28 then raise exception 'Season 1 publication requires 28 team matches'; end if;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, before_state, after_state)
  values(
    actor_user_id,
    'season.publish_schedule',
    'season',
    target_season_id,
    jsonb_build_object('status', current_status),
    jsonb_build_object('status', 'active', 'roundCount', inserted_round_count, 'teamMatchCount', inserted_match_count)
  );
  round_count := inserted_round_count;
  team_match_count := inserted_match_count;
  return next;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.record_player_match_rack(actor_user_id uuid, target_player_match_id uuid, rack_winner_side text)
 RETURNS TABLE(player_match_id uuid, rack_number integer, discipline text, winner_side text, score_a integer, score_b integer, current_discipline text, match_winner_side text, winner_player_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_match __LANE__.player_matches%rowtype; next_rack_number integer; rack_discipline text; next_score_a integer; next_score_b integer; next_current_discipline text; next_winner_side text; next_winner_player_id uuid;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
if rack_winner_side not in ('A','B') then raise exception 'rack_winner_side must be A or B'; end if;
select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update;
if not found then raise exception 'Player match not found'; end if;
if target_match.status in ('finalized','corrected') then raise exception 'Player match is finalized'; end if;
if target_match.winner_side is not null then raise exception 'Player match is already complete'; end if;
if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before recording racks'; end if;
if not __LANE___private.can_score_player_match(actor_user_id,target_match) then raise exception 'Only match players or active team captains can record racks'; end if;
select coalesce(max(rack_number),0)+1 into next_rack_number from __LANE__.player_match_racks pmr where pmr.player_match_id=target_player_match_id;
rack_discipline:=target_match.current_discipline; next_score_a:=target_match.score_a+case when rack_winner_side='A' then 1 else 0 end; next_score_b:=target_match.score_b+case when rack_winner_side='B' then 1 else 0 end; next_current_discipline:=target_match.current_discipline; next_winner_side:=null; next_winner_player_id:=null;
if next_score_a>=target_match.race_to_a then next_winner_side:='A'; next_winner_player_id:=target_match.player_a_id; elsif next_score_b>=target_match.race_to_b then next_winner_side:='B'; next_winner_player_id:=target_match.player_b_id; elsif next_rack_number=target_match.opening_block_length then next_current_discipline:=case when target_match.opening_discipline='8-ball' then '9-ball' else '8-ball' end; end if;
insert into __LANE__.player_match_racks(season_id,player_match_id,rack_number,discipline,winner_side,winner_player_id,recorded_by) values(target_match.season_id,target_player_match_id,next_rack_number,rack_discipline,rack_winner_side,case when rack_winner_side='A' then target_match.player_a_id else target_match.player_b_id end,actor_user_id);
update __LANE__.player_matches set score_a=next_score_a,score_b=next_score_b,current_discipline=next_current_discipline,winner_side=next_winner_side,winner_player_id=next_winner_player_id,status='in_progress' where player_matches.id=target_player_match_id;
return query select target_player_match_id,next_rack_number,rack_discipline,rack_winner_side,next_score_a,next_score_b,next_current_discipline,next_winner_side,next_winner_player_id,'in_progress'::text;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.record_player_match_score_rack(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, rack_winner_side text)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, discipline text, winner_side text, score_a integer, score_b integer, record_complete boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target_match __LANE__.player_matches%rowtype; tracker_id uuid; existing_submission __LANE___private.player_match_score_submissions%rowtype; next_rack_number integer; rack_discipline text; next_racks jsonb; next_score_a integer; next_score_b integer; begin if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if; if rack_winner_side not in ('A','B') then raise exception 'rack_winner_side must be A or B'; end if; select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update; if not found then raise exception 'Player match not found'; end if; if target_match.status in ('finalized','corrected') then raise exception 'Player match is finalized'; end if; if target_match.race_to_a is null or target_match.race_to_b is null then raise exception 'Race targets are required before recording racks'; end if; tracker_id:=__LANE___private.match_tracker_for_scoring_team(actor_user_id,target_match,target_scoring_team_id); select * into existing_submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=tracker_id for update; if not found then existing_submission.racks:='[]'::jsonb; end if; select count(*) filter(where elem->>'winnerSide'='A')::integer,count(*) filter(where elem->>'winnerSide'='B')::integer into next_score_a,next_score_b from jsonb_array_elements(existing_submission.racks) elem; if next_score_a>=target_match.race_to_a or next_score_b>=target_match.race_to_b then raise exception 'Score record is already complete'; end if; next_rack_number:=jsonb_array_length(existing_submission.racks)+1; rack_discipline:=case when next_rack_number<=target_match.opening_block_length then target_match.opening_discipline when target_match.opening_discipline='8-ball' then '9-ball' else '8-ball' end; next_racks:=existing_submission.racks||jsonb_build_array(jsonb_build_object('rackNumber',next_rack_number,'discipline',rack_discipline,'winnerSide',rack_winner_side)); select count(*) filter(where elem->>'winnerSide'='A')::integer,count(*) filter(where elem->>'winnerSide'='B')::integer into next_score_a,next_score_b from jsonb_array_elements(next_racks) elem; insert into __LANE___private.player_match_score_submissions(season_id,player_match_id,tracker_player_id,racks,confirmed_at,updated_at) values(target_match.season_id,target_player_match_id,tracker_id,next_racks,null,now()) on conflict on constraint player_match_score_submission_player_match_id_tracker_playe_key do update set racks=excluded.racks,confirmed_at=null,updated_at=now(); insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.team_score_rack_record','player_match',target_player_match_id,jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id,'racks',coalesce(existing_submission.racks,'[]'::jsonb)),jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id,'racks',next_racks)); return query select target_player_match_id,target_scoring_team_id,tracker_id,next_rack_number,rack_discipline,rack_winner_side,next_score_a,next_score_b,(next_score_a>=target_match.race_to_a or next_score_b>=target_match.race_to_b); end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.record_player_match_score_rack_checked(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, rack_winner_side text, expected_racks jsonb)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, discipline text, winner_side text, score_a integer, score_b integer, record_complete boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
begin
  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );
  perform __LANE___private.assert_expected_score_history(
    target_player_match_id,
    tracker_id,
    expected_racks
  );

  return query
  select * from __LANE__.record_player_match_score_rack(
    actor_user_id,
    target_player_match_id,
    target_scoring_team_id,
    rack_winner_side
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.register_for_season(actor_user_id uuid, target_season_id uuid, registration_participation_type text DEFAULT 'free_agent'::text)
 RETURNS TABLE(season_id uuid, player_id uuid, participation_type text, registration_status text, registered_at timestamp with time zone, payment_status text, amount_due_cents integer, amount_paid_cents integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_player __LANE__.players%rowtype;
  target_season __LANE__.seasons%rowtype;
  registration __LANE__.season_players%rowtype;
  fee_cents integer;
  has_active_team boolean;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if registration_participation_type not in ('rostered', 'free_agent') then
    raise exception 'participation_type must be rostered or free_agent';
  end if;

  select * into target_player
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before season registration'; end if;

  select * into target_season
  from __LANE__.seasons s
  where s.id = target_season_id;
  if not found then raise exception 'Season not found'; end if;
  if target_season.status <> 'registration' then raise exception 'Season registration is not open'; end if;

  select exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.player_id = target_player.id
      and tm.ends_at is null
  ) into has_active_team;

  if registration_participation_type = 'rostered' and not has_active_team then
    raise exception 'Active team membership is required for rostered registration';
  end if;
  if registration_participation_type = 'free_agent' and has_active_team then
    raise exception 'Rostered players cannot register as free agents for the same season';
  end if;

  insert into __LANE__.season_players(season_id, player_id, participation_type, status)
  values (target_season_id, target_player.id, registration_participation_type, 'active')
  on conflict on constraint season_players_season_id_player_id_key do update
    set participation_type = excluded.participation_type,
        status = 'active'
  returning * into registration;

  select coalesce(spc.entry_fee_cents, 0)
  into fee_cents
  from __LANE__.season_prize_configurations spc
  where spc.season_id = target_season_id
  order by spc.version desc
  limit 1;
  fee_cents := coalesce(fee_cents, 0);

  insert into __LANE___private.payment_status(season_id, player_id, status, amount_due_cents, amount_paid_cents)
  values (target_season_id, target_player.id, 'unpaid', fee_cents, 0)
  on conflict on constraint payment_status_pkey do nothing;

  return query
  select
    registration.season_id,
    registration.player_id,
    registration.participation_type,
    registration.status,
    registration.created_at,
    ps.status,
    ps.amount_due_cents,
    ps.amount_paid_cents
  from __LANE___private.payment_status ps
  where ps.season_id = target_season_id
    and ps.player_id = target_player.id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.register_free_agent(actor_user_id uuid, target_season_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, player_id uuid, participation_type text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_player_id uuid;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_season_id is null then raise exception 'target_season_id is required'; end if;
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id;
if not found then raise exception 'Player profile is required before joining as a free agent'; end if;
if exists(select 1 from __LANE__.team_memberships tm where tm.season_id=target_season_id and tm.player_id=actor_player_id and tm.ends_at is null) then raise exception 'Rostered players cannot register as free agents for the same season'; end if;
return query insert into __LANE__.season_players(season_id,player_id,participation_type,status) values(target_season_id,actor_player_id,'free_agent','active') on conflict(season_id,player_id) do update set participation_type='free_agent',status='active' returning season_players.id,season_players.season_id,season_players.player_id,season_players.participation_type,season_players.status;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.remove_team_member(actor_user_id uuid, target_membership_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, player_id uuid, role text, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  membership __LANE__.team_memberships%rowtype;
  actor_player_id uuid;
  ended_at timestamptz;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_membership_id is null then raise exception 'target_membership_id is required'; end if;

  select * into membership
  from __LANE__.team_memberships tm
  where tm.id = target_membership_id
  for update;
  if not found then raise exception 'Team membership not found'; end if;
  if membership.ends_at is not null then raise exception 'Team membership is already inactive'; end if;
  if membership.role <> 'player' then raise exception 'Captain memberships cannot be removed through this path'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before removing team members'; end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.team_id = membership.team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can remove team members';
  end if;

  ended_at := now();
  update __LANE__.team_memberships
  set ends_at = ended_at
  where team_memberships.id = target_membership_id;

  if not exists (
    select 1
    from __LANE__.team_memberships active_tm
    where active_tm.season_id = membership.season_id
      and active_tm.player_id = membership.player_id
      and active_tm.ends_at is null
  ) then
    update __LANE__.season_players sp
    set participation_type = 'free_agent',
        status = 'active'
    where sp.season_id = membership.season_id
      and sp.player_id = membership.player_id;
  end if;

  insert into __LANE___private.audit_events(
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'team.remove_member',
    'team_membership',
    membership.id,
    to_jsonb(membership),
    jsonb_build_object(
      'id', membership.id,
      'season_id', membership.season_id,
      'team_id', membership.team_id,
      'player_id', membership.player_id,
      'role', membership.role,
      'ends_at', ended_at
    )
  );

  return query
  select tm.id, tm.season_id, tm.team_id, tm.player_id, tm.role, tm.ends_at
  from __LANE__.team_memberships tm
  where tm.id = target_membership_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.report_chat_message(actor_user_id uuid, target_type text, target_message_id uuid, report_reason text, report_details text DEFAULT NULL::text)
 RETURNS TABLE(report_id uuid, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid; target_author_id uuid;
  target_team_message_id uuid; target_direct_message_id uuid;
  target_league_message_id uuid; target_matchup_message_id uuid;
  saved_report __LANE__.chat_message_reports%rowtype;
begin
  target_type := lower(btrim(target_type)); report_reason := lower(btrim(report_reason));
  report_details := nullif(btrim(report_details), '');
  if target_type not in ('team', 'direct', 'league', 'matchup') then raise exception 'Unsupported chat message type'; end if;
  if report_reason not in ('harassment', 'spam', 'privacy', 'threat', 'other') then raise exception 'Choose a valid report reason'; end if;
  if report_details is not null and char_length(report_details) > 1000 then raise exception 'Report details cannot exceed 1000 characters'; end if;
  select player.id into actor_player_id from __LANE__.players player where player.user_id = actor_user_id;
  if actor_player_id is null then raise exception 'Player profile is required before reporting chat'; end if;

  if target_type = 'team' then
    select message.id, message.author_player_id into target_team_message_id, target_author_id
    from __LANE__.team_chat_messages message where message.id = target_message_id and exists (
      select 1 from __LANE__.team_memberships membership
      where membership.player_id = actor_player_id and membership.season_id = message.season_id
        and membership.team_id = message.team_id and membership.starts_at <= message.created_at
        and (membership.ends_at is null or message.created_at < membership.ends_at));
  elsif target_type = 'direct' then
    select message.id, message.author_player_id into target_direct_message_id, target_author_id
    from __LANE__.direct_messages message join __LANE__.direct_conversations conversation on conversation.id = message.conversation_id
    where message.id = target_message_id and actor_player_id in (conversation.player_low_id, conversation.player_high_id);
  elsif target_type = 'league' then
    select message.id, message.author_player_id into target_league_message_id, target_author_id
    from __LANE__.league_chat_messages message where message.id = target_message_id
      and __LANE___private.is_season_chat_participant(actor_player_id, message.season_id);
  else
    select message.id, message.author_player_id into target_matchup_message_id, target_author_id
    from __LANE__.matchup_chat_messages message join __LANE__.team_matches match on match.id = message.team_match_id
    where message.id = target_message_id and exists (
      select 1 from __LANE__.team_memberships membership
      where membership.player_id = actor_player_id and membership.season_id = match.season_id
        and membership.team_id in (match.team_a_id, match.team_b_id)
        and membership.starts_at <= message.created_at
        and (membership.ends_at is null or message.created_at < membership.ends_at));
  end if;
  if target_author_id is null then raise exception 'Chat message not found'; end if;
  if target_author_id = actor_player_id then raise exception 'Cannot report your own message'; end if;

  select report.* into saved_report from __LANE__.chat_message_reports report
  where report.reporter_player_id = actor_player_id and (
    report.team_message_id = target_team_message_id
    or report.direct_message_id = target_direct_message_id
    or report.league_message_id = target_league_message_id
    or report.matchup_message_id = target_matchup_message_id) limit 1;
  if saved_report.id is null then
    insert into __LANE__.chat_message_reports (
      reporter_player_id, target_type, team_message_id, direct_message_id,
      league_message_id, matchup_message_id, reason, details
    ) values (
      actor_player_id, target_type, target_team_message_id, target_direct_message_id,
      target_league_message_id, target_matchup_message_id, report_reason, report_details
    ) returning * into saved_report;
  end if;
  return query select saved_report.id, saved_report.status, saved_report.created_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.request_captaincy_transfer(actor_user_id uuid, target_team_id uuid, target_player_id uuid, requested_departure_mode text DEFAULT 'remain'::text)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, from_player_id uuid, to_player_id uuid, departure_mode text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_player_id uuid; target_season_id uuid; transfer_id uuid;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_team_id is null then raise exception 'target_team_id is required'; end if;
if target_player_id is null then raise exception 'target_player_id is required'; end if;
if requested_departure_mode not in ('remain','leave') then raise exception 'departure_mode must be remain or leave'; end if;
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id;
if not found then raise exception 'Player profile is required'; end if;
select t.season_id into target_season_id from __LANE__.teams t where t.id=target_team_id;
if not found then raise exception 'Team not found'; end if;
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=target_team_id and tm.season_id=target_season_id and tm.player_id=actor_player_id and tm.role='captain' and tm.ends_at is null) then raise exception 'Only the active captain can transfer captaincy'; end if;
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=target_team_id and tm.season_id=target_season_id and tm.player_id=target_player_id and tm.role='player' and tm.ends_at is null) then raise exception 'New captain must be an active rostered player on this team'; end if;
insert into __LANE___private.captaincy_transfers(season_id,team_id,from_player_id,to_player_id,departure_mode) values(target_season_id,target_team_id,actor_player_id,target_player_id,requested_departure_mode) returning __LANE___private.captaincy_transfers.id into transfer_id;
return query select ct.id,ct.season_id,ct.team_id,ct.from_player_id,ct.to_player_id,ct.departure_mode,ct.status from __LANE___private.captaincy_transfers ct where ct.id=transfer_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.request_team_membership(actor_user_id uuid, target_team_id uuid)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, player_id uuid, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_season_id uuid;
  request_id uuid;
  pending_invitation_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before requesting a team'; end if;

  select t.season_id into target_season_id
  from __LANE__.teams t
  where t.id = target_team_id;
  if not found then raise exception 'Team not found'; end if;

  perform __LANE___private.expire_season_team_registration(target_season_id);
  if not exists (
    select 1
    from __LANE___private.season_team_slots sts
    where sts.season_id = target_season_id
      and sts.team_id = target_team_id
      and sts.status in ('approved_pending_roster', 'ready', 'confirmed')
  ) then
    raise exception 'This team is not accepting season roster requests';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.ends_at is null
  ) then
    raise exception 'Player is already an active member of this team';
  end if;

  if exists (
    select 1 from __LANE___private.team_membership_requests r
    where r.season_id = target_season_id
      and r.team_id = target_team_id
      and r.player_id = actor_player_id
      and r.status = 'pending'
  ) then
    raise exception 'Membership request is already pending';
  end if;

  select ti.id into pending_invitation_id
  from __LANE___private.team_invitations ti
  where ti.season_id = target_season_id
    and ti.team_id = target_team_id
    and ti.invited_player_id = actor_player_id
    and ti.status = 'pending'
  order by ti.created_at
  limit 1
  for update;

  if pending_invitation_id is not null then
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(target_season_id, target_team_id, actor_player_id, 'player');

    insert into __LANE___private.team_membership_requests(
      season_id, team_id, player_id, status, resolved_at, resolved_by_user_id
    ) values (
      target_season_id, target_team_id, actor_player_id, 'approved', now(), actor_user_id
    ) returning __LANE___private.team_membership_requests.id into request_id;

    update __LANE___private.team_invitations
    set status = 'accepted', responded_at = now()
    where __LANE___private.team_invitations.id = pending_invitation_id;
  else
    insert into __LANE___private.team_membership_requests(season_id, team_id, player_id)
    values(target_season_id, target_team_id, actor_player_id)
    returning __LANE___private.team_membership_requests.id into request_id;
  end if;

  return query
  select r.id, r.season_id, r.team_id, r.player_id, r.status, r.created_at
  from __LANE___private.team_membership_requests r
  where r.id = request_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.resolve_sandbox_feedback(actor_user_id uuid, target_feedback_id uuid)
 RETURNS TABLE(id uuid, status text, reviewed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'League admin access is required';
  end if;

  update __LANE___private.sandbox_feedback sf
  set status = 'reviewed',
      reviewed_at = now(),
      reviewed_by_user_id = actor_user_id
  where sf.id = target_feedback_id
    and sf.status = 'open';

  if not found then
    raise exception 'Open sandbox feedback not found';
  end if;

  return query
  select sf.id, sf.status, sf.reviewed_at
  from __LANE___private.sandbox_feedback sf
  where sf.id = target_feedback_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.respond_to_captaincy_transfer(actor_user_id uuid, target_transfer_id uuid, response_status text)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, from_player_id uuid, to_player_id uuid, departure_mode text, status text, resolved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor_player_id uuid; transfer_row __LANE___private.captaincy_transfers%rowtype;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_transfer_id is null then raise exception 'target_transfer_id is required'; end if;
if response_status not in ('accepted','declined') then raise exception 'response_status must be accepted or declined'; end if;
select p.id into actor_player_id from __LANE__.players p where p.user_id=actor_user_id;
if not found then raise exception 'Player profile is required'; end if;
select * into transfer_row from __LANE___private.captaincy_transfers ct where ct.id=target_transfer_id for update;
if not found then raise exception 'Captaincy transfer not found'; end if;
if transfer_row.status<>'pending' then raise exception 'Captaincy transfer is no longer pending'; end if;
if transfer_row.to_player_id<>actor_player_id then raise exception 'Only the proposed captain can respond to this transfer'; end if;
if response_status='accepted' then
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=transfer_row.team_id and tm.season_id=transfer_row.season_id and tm.player_id=transfer_row.from_player_id and tm.role='captain' and tm.ends_at is null) then raise exception 'Current captain is no longer eligible to transfer this team'; end if;
if not exists(select 1 from __LANE__.team_memberships tm where tm.team_id=transfer_row.team_id and tm.season_id=transfer_row.season_id and tm.player_id=transfer_row.to_player_id and tm.role='player' and tm.ends_at is null) then raise exception 'Proposed captain is no longer an active rostered player'; end if;
update __LANE__.team_memberships set role='captain' where season_id=transfer_row.season_id and team_id=transfer_row.team_id and player_id=transfer_row.to_player_id and ends_at is null;
if transfer_row.departure_mode='leave' then
update __LANE__.team_memberships set ends_at=now() where season_id=transfer_row.season_id and team_id=transfer_row.team_id and player_id=transfer_row.from_player_id and role='captain' and ends_at is null;
else
update __LANE__.team_memberships set role='player' where season_id=transfer_row.season_id and team_id=transfer_row.team_id and player_id=transfer_row.from_player_id and role='captain' and ends_at is null;
end if;
end if;
update __LANE___private.captaincy_transfers set status=response_status,resolved_at=now() where __LANE___private.captaincy_transfers.id=target_transfer_id;
return query select ct.id,ct.season_id,ct.team_id,ct.from_player_id,ct.to_player_id,ct.departure_mode,ct.status,ct.resolved_at from __LANE___private.captaincy_transfers ct where ct.id=target_transfer_id;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.respond_to_returning_team_slot(actor_user_id uuid, target_slot_id uuid, response_action text, transfer_player_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(slot_id uuid, slot_status text, team_id uuid, assigned_captain_player_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  slot_row __LANE___private.season_team_slots%rowtype;
  target_captain_player_id uuid;
  target_captain_user_id uuid;
  source_team_name text;
  inserted_team_id uuid;
begin
  if response_action not in ('confirm', 'release', 'transfer') then
    raise exception 'response_action must be confirm, release, or transfer';
  end if;
  select p.id into actor_player_id from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required'; end if;

  select * into slot_row
  from __LANE___private.season_team_slots sts where sts.id = target_slot_id
  for update;
  if not found then raise exception 'Returning team slot not found'; end if;

  perform __LANE___private.expire_season_team_registration(slot_row.season_id);
  select * into slot_row
  from __LANE___private.season_team_slots sts where sts.id = target_slot_id
  for update;

  if slot_row.status not in ('reserved', 'transferred') then
    raise exception 'Returning team slot is no longer awaiting a response';
  end if;
  if slot_row.assigned_captain_player_id <> actor_player_id then
    raise exception 'Only the assigned returning captain can respond';
  end if;

  if response_action = 'release' then
    update __LANE___private.season_team_slots
    set status = 'released', resolved_at = now(), updated_at = now()
    where id = target_slot_id;
  elsif response_action = 'transfer' then
    if transfer_player_id is null or transfer_player_id = actor_player_id then
      raise exception 'Choose another eligible player for the transfer';
    end if;
    if not exists (select 1 from __LANE__.players p where p.id = transfer_player_id and p.user_id is not null) then
      raise exception 'Transfer player must have a signed-in player profile';
    end if;
    if exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = slot_row.season_id
        and tm.player_id = transfer_player_id
        and tm.role = 'captain'
        and tm.ends_at is null
    ) then
      raise exception 'Transfer player already captains a team in this season';
    end if;
    update __LANE___private.season_team_slots
    set status = 'transferred',
        assigned_captain_player_id = transfer_player_id,
        updated_at = now()
    where id = target_slot_id;
  else
    target_captain_player_id := slot_row.assigned_captain_player_id;
    select p.user_id into target_captain_user_id
    from __LANE__.players p where p.id = target_captain_player_id;
    select t.name into source_team_name
    from __LANE__.teams t where t.id = slot_row.source_team_id;
    if target_captain_user_id is null then
      raise exception 'Assigned captain must have a signed-in player profile';
    end if;
    if exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = slot_row.season_id
        and tm.player_id = target_captain_player_id
        and tm.role = 'captain'
        and tm.ends_at is null
    ) then
      raise exception 'Assigned captain already captains a team in this season';
    end if;

    insert into __LANE__.teams(season_id, name, created_by)
    values(slot_row.season_id, source_team_name, target_captain_user_id)
    returning __LANE__.teams.id into inserted_team_id;
    insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
    values(slot_row.season_id, inserted_team_id, target_captain_player_id, 'captain');
    update __LANE___private.season_team_slots
    set status = 'confirmed',
        team_id = inserted_team_id,
        resolved_at = now(),
        updated_at = now()
    where id = target_slot_id;
  end if;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'returning_team_slot.' || response_action,
    'season_team_slot',
    target_slot_id,
    jsonb_build_object('transferPlayerId', transfer_player_id)
  );

  return query
  select sts.id, sts.status, sts.team_id, sts.assigned_captain_player_id
  from __LANE___private.season_team_slots sts where sts.id = target_slot_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.respond_to_team_invitation(actor_user_id uuid, target_invitation_id uuid, response_status text)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, invited_player_id uuid, status text, responded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  invitation __LANE___private.team_invitations%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_invitation_id is null then raise exception 'target_invitation_id is required'; end if;
  if response_status not in ('accepted', 'declined') then
    raise exception 'response_status must be accepted or declined';
  end if;

  select * into invitation
  from __LANE___private.team_invitations ti
  where ti.id = target_invitation_id
  for update;
  if not found then raise exception 'Invitation not found'; end if;
  if invitation.status <> 'pending' then raise exception 'Invitation is no longer pending'; end if;

  if not exists (
    select 1 from __LANE__.players p
    where p.id = invitation.invited_player_id
      and p.user_id = actor_user_id
  ) then
    raise exception 'Only the invited player can respond';
  end if;

  if response_status = 'accepted' then
    if not exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = invitation.season_id
        and tm.team_id = invitation.team_id
        and tm.player_id = invitation.invited_player_id
        and tm.ends_at is null
    ) then
      insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
      values(invitation.season_id, invitation.team_id, invitation.invited_player_id, 'player');
    end if;

    update __LANE___private.team_membership_requests
    set status = 'approved', resolved_at = now(), resolved_by_user_id = actor_user_id
    where __LANE___private.team_membership_requests.season_id = invitation.season_id
      and __LANE___private.team_membership_requests.team_id = invitation.team_id
      and __LANE___private.team_membership_requests.player_id = invitation.invited_player_id
      and __LANE___private.team_membership_requests.status = 'pending';
  end if;

  update __LANE___private.team_invitations
  set status = response_status,
      responded_at = now()
  where __LANE___private.team_invitations.id = target_invitation_id;

  return query
  select ti.id, ti.season_id, ti.team_id, ti.invited_player_id, ti.status, ti.responded_at
  from __LANE___private.team_invitations ti
  where ti.id = target_invitation_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.respond_to_team_membership_request(actor_user_id uuid, target_request_id uuid, response_status text)
 RETURNS TABLE(id uuid, season_id uuid, team_id uuid, player_id uuid, status text, resolved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request_row __LANE___private.team_membership_requests%rowtype;
  actor_player_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_request_id is null then raise exception 'target_request_id is required'; end if;
  if response_status not in ('approved', 'declined') then
    raise exception 'response_status must be approved or declined';
  end if;

  select * into request_row
  from __LANE___private.team_membership_requests r
  where r.id = target_request_id
  for update;
  if not found then raise exception 'Membership request not found'; end if;
  if request_row.status <> 'pending' then raise exception 'Membership request is no longer pending'; end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required'; end if;

  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = request_row.team_id
      and tm.season_id = request_row.season_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can respond to membership requests';
  end if;

  if response_status = 'approved' then
    if not exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = request_row.season_id
        and tm.team_id = request_row.team_id
        and tm.player_id = request_row.player_id
        and tm.ends_at is null
    ) then
      insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
      values(request_row.season_id, request_row.team_id, request_row.player_id, 'player');
    end if;

    update __LANE___private.team_invitations
    set status = 'accepted', responded_at = now()
    where __LANE___private.team_invitations.season_id = request_row.season_id
      and __LANE___private.team_invitations.team_id = request_row.team_id
      and __LANE___private.team_invitations.invited_player_id = request_row.player_id
      and __LANE___private.team_invitations.status = 'pending';
  end if;

  update __LANE___private.team_membership_requests
  set status = response_status,
      resolved_at = now(),
      resolved_by_user_id = actor_user_id
  where __LANE___private.team_membership_requests.id = target_request_id;

  return query
  select r.id, r.season_id, r.team_id, r.player_id, r.status, r.resolved_at
  from __LANE___private.team_membership_requests r
  where r.id = target_request_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.respond_to_team_trade_player(actor_user_id uuid, target_trade_id uuid, response_status text)
 RETURNS TABLE(id uuid, season_id uuid, status text, requesting_player_accepted_at timestamp with time zone, requested_player_accepted_at timestamp with time zone, declined_at timestamp with time zone, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  trade __LANE___private.team_trades%rowtype;
  actor_player_id uuid;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if target_trade_id is null then
    raise exception 'target_trade_id is required';
  end if;

  if response_status not in ('accepted', 'declined') then
    raise exception 'response_status must be accepted or declined';
  end if;

  select *
    into trade
  from __LANE___private.team_trades tt
  where tt.id = target_trade_id
  for update;

  if not found then
    raise exception 'Trade not found';
  end if;

  if trade.status <> 'pending' then
    raise exception 'Trade is no longer pending';
  end if;

  select p.id
    into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;

  if actor_player_id is null
      or actor_player_id not in (trade.offered_player_id, trade.requested_player_id) then
    raise exception 'Only a traded player can respond';
  end if;

  if response_status = 'declined' then
    update __LANE___private.team_trades
    set status = 'declined',
        declined_by_user_id = actor_user_id,
        declined_at = now()
    where team_trades.id = target_trade_id;
  elsif actor_player_id = trade.offered_player_id then
    update __LANE___private.team_trades
    set requesting_player_accepted_at = coalesce(requesting_player_accepted_at, now())
    where team_trades.id = target_trade_id;
  else
    update __LANE___private.team_trades
    set requested_player_accepted_at = coalesce(requested_player_accepted_at, now())
    where team_trades.id = target_trade_id;
  end if;

  if response_status = 'accepted' then
    perform __LANE___private.complete_team_trade_if_ready(target_trade_id);
  end if;

  return query
  select
    tt.id,
    tt.season_id,
    tt.status,
    tt.requesting_player_accepted_at,
    tt.requested_player_accepted_at,
    tt.declined_at,
    tt.completed_at
  from __LANE___private.team_trades tt
  where tt.id = target_trade_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.seed_returning_team_slots(actor_user_id uuid, target_season_id uuid, source_season_id uuid)
 RETURNS TABLE(created_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_capacity integer;
  occupied_count integer;
  remaining_count integer;
  expiry_at timestamptz;
  inserted_count integer;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;
  if target_season_id = source_season_id then
    raise exception 'Source and target seasons must differ';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'season_team_capacity:' || target_season_id::text, 0
  ));
  perform __LANE___private.expire_season_team_registration(target_season_id);

  select s.team_capacity,
         coalesce(s.returning_reservation_deadline, now() + interval '14 days')
  into target_capacity, expiry_at
  from __LANE__.seasons s
  where s.id = target_season_id and s.status = 'registration'
  for update;
  if not found then raise exception 'Target season is not open for registration'; end if;

  select count(*)::integer into occupied_count
  from __LANE___private.season_team_slots sts
  where sts.season_id = target_season_id
    and sts.status in ('reserved', 'transferred', 'approved_pending_roster', 'ready', 'confirmed');
  remaining_count := greatest(0, target_capacity - occupied_count);

  with returning_teams as (
    select t.id as source_team_id, tm.player_id as captain_player_id
    from __LANE__.teams t
    join __LANE__.team_memberships tm
      on tm.team_id = t.id
     and tm.season_id = t.season_id
     and tm.role = 'captain'
     and tm.ends_at is null
    where t.season_id = source_season_id
      and not exists (
        select 1 from __LANE___private.season_team_slots existing
        where existing.season_id = target_season_id
          and existing.source_team_id = t.id
      )
    order by t.created_at, t.id
    limit remaining_count
  ), inserted as (
    insert into __LANE___private.season_team_slots(
      season_id,
      source_team_id,
      returning_captain_player_id,
      assigned_captain_player_id,
      status,
      reservation_expires_at
    )
    select target_season_id, source_team_id, captain_player_id, captain_player_id,
           'reserved', expiry_at
    from returning_teams
    returning 1
  )
  select count(*)::integer into inserted_count from inserted;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'season.seed_returning_team_slots',
    'season',
    target_season_id,
    jsonb_build_object('sourceSeasonId', source_season_id, 'createdCount', inserted_count)
  );

  created_count := inserted_count;
  return next;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.send_direct_message(actor_user_id uuid, target_conversation_id uuid, message_body text, message_client_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, conversation_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player __LANE__.players%rowtype;
  conversation __LANE__.direct_conversations%rowtype;
  other_player_id uuid;
  saved_message __LANE__.direct_messages%rowtype;
begin
  message_body := btrim(message_body);
  if message_body is null or char_length(message_body) < 1 then
    raise exception 'Message cannot be empty';
  end if;
  if char_length(message_body) > 2000 then
    raise exception 'Message cannot exceed 2000 characters';
  end if;

  select p.* into actor_player
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player.id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  select target.* into conversation
  from __LANE__.direct_conversations target
  where target.id = target_conversation_id
    and actor_player.id in (target.player_low_id, target.player_high_id);
  if conversation.id is null then
    raise exception 'Direct conversation not found';
  end if;

  other_player_id := case
    when conversation.player_low_id = actor_player.id
      then conversation.player_high_id
    else conversation.player_low_id
  end;

  if not __LANE___private.is_active_season_participant(actor_player.id, conversation.season_id)
    or not __LANE___private.is_active_season_participant(other_player_id, conversation.season_id)
  then
    raise exception 'Both players must participate in the active season';
  end if;

  if exists (
    select 1
    from __LANE__.player_chat_blocks block
    where (
      block.blocker_player_id = actor_player.id
      and block.blocked_player_id = other_player_id
    ) or (
      block.blocker_player_id = other_player_id
      and block.blocked_player_id = actor_player.id
    )
  ) then
    raise exception 'Direct messages are blocked';
  end if;

  insert into __LANE__.direct_messages (
    conversation_id, author_player_id, client_message_id, body
  ) values (
    conversation.id, actor_player.id, message_client_id, message_body
  )
  on conflict on constraint direct_messages_author_player_id_client_message_id_key
  do update set client_message_id = excluded.client_message_id
  returning * into saved_message;

  return query select saved_message.id, saved_message.conversation_id,
    saved_message.author_player_id, actor_player.display_name,
    saved_message.body, saved_message.created_at, true;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.send_league_chat_message(actor_user_id uuid, target_season_id uuid, message_body text, message_client_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, season_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player __LANE__.players%rowtype;
  saved_message __LANE__.league_chat_messages%rowtype;
begin
  message_body := btrim(message_body);
  if message_body is null or char_length(message_body) < 1 then
    raise exception 'Message cannot be empty';
  end if;
  if char_length(message_body) > 2000 then
    raise exception 'Message cannot exceed 2000 characters';
  end if;
  select player.* into actor_player
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player.id is null then
    raise exception 'Player profile is required before using chat';
  end if;
  if not __LANE___private.is_active_season_participant(actor_player.id, target_season_id) then
    raise exception 'Active season participation is required to post league messages';
  end if;

  insert into __LANE__.league_chat_messages (
    season_id, author_player_id, client_message_id, body
  ) values (
    target_season_id, actor_player.id, message_client_id, message_body
  )
  on conflict on constraint league_chat_messages_author_client_key
  do update set client_message_id = excluded.client_message_id
  returning * into saved_message;

  return query select saved_message.id, saved_message.season_id,
    saved_message.author_player_id, actor_player.display_name,
    saved_message.body, saved_message.created_at, true;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.send_matchup_chat_message(actor_user_id uuid, target_team_match_id uuid, message_body text, message_client_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, team_match_id uuid, author_player_id uuid, author_display_name text, author_team_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player __LANE__.players%rowtype;
  target_match __LANE__.team_matches%rowtype;
  actor_team_id uuid;
  actor_team_name text;
  saved_message __LANE__.matchup_chat_messages%rowtype;
begin
  message_body := btrim(message_body);
  if message_body is null or char_length(message_body) < 1 then
    raise exception 'Message cannot be empty';
  end if;
  if char_length(message_body) > 2000 then
    raise exception 'Message cannot exceed 2000 characters';
  end if;
  select player.* into actor_player
  from __LANE__.players player
  where player.user_id = actor_user_id;
  if actor_player.id is null then
    raise exception 'Player profile is required before using chat';
  end if;
  select match.* into target_match
  from __LANE__.team_matches match
  where match.id = target_team_match_id;
  if target_match.id is null then raise exception 'Team matchup not found'; end if;
  if target_match.status in ('finalized', 'corrected', 'cancelled') then
    raise exception 'Completed matchup chats are read-only';
  end if;
  if not __LANE___private.is_active_season_participant(actor_player.id, target_match.season_id) then
    raise exception 'Active season participation is required to post matchup messages';
  end if;

  select membership.team_id, team.name into actor_team_id, actor_team_name
  from __LANE__.team_memberships membership
  join __LANE__.teams team on team.id = membership.team_id
  where membership.player_id = actor_player.id
    and membership.season_id = target_match.season_id
    and membership.team_id in (target_match.team_a_id, target_match.team_b_id)
    and membership.ends_at is null
  order by membership.starts_at desc
  limit 1;
  if actor_team_id is null then
    raise exception 'Current matchup team membership is required';
  end if;

  insert into __LANE__.matchup_chat_messages (
    team_match_id, author_player_id, author_team_id, client_message_id, body
  ) values (
    target_match.id, actor_player.id, actor_team_id, message_client_id, message_body
  )
  on conflict on constraint matchup_chat_messages_author_player_id_client_message_id_key
  do update set client_message_id = excluded.client_message_id
  returning * into saved_message;

  return query select saved_message.id, saved_message.team_match_id,
    saved_message.author_player_id, actor_player.display_name, actor_team_name,
    saved_message.body, saved_message.created_at, true;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.send_team_chat_message(actor_user_id uuid, target_team_id uuid, message_body text, message_client_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, team_id uuid, author_player_id uuid, author_display_name text, body text, created_at timestamp with time zone, is_own boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player __LANE__.players%rowtype;
  target_team __LANE__.teams%rowtype;
  saved_message __LANE__.team_chat_messages%rowtype;
begin
  message_body := btrim(message_body);
  if message_body is null or char_length(message_body) < 1 then
    raise exception 'Message cannot be empty';
  end if;
  if char_length(message_body) > 2000 then
    raise exception 'Message cannot exceed 2000 characters';
  end if;

  select p.* into actor_player
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player.id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  select t.* into target_team
  from __LANE__.teams t
  where t.id = target_team_id;
  if target_team.id is null then
    raise exception 'Team not found';
  end if;

  if not exists (
    select 1
    from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player.id
      and tm.ends_at is null
  ) then
    raise exception 'Active team membership is required to post messages';
  end if;

  insert into __LANE__.team_chat_messages (
    season_id, team_id, author_player_id, client_message_id, body
  ) values (
    target_team.season_id, target_team.id, actor_player.id,
    message_client_id, message_body
  )
  on conflict on constraint team_chat_messages_author_player_id_client_message_id_key
  do update set client_message_id = excluded.client_message_id
  returning * into saved_message;

  return query select saved_message.id, saved_message.team_id,
    saved_message.author_player_id, actor_player.display_name,
    saved_message.body, saved_message.created_at, true;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_admin_player_team_membership(actor_user_id uuid, target_season_id uuid, target_team_id uuid, target_player_id uuid, active boolean, change_reason text DEFAULT NULL::text)
 RETURNS TABLE(membership_id uuid, season_id uuid, team_id uuid, player_id uuid, role text, ends_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_team __LANE__.teams%rowtype;
  membership __LANE__.team_memberships%rowtype;
  normalized_reason text;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;
  if active is null then raise exception 'active is required'; end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then raise exception 'Actor is not a league admin'; end if;

  select * into target_team
  from __LANE__.teams t
  where t.id = target_team_id
    and t.season_id = target_season_id;
  if not found then raise exception 'Team not found in season'; end if;

  if not exists (select 1 from __LANE__.players p where p.id = target_player_id) then
    raise exception 'Player not found';
  end if;

  normalized_reason := nullif(btrim(change_reason), '');
  if normalized_reason is not null and char_length(normalized_reason) > 500 then
    raise exception 'reason must be 500 characters or fewer';
  end if;

  select * into membership
  from __LANE__.team_memberships tm
  where tm.season_id = target_season_id
    and tm.team_id = target_team_id
    and tm.player_id = target_player_id
    and tm.ends_at is null
  for update;

  if active then
    if not found then
      insert into __LANE__.team_memberships(season_id, team_id, player_id, role)
      values (target_season_id, target_team_id, target_player_id, 'player')
      returning * into membership;

      insert into __LANE___private.audit_events(
        actor_user_id, action, entity_type, entity_id, reason, before_state, after_state
      ) values (
        actor_user_id,
        'player.admin_add_team_membership',
        'team_membership',
        membership.id,
        normalized_reason,
        jsonb_build_object(
          'seasonId', target_season_id,
          'teamId', target_team_id,
          'playerId', target_player_id,
          'active', false
        ),
        jsonb_build_object(
          'seasonId', target_season_id,
          'teamId', target_team_id,
          'playerId', target_player_id,
          'role', membership.role,
          'active', true
        )
      );
    end if;
  else
    if not found then
      raise exception 'Active team membership not found';
    end if;
    if membership.role = 'captain' then
      raise exception 'Captain memberships require the captain lifecycle workflow';
    end if;

    update __LANE__.team_memberships tm
    set ends_at = now()
    where tm.id = membership.id
    returning * into membership;

    insert into __LANE___private.audit_events(
      actor_user_id, action, entity_type, entity_id, reason, before_state, after_state
    ) values (
      actor_user_id,
      'player.admin_remove_team_membership',
      'team_membership',
      membership.id,
      normalized_reason,
      jsonb_build_object(
        'seasonId', target_season_id,
        'teamId', target_team_id,
        'playerId', target_player_id,
        'role', membership.role,
        'active', true
      ),
      jsonb_build_object(
        'seasonId', target_season_id,
        'teamId', target_team_id,
        'playerId', target_player_id,
        'role', membership.role,
        'active', false,
        'endsAt', membership.ends_at
      )
    );
  end if;

  return query
  select membership.id, membership.season_id, membership.team_id,
         membership.player_id, membership.role, membership.ends_at;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_free_agent_availability(actor_user_id uuid, target_round_id uuid, availability_status text)
 RETURNS TABLE(season_id uuid, round_id uuid, player_id uuid, status text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_round __LANE__.rounds%rowtype;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;
  if availability_status not in ('available', 'unavailable', 'unsure') then
    raise exception 'availability_status must be available, unavailable, or unsure';
  end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before setting availability'; end if;

  select * into target_round
  from __LANE__.rounds r
  where r.id = target_round_id;
  if not found then raise exception 'Round not found'; end if;
  if target_round.scheduled_on is null then raise exception 'Round does not have a scheduled date'; end if;

  if not exists (
    select 1
    from __LANE__.season_players sp
    where sp.season_id = target_round.season_id
      and sp.player_id = actor_player_id
      and sp.participation_type = 'free_agent'
      and sp.status = 'active'
  ) then
    raise exception 'Active free-agent registration is required before setting availability';
  end if;

  perform * from __LANE__.set_own_date_availability(
    actor_user_id,
    target_round.season_id,
    target_round.scheduled_on,
    availability_status
  );

  return query
  select
    target_round.season_id,
    target_round.id,
    actor_player_id,
    pda.status,
    pda.updated_at
  from __LANE___private.player_date_availability pda
  where pda.season_id = target_round.season_id
    and pda.player_id = actor_player_id
    and pda.availability_date = target_round.scheduled_on;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_league_admin_role(actor_user_id uuid, target_player_id uuid, enabled boolean, change_reason text DEFAULT NULL::text)
 RETURNS TABLE(player_id uuid, is_league_admin boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_user_id uuid;
  was_admin boolean;
  normalized_reason text;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;
  if target_player_id is null then
    raise exception 'target_player_id is required';
  end if;
  if enabled is null then
    raise exception 'enabled is required';
  end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  select p.user_id into target_user_id
  from __LANE__.players p
  where p.id = target_player_id
  for update;

  if not found then
    raise exception 'Player not found';
  end if;
  if target_user_id is null then
    raise exception 'Player must sign in before admin access can be granted';
  end if;

  normalized_reason := nullif(btrim(change_reason), '');
  if normalized_reason is not null and char_length(normalized_reason) > 500 then
    raise exception 'reason must be 500 characters or fewer';
  end if;

  select exists (
    select 1 from __LANE___private.league_admins la where la.user_id = target_user_id
  ) into was_admin;

  if enabled then
    insert into __LANE___private.league_admins (user_id, granted_by, note)
    values (target_user_id, actor_user_id, normalized_reason)
    on conflict (user_id) do update
      set granted_by = excluded.granted_by,
          note = excluded.note;
  else
    if was_admin and (
      select count(*) from __LANE___private.league_admins
    ) <= 1 then
      raise exception 'The last league admin cannot be removed';
    end if;
    delete from __LANE___private.league_admins where user_id = target_user_id;
  end if;

  if was_admin is distinct from enabled then
    insert into __LANE___private.audit_events (
      actor_user_id,
      action,
      entity_type,
      entity_id,
      reason,
      before_state,
      after_state
    ) values (
      actor_user_id,
      case when enabled then 'player.grant_admin' else 'player.revoke_admin' end,
      'player',
      target_player_id,
      normalized_reason,
      jsonb_build_object('isLeagueAdmin', was_admin),
      jsonb_build_object('isLeagueAdmin', enabled)
    );
  end if;

  return query select target_player_id, enabled;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_own_date_availability(actor_user_id uuid, target_season_id uuid, target_availability_date date, target_availability_status text)
 RETURNS TABLE(season_id uuid, player_id uuid, availability_date date, availability_status text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_player_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if target_availability_date is null then raise exception 'target_availability_date is required'; end if;
  if target_availability_status not in ('available', 'unsure', 'unavailable') then
    raise exception 'availability_status must be available, unsure, or unavailable';
  end if;

  select p.id into target_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if target_player_id is null then raise exception 'Player profile is required'; end if;

  if not exists (
    select 1
    from __LANE__.season_players sp
    where sp.season_id = target_season_id
      and sp.player_id = target_player_id
      and sp.status = 'active'
  ) then
    raise exception 'Active season registration is required to set availability';
  end if;

  if not exists (
    select 1
    from __LANE__.rounds r
    where r.season_id = target_season_id
      and r.scheduled_on = target_availability_date
  ) then
    raise exception 'Availability date is not a scheduled league date for this season';
  end if;

  insert into __LANE___private.player_date_availability(
    season_id,
    player_id,
    availability_date,
    status,
    updated_at
  ) values (
    target_season_id,
    target_player_id,
    target_availability_date,
    target_availability_status,
    now()
  )
  on conflict on constraint player_date_availability_pkey do update
  set status = excluded.status,
      updated_at = now();

  -- Compatibility cache for submit_team_lineup while it still accepts the old
  -- round-shaped availability tables. This does not become a second source of
  -- truth: every supported write reaches this function first.
  insert into __LANE___private.free_agent_availability(
    season_id,
    round_id,
    player_id,
    status,
    updated_at
  )
  select
    target_season_id,
    r.id,
    target_player_id,
    target_availability_status,
    now()
  from __LANE__.rounds r
  where r.season_id = target_season_id
    and r.scheduled_on = target_availability_date
  on conflict (round_id, player_id) do update
  set status = excluded.status,
      updated_at = now();

  -- Neutralize any older roster-scoped cache row for the same player/date so an
  -- obsolete 'available' value cannot override an Unavailable/Unsure date state.
  update __LANE___private.roster_availability ra
  set status = target_availability_status,
      updated_at = now()
  where ra.season_id = target_season_id
    and ra.player_id = target_player_id
    and exists (
      select 1
      from __LANE__.rounds r
      where r.id = ra.round_id
        and r.season_id = target_season_id
        and r.scheduled_on = target_availability_date
    );

  return query
  select pda.season_id, pda.player_id, pda.availability_date, pda.status, pda.updated_at
  from __LANE___private.player_date_availability pda
  where pda.season_id = target_season_id
    and pda.player_id = target_player_id
    and pda.availability_date = target_availability_date;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_own_player_phone(actor_user_id uuid, profile_phone text)
 RETURNS TABLE(phone text, has_phone boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_player_id uuid;
  normalized_phone text;
  digit_count integer;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;

  select p.id into target_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id
  for update;
  if not found then raise exception 'Player profile is required'; end if;

  normalized_phone := nullif(btrim(profile_phone), '');
  if normalized_phone is not null then
    digit_count := char_length(regexp_replace(normalized_phone, '[^0-9]', '', 'g'));
    if digit_count < 10 or digit_count > 15 then
      raise exception 'Phone number must contain between 10 and 15 digits';
    end if;
  end if;

  if normalized_phone is null and exists (
    select 1
    from __LANE__.team_memberships tm
    join __LANE__.seasons s on s.id = tm.season_id
    where tm.player_id = target_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
      and s.status in ('active', 'playoffs')
  ) then
    raise exception 'Active captains must keep a phone number on file';
  end if;

  insert into __LANE___private.player_contacts(player_id, phone, updated_at)
  values(target_player_id, normalized_phone, now())
  on conflict (player_id) do update
    set phone = excluded.phone,
        updated_at = now();

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, after_state)
  values (
    actor_user_id,
    'player.phone_contact_update',
    'player',
    target_player_id,
    jsonb_build_object('hasPhone', normalized_phone is not null)
  );

  return query select normalized_phone, normalized_phone is not null;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_player_competition_eligibility(actor_user_id uuid, target_season_id uuid, target_player_id uuid, eligible boolean, change_reason text DEFAULT NULL::text)
 RETURNS TABLE(player_id uuid, season_id uuid, competition_eligible boolean, ineligibility_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing_restriction __LANE___private.player_competition_restrictions%rowtype;
  normalized_reason text;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  if target_player_id is null then raise exception 'target_player_id is required'; end if;
  if eligible is null then raise exception 'eligible is required'; end if;

  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then raise exception 'Actor is not a league admin'; end if;

  if not exists (select 1 from __LANE__.seasons s where s.id = target_season_id) then
    raise exception 'Season not found';
  end if;
  if not exists (select 1 from __LANE__.players p where p.id = target_player_id) then
    raise exception 'Player not found';
  end if;

  normalized_reason := nullif(btrim(change_reason), '');
  if normalized_reason is not null and char_length(normalized_reason) > 500 then
    raise exception 'reason must be 500 characters or fewer';
  end if;
  if not eligible and normalized_reason is null then
    raise exception 'A reason is required to mark a player ineligible';
  end if;

  select * into existing_restriction
  from __LANE___private.player_competition_restrictions r
  where r.season_id = target_season_id
    and r.player_id = target_player_id
    and r.lifted_at is null
  for update;

  if eligible then
    if found then
      update __LANE___private.player_competition_restrictions r
      set lifted_by = actor_user_id,
          lifted_at = now(),
          lift_reason = normalized_reason
      where r.id = existing_restriction.id;

      insert into __LANE___private.audit_events(
        actor_user_id, action, entity_type, entity_id, reason, before_state, after_state
      ) values (
        actor_user_id,
        'player.restore_competition_eligibility',
        'player',
        target_player_id,
        normalized_reason,
        jsonb_build_object(
          'seasonId', target_season_id,
          'competitionEligible', false,
          'reason', existing_restriction.reason
        ),
        jsonb_build_object('seasonId', target_season_id, 'competitionEligible', true)
      );
    end if;
  else
    if found then
      if existing_restriction.reason is distinct from normalized_reason then
        update __LANE___private.player_competition_restrictions r
        set reason = normalized_reason,
            restricted_by = actor_user_id,
            restricted_at = now()
        where r.id = existing_restriction.id;

        insert into __LANE___private.audit_events(
          actor_user_id, action, entity_type, entity_id, reason, before_state, after_state
        ) values (
          actor_user_id,
          'player.update_competition_ineligibility',
          'player',
          target_player_id,
          normalized_reason,
          jsonb_build_object(
            'seasonId', target_season_id,
            'competitionEligible', false,
            'reason', existing_restriction.reason
          ),
          jsonb_build_object(
            'seasonId', target_season_id,
            'competitionEligible', false,
            'reason', normalized_reason
          )
        );
      end if;
    else
      insert into __LANE___private.player_competition_restrictions(
        season_id, player_id, reason, restricted_by
      ) values (
        target_season_id, target_player_id, normalized_reason, actor_user_id
      );

      insert into __LANE___private.audit_events(
        actor_user_id, action, entity_type, entity_id, reason, before_state, after_state
      ) values (
        actor_user_id,
        'player.mark_competition_ineligible',
        'player',
        target_player_id,
        normalized_reason,
        jsonb_build_object('seasonId', target_season_id, 'competitionEligible', true),
        jsonb_build_object(
          'seasonId', target_season_id,
          'competitionEligible', false,
          'reason', normalized_reason
        )
      );
    end if;
  end if;

  return query
  select
    target_player_id,
    target_season_id,
    not exists (
      select 1 from __LANE___private.player_competition_restrictions r
      where r.season_id = target_season_id
        and r.player_id = target_player_id
        and r.lifted_at is null
    ),
    (
      select r.reason
      from __LANE___private.player_competition_restrictions r
      where r.season_id = target_season_id
        and r.player_id = target_player_id
        and r.lifted_at is null
      limit 1
    );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_player_match_opening_discipline(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, opening_discipline text)
 RETURNS TABLE(player_match_id uuid, selected_opening_discipline text, selected_current_discipline text, opening_block_length integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
  has_team_score_racks boolean;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  if target_scoring_team_id is null then raise exception 'target_scoring_team_id is required'; end if;
  if opening_discipline not in ('8-ball', '9-ball') then
    raise exception 'opening_discipline must be 8-ball or 9-ball';
  end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;

  if target_match.status in ('finalized', 'corrected') then
    raise exception 'Player match is finalized';
  end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );

  select exists (
    select 1
    from __LANE___private.player_match_score_submissions s
    where s.player_match_id = target_player_match_id
      and jsonb_array_length(coalesce(s.racks, '[]'::jsonb)) > 0
  ) into has_team_score_racks;

  if has_team_score_racks or exists (
    select 1 from __LANE__.player_match_racks r
    where r.player_match_id = target_player_match_id
  ) then
    raise exception 'Opening discipline is locked after rack 1 is recorded';
  end if;

  update __LANE__.player_matches pm
  set opening_discipline = set_player_match_opening_discipline.opening_discipline,
      current_discipline = set_player_match_opening_discipline.opening_discipline
  where pm.id = target_player_match_id;

  insert into __LANE___private.audit_events(
    actor_user_id,
    action,
    entity_type,
    entity_id,
    before_state,
    after_state
  ) values (
    actor_user_id,
    'player_match.set_opening_discipline',
    'player_match',
    target_player_match_id,
    jsonb_build_object(
      'scoringTeamId', target_scoring_team_id,
      'trackerPlayerId', tracker_id,
      'openingDiscipline', target_match.opening_discipline
    ),
    jsonb_build_object(
      'scoringTeamId', target_scoring_team_id,
      'trackerPlayerId', tracker_id,
      'openingDiscipline', opening_discipline
    )
  );

  return query
  select
    target_player_match_id,
    opening_discipline,
    opening_discipline,
    target_match.opening_block_length;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.set_roster_availability(actor_user_id uuid, target_round_id uuid, availability_status text)
 RETURNS TABLE(season_id uuid, round_id uuid, team_id uuid, player_id uuid, status text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_round __LANE__.rounds%rowtype;
  actor_team_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;
  if availability_status not in ('available', 'unavailable', 'unsure') then
    raise exception 'availability_status must be available, unavailable, or unsure';
  end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before setting roster availability'; end if;

  select * into target_round
  from __LANE__.rounds r
  where r.id = target_round_id;
  if not found then raise exception 'Round not found'; end if;
  if target_round.scheduled_on is null then raise exception 'Round does not have a scheduled date'; end if;

  select tm.team_id into actor_team_id
  from __LANE__.team_memberships tm
  where tm.season_id = target_round.season_id
    and tm.player_id = actor_player_id
    and tm.ends_at is null
  order by tm.starts_at, tm.team_id
  limit 1;
  if not found then raise exception 'Active roster membership is required before setting availability'; end if;

  perform * from __LANE__.set_own_date_availability(
    actor_user_id,
    target_round.season_id,
    target_round.scheduled_on,
    availability_status
  );

  return query
  select
    target_round.season_id,
    target_round.id,
    actor_team_id,
    actor_player_id,
    pda.status,
    pda.updated_at
  from __LANE___private.player_date_availability pda
  where pda.season_id = target_round.season_id
    and pda.player_id = actor_player_id
    and pda.availability_date = target_round.scheduled_on;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.start_direct_conversation(actor_user_id uuid, target_season_id uuid, target_player_id uuid)
 RETURNS TABLE(conversation_id uuid, season_id uuid, season_name text, other_player_id uuid, other_display_name text, last_message_body text, last_message_at timestamp with time zone, unread_count bigint, can_send boolean, blocked_by_me boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player __LANE__.players%rowtype;
  target_player __LANE__.players%rowtype;
  saved_conversation __LANE__.direct_conversations%rowtype;
begin
  select p.* into actor_player
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player.id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  select p.* into target_player
  from __LANE__.players p
  where p.id = target_player_id;
  if target_player.id is null then raise exception 'Player not found'; end if;
  if target_player.id = actor_player.id then
    raise exception 'Cannot message yourself';
  end if;

  if not __LANE___private.is_active_season_participant(actor_player.id, target_season_id)
    or not __LANE___private.is_active_season_participant(target_player.id, target_season_id)
  then
    raise exception 'Both players must participate in the active season';
  end if;

  if exists (
    select 1
    from __LANE__.player_chat_blocks block
    where (
      block.blocker_player_id = actor_player.id
      and block.blocked_player_id = target_player.id
    ) or (
      block.blocker_player_id = target_player.id
      and block.blocked_player_id = actor_player.id
    )
  ) then
    raise exception 'Direct messages are blocked';
  end if;

  insert into __LANE__.direct_conversations (
    season_id, player_low_id, player_high_id, created_by_player_id
  ) values (
    target_season_id,
    least(actor_player.id, target_player.id),
    greatest(actor_player.id, target_player.id),
    actor_player.id
  )
  on conflict on constraint direct_conversations_season_id_player_low_id_player_high_id_key
  do update set season_id = excluded.season_id
  returning * into saved_conversation;

  return query
  select saved_conversation.id, saved_conversation.season_id, season.name,
    target_player.id, target_player.display_name, null::text, null::timestamptz,
    0::bigint, true, false
  from __LANE__.seasons season
  where season.id = saved_conversation.season_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.start_season_playoffs(target_season_id uuid, actor_user_id uuid)
 RETURNS TABLE(round_id uuid, semifinal_one_id uuid, semifinal_two_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  existing_round_id uuid;
  seed_team_ids uuid[];
  created_round_id uuid;
  first_match_id uuid;
  second_match_id uuid;
  regular_round_count integer;
  team_count integer;
  completed_team_count integer;
begin
  if not exists (
    select 1 from __LANE___private.league_admins la where la.user_id = actor_user_id
  ) then
    raise exception 'Actor is not a league admin';
  end if;

  select r.id into existing_round_id
  from __LANE__.rounds r
  where r.season_id = target_season_id and r.stage = 'semifinal'
  order by r.round_number
  limit 1;

  if existing_round_id is not null then
    return query
      select existing_round_id,
             (select tm.id from __LANE__.team_matches tm where tm.round_id = existing_round_id order by tm.table_number limit 1),
             (select tm.id from __LANE__.team_matches tm where tm.round_id = existing_round_id order by tm.table_number offset 1 limit 1);
    return;
  end if;

  if not exists (select 1 from __LANE__.seasons s where s.id = target_season_id) then
    raise exception 'Season not found';
  end if;

  select count(*)::integer into regular_round_count
  from __LANE__.rounds r
  where r.season_id = target_season_id and r.stage = 'regular';
  if regular_round_count <> 7 then
    raise exception 'Season must have exactly seven regular rounds before playoffs';
  end if;

  select count(*)::integer into team_count
  from __LANE__.teams t where t.season_id = target_season_id;
  if team_count <> 8 then
    raise exception 'Season must have exactly eight teams before playoffs';
  end if;

  select count(*)::integer into completed_team_count
  from __LANE__.list_team_standings(target_season_id) standings
  where standings.games_played = 7 and standings.maximum_matches = 7;
  if completed_team_count <> 8 then
    raise exception 'All seven regular-season matchups must be complete before playoffs';
  end if;

  select array_agg(seeded.team_id order by seeded.seed_position)
  into seed_team_ids
  from (
    select standings.team_id,
           row_number() over (
             order by standings.standings_rank,
                      standings.standing_points desc,
                      standings.match_points desc,
                      standings.point_differential desc,
                      standings.team_name
           )::integer as seed_position
    from __LANE__.list_team_standings(target_season_id) standings
    order by standings.standings_rank,
             standings.standing_points desc,
             standings.match_points desc,
             standings.point_differential desc,
             standings.team_name
    limit 4
  ) seeded;

  if coalesce(array_length(seed_team_ids, 1), 0) <> 4 then
    raise exception 'Four playoff seeds are required';
  end if;

  insert into __LANE__.rounds (season_id, round_number, stage, status)
  values (target_season_id, 8, 'semifinal', 'scheduled')
  returning id into created_round_id;

  insert into __LANE__.team_matches (season_id, round_id, table_number, team_a_id, team_b_id, status)
  values (target_season_id, created_round_id, 1, seed_team_ids[1], seed_team_ids[4], 'scheduled')
  returning id into first_match_id;

  insert into __LANE__.team_matches (season_id, round_id, table_number, team_a_id, team_b_id, status)
  values (target_season_id, created_round_id, 2, seed_team_ids[2], seed_team_ids[3], 'scheduled')
  returning id into second_match_id;

  update __LANE__.seasons
  set status = 'playoffs', updated_at = now()
  where id = target_season_id;

  return query select created_round_id, first_match_id, second_match_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.submit_postseason_lineup(actor_user_id uuid, target_team_match_id uuid, target_team_id uuid, lineup_player_ids uuid[], anchor_player_id uuid)
 RETURNS TABLE(lineup_id uuid, team_match_id uuid, team_id uuid, slot_number integer, player_id uuid, locked_anchor_player_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_match __LANE__.team_matches%rowtype;
  target_round __LANE__.rounds%rowtype;
  saved_lineup_id uuid;
  qualifying_four_count integer;
  qualifying_three_count integer;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_match_id is null then raise exception 'target_team_match_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if coalesce(array_length(lineup_player_ids, 1), 0) <> 4 then
    raise exception 'Postseason lineup requires exactly four players';
  end if;
  if anchor_player_id is null then raise exception 'Postseason anchor is required'; end if;

  select * into target_match
  from __LANE__.team_matches tm
  where tm.id = target_team_match_id
  for update;
  if not found then raise exception 'Team matchup not found'; end if;

  select * into target_round
  from __LANE__.rounds r
  where r.id = target_match.round_id;
  if target_round.stage not in ('semifinal', 'championship') then
    raise exception 'Postseason lineup is only valid for a semifinal or championship';
  end if;
  if target_team_id not in (target_match.team_a_id, target_match.team_b_id) then
    raise exception 'Team is not part of this postseason matchup';
  end if;

  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then raise exception 'Player profile is required'; end if;
  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = target_team_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'Only the active captain can submit a postseason lineup';
  end if;

  if exists (
    select 1 from __LANE___private.team_lineups tl
    where tl.team_match_id = target_team_match_id
      and tl.team_id = target_team_id
  ) then
    raise exception 'Postseason lineup and anchor are locked after submission';
  end if;

  if (select count(distinct p) from unnest(lineup_player_ids) p) <> 4 then
    raise exception 'Postseason lineup players must be unique';
  end if;
  if not (anchor_player_id = any(lineup_player_ids)) then
    raise exception 'Postseason anchor must be selected from the submitted lineup';
  end if;

  if exists (
    select 1
    from unnest(lineup_player_ids) pid
    where not exists (
      select 1 from __LANE__.team_memberships tm
      where tm.season_id = target_match.season_id
        and tm.team_id = target_team_id
        and tm.player_id = pid
        and tm.ends_at is null
    )
  ) then
    raise exception 'Every postseason player must be an active member of the team';
  end if;

  with player_counts as (
    select pid.player_id,
      (
        select count(*)::integer
        from __LANE__.player_matches pm
        join __LANE__.rounds r on r.id = pm.round_id
        where pm.season_id = target_match.season_id
          and r.stage = 'regular'
          and pm.status in ('finalized', 'corrected')
          and (
            (pm.team_a_id = target_team_id and pm.player_a_id = pid.player_id)
            or (pm.team_b_id = target_team_id and pm.player_b_id = pid.player_id)
          )
      ) as team_matches_played
    from unnest(lineup_player_ids) as pid(player_id)
  )
  select count(*) filter (where team_matches_played >= 4)::integer,
         count(*) filter (where team_matches_played >= 3)::integer
  into qualifying_four_count, qualifying_three_count
  from player_counts;

  if qualifying_four_count < 3 or qualifying_three_count < 4 then
    raise exception 'Postseason lineup requires three players with 4+ team matches and a fourth with 3+';
  end if;

  insert into __LANE___private.team_lineups(
    season_id, round_id, team_match_id, team_id, submitted_by, anchor_player_id
  ) values (
    target_match.season_id, target_match.round_id, target_team_match_id,
    target_team_id, actor_user_id, anchor_player_id
  ) returning __LANE___private.team_lineups.id into saved_lineup_id;

  insert into __LANE___private.team_lineup_slots(
    lineup_id, season_id, round_id, team_id, slot_number, player_id, participation_type
  )
  select saved_lineup_id, target_match.season_id, target_match.round_id,
         target_team_id, lineup.ordinality::integer, lineup.player_id, 'roster'
  from unnest(lineup_player_ids) with ordinality as lineup(player_id, ordinality);

  return query
  select tl.id, tl.team_match_id, tl.team_id, tls.slot_number, tls.player_id, tl.anchor_player_id
  from __LANE___private.team_lineups tl
  join __LANE___private.team_lineup_slots tls on tls.lineup_id = tl.id
  where tl.id = saved_lineup_id
  order by tls.slot_number;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.submit_sandbox_feedback(actor_user_id uuid, feedback_surface text, feedback_path text, feedback_context jsonb, feedback_comment text)
 RETURNS TABLE(id uuid, surface text, page_path text, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_path text := btrim(feedback_path);
  normalized_comment text := btrim(feedback_comment);
  inserted_id uuid;
begin
  if actor_user_id is null or not exists (
    select 1 from auth.users u where u.id = actor_user_id
  ) then
    raise exception 'Authenticated user is required';
  end if;
  if feedback_surface not in ('demo', 'player', 'captain') then
    raise exception 'Invalid sandbox feedback surface';
  end if;
  if normalized_path is null or char_length(normalized_path) not between 1 and 160 then
    raise exception 'Feedback path is required and must be 160 characters or fewer';
  end if;
  if normalized_comment is null or char_length(normalized_comment) not between 1 and 2000 then
    raise exception 'Feedback comment is required and must be 2000 characters or fewer';
  end if;
  if feedback_context is null or jsonb_typeof(feedback_context) <> 'object' then
    raise exception 'Feedback context must be an object';
  end if;

  insert into __LANE___private.sandbox_feedback(
    actor_user_id,
    surface,
    page_path,
    context,
    comment
  ) values (
    actor_user_id,
    feedback_surface,
    normalized_path,
    feedback_context,
    normalized_comment
  )
  returning __LANE___private.sandbox_feedback.id into inserted_id;

  return query
  select sf.id, sf.surface, sf.page_path, sf.status, sf.created_at
  from __LANE___private.sandbox_feedback sf
  where sf.id = inserted_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.submit_team_application(actor_user_id uuid, target_season_id uuid, proposed_team_name text)
 RETURNS TABLE(id uuid, season_id uuid, status text, team_name text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  normalized_name text;
  inserted_id uuid;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_season_id is null then raise exception 'target_season_id is required'; end if;
  normalized_name := btrim(proposed_team_name);
  if normalized_name is null or char_length(normalized_name) not between 1 and 80 then
    raise exception 'proposed_team_name must be 80 characters or fewer';
  end if;

  if not exists (
    select 1 from __LANE__.seasons s
    where s.id = target_season_id and s.status = 'registration'
  ) then
    raise exception 'Season is not open for team applications';
  end if;

  perform __LANE___private.expire_season_team_registration(target_season_id);

  select p.id into actor_player_id
  from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before applying for a team'; end if;

  if exists (
    select 1 from __LANE__.teams t
    where t.season_id = target_season_id
      and lower(btrim(t.name)) = lower(normalized_name)
  ) or exists (
    select 1
    from __LANE___private.season_team_slots sts
    join __LANE__.teams source_team on source_team.id = sts.source_team_id
    where sts.season_id = target_season_id
      and sts.status in ('reserved', 'transferred')
      and lower(btrim(source_team.name)) = lower(normalized_name)
  ) then
    raise exception 'That team name is already reserved for this season';
  end if;

  if exists (
    select 1 from __LANE__.team_memberships tm
    where tm.season_id = target_season_id
      and tm.player_id = actor_player_id
      and tm.role = 'captain'
      and tm.ends_at is null
  ) then
    raise exception 'You already captain a team in this season';
  end if;

  insert into __LANE___private.team_applications(
    season_id, applicant_player_id, proposed_team_name
  ) values (
    target_season_id, actor_player_id, normalized_name
  ) returning __LANE___private.team_applications.id into inserted_id;

  return query
  select ta.id, ta.season_id, ta.status, ta.proposed_team_name, ta.submitted_at
  from __LANE___private.team_applications ta where ta.id = inserted_id;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.submit_team_lineup(actor_user_id uuid, target_team_id uuid, target_round_id uuid, lineup_slots jsonb)
 RETURNS TABLE(lineup_id uuid, season_id uuid, round_id uuid, team_match_id uuid, team_id uuid, slot_number integer, player_id uuid, participation_type text, submitted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
  target_round __LANE__.rounds%rowtype;
  target_match __LANE__.team_matches%rowtype;
  saved_lineup_id uuid;
  saved_submitted_at timestamptz;
begin
  if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
  if target_team_id is null then raise exception 'target_team_id is required'; end if;
  if target_round_id is null then raise exception 'target_round_id is required'; end if;
  if lineup_slots is null or jsonb_typeof(lineup_slots) is distinct from 'array' then raise exception 'lineup_slots must be an array'; end if;
  if jsonb_array_length(lineup_slots) > 3 then raise exception 'Lineup cannot contain more than three slots'; end if;

  select * into target_round from __LANE__.rounds r where r.id = target_round_id;
  if not found then raise exception 'Round not found'; end if;
  if target_round.stage <> 'regular' then raise exception 'Regular lineup is only valid for a regular-season round'; end if;
  if target_round.lineup_deadline_at is not null and now() > target_round.lineup_deadline_at then raise exception 'Lineup deadline has passed'; end if;

  select * into target_match
  from __LANE__.team_matches tm
  where tm.round_id = target_round_id and (tm.team_a_id = target_team_id or tm.team_b_id = target_team_id)
  for update;
  if not found then raise exception 'Team is not scheduled for target round'; end if;

  select p.id into actor_player_id from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required before submitting a lineup'; end if;
  if not exists (
    select 1 from __LANE__.team_memberships tm
    where tm.team_id = target_team_id and tm.player_id = actor_player_id and tm.role = 'captain' and tm.ends_at is null
  ) then raise exception 'Only the active captain can submit a lineup'; end if;

  if exists (
    select 1 from __LANE___private.team_lineups existing_lineup
    where existing_lineup.team_match_id = target_match.id and existing_lineup.team_id = target_team_id
  ) then raise exception 'Lineup is locked after submission'; end if;

  if exists (
    select 1 from (
      select coalesce((slot_item.value ->> 'slotNumber')::integer, slot_item.ordinality::integer) as slot_number
      from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
    ) parsed_slots where parsed_slots.slot_number < 1 or parsed_slots.slot_number > 3
  ) then raise exception 'Lineup slot numbers must be between 1 and 3'; end if;

  if exists (
    select 1 from (
      select coalesce((slot_item.value ->> 'slotNumber')::integer, slot_item.ordinality::integer) as slot_number
      from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
    ) parsed_slots group by parsed_slots.slot_number having count(*) > 1
  ) then raise exception 'Lineup slot numbers must be unique'; end if;

  if exists (
    select 1 from (
      select nullif(slot_item.value ->> 'playerId', '')::uuid as player_id
      from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
      where nullif(slot_item.value ->> 'playerId', '') is not null
    ) parsed_slots group by parsed_slots.player_id having count(*) > 1
  ) then raise exception 'Lineup players must be unique'; end if;

  if exists (
    select 1 from (
      select nullif(slot_item.value ->> 'playerId', '')::uuid as player_id
      from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
      where nullif(slot_item.value ->> 'playerId', '') is not null
    ) parsed_slots
    where not exists (
      select 1 from __LANE___private.payment_status ps
      where ps.season_id = target_match.season_id and ps.player_id = parsed_slots.player_id and ps.status in ('paid', 'waived')
    )
  ) then raise exception 'Every lineup player must be paid or waived before playing'; end if;

  if exists (
    select 1 from (
      select nullif(slot_item.value ->> 'playerId', '')::uuid as player_id
      from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
      where nullif(slot_item.value ->> 'playerId', '') is not null
    ) parsed_slots
    where not (
      exists (
        select 1 from __LANE__.team_memberships tm
        where tm.team_id = target_team_id and tm.season_id = target_match.season_id
          and tm.player_id = parsed_slots.player_id and tm.ends_at is null
      )
      or exists (
        select 1 from __LANE___private.free_agent_availability fa
        join __LANE__.season_players sp on sp.season_id = fa.season_id and sp.player_id = fa.player_id
        where fa.season_id = target_match.season_id and fa.round_id = target_round_id
          and fa.player_id = parsed_slots.player_id and fa.status = 'available' and sp.status = 'active'
      )
      or exists (
        select 1 from __LANE___private.roster_availability ra
        where ra.season_id = target_match.season_id and ra.round_id = target_round_id
          and ra.player_id = parsed_slots.player_id and ra.status = 'available'
          and exists (
            select 1 from __LANE__.team_memberships other_tm
            where other_tm.season_id = target_match.season_id
              and other_tm.player_id = parsed_slots.player_id and other_tm.ends_at is null
          )
      )
    )
  ) then raise exception 'Lineup player is not eligible for this team round'; end if;

  insert into __LANE___private.team_lineups (season_id, round_id, team_match_id, team_id, submitted_by)
  values (target_match.season_id, target_round_id, target_match.id, target_team_id, actor_user_id)
  on conflict on constraint team_lineups_team_match_id_team_id_key do update
    set submitted_by = excluded.submitted_by, submitted_at = now(), updated_at = now()
  returning team_lineups.id, team_lineups.submitted_at into saved_lineup_id, saved_submitted_at;

  delete from __LANE___private.team_lineup_slots tls where tls.lineup_id = saved_lineup_id;

  insert into __LANE___private.team_lineup_slots (lineup_id, season_id, round_id, team_id, slot_number, player_id, participation_type)
  select saved_lineup_id, target_match.season_id, target_round_id, target_team_id, slot_numbers.slot_number, parsed_slots.player_id,
    case
      when parsed_slots.player_id is null then 'forfeit'
      when exists (
        select 1 from __LANE__.team_memberships tm
        where tm.team_id = target_team_id and tm.season_id = target_match.season_id
          and tm.player_id = parsed_slots.player_id and tm.ends_at is null
      ) then 'roster'
      else 'free_agent'
    end
  from generate_series(1, 3) as slot_numbers(slot_number)
  left join (
    select coalesce((slot_item.value ->> 'slotNumber')::integer, slot_item.ordinality::integer) as slot_number,
      nullif(slot_item.value ->> 'playerId', '')::uuid as player_id
    from jsonb_array_elements(lineup_slots) with ordinality as slot_item(value, ordinality)
  ) parsed_slots on parsed_slots.slot_number = slot_numbers.slot_number
  order by slot_numbers.slot_number;

  return query
  select tl.id, tl.season_id, tl.round_id, tl.team_match_id, tl.team_id,
    tls.slot_number, tls.player_id, tls.participation_type, tl.submitted_at
  from __LANE___private.team_lineups tl
  join __LANE___private.team_lineup_slots tls on tls.lineup_id = tl.id
  where tl.id = saved_lineup_id
  order by tls.slot_number;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.unblock_player_chat(actor_user_id uuid, target_player_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p
  where p.user_id = actor_user_id;
  if actor_player_id is null then
    raise exception 'Player profile is required before using chat';
  end if;

  delete from __LANE__.player_chat_blocks block
  where block.blocker_player_id = actor_player_id
    and block.blocked_player_id = target_player_id;
  return found;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.undo_player_match_rack(actor_user_id uuid, target_player_match_id uuid)
 RETURNS TABLE(player_match_id uuid, undone_rack_number integer, undone_winner_side text, score_a integer, score_b integer, current_discipline text, winner_side text, winner_player_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_match __LANE__.player_matches%rowtype; undone_rack __LANE__.player_match_racks%rowtype; updated_match __LANE__.player_matches%rowtype; remaining_rack_count integer; next_score_a integer; next_score_b integer; next_discipline text;
begin
if actor_user_id is null then raise exception 'actor_user_id is required'; end if;
if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update;
if not found then raise exception 'Player match not found'; end if;
if target_match.status in ('finalized','corrected') then raise exception 'Player match is finalized'; end if;
if not __LANE___private.can_score_player_match(actor_user_id,target_match) then raise exception 'Only match players or active team captains can undo racks'; end if;
select * into undone_rack from __LANE__.player_match_racks pmr where pmr.player_match_id=target_player_match_id order by pmr.rack_number desc limit 1 for update;
if not found then raise exception 'Player match has no racks to undo'; end if;
delete from __LANE__.player_match_racks pmr where pmr.id=undone_rack.id;
select count(*)::integer,count(*) filter(where pmr.winner_side='A')::integer,count(*) filter(where pmr.winner_side='B')::integer into remaining_rack_count,next_score_a,next_score_b from __LANE__.player_match_racks pmr where pmr.player_match_id=target_player_match_id;
next_discipline:=case when remaining_rack_count>=target_match.opening_block_length then case when target_match.opening_discipline='8-ball' then '9-ball' else '8-ball' end else target_match.opening_discipline end;
update __LANE__.player_matches set score_a=next_score_a,score_b=next_score_b,current_discipline=next_discipline,winner_side=null,winner_player_id=null,status=case when remaining_rack_count=0 then 'scheduled' else 'in_progress' end where player_matches.id=target_player_match_id returning * into updated_match;
insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.rack_undo','player_match',target_player_match_id,jsonb_build_object('match',to_jsonb(target_match),'removedRack',to_jsonb(undone_rack)),to_jsonb(updated_match));
return query select updated_match.id,undone_rack.rack_number,undone_rack.winner_side,updated_match.score_a,updated_match.score_b,updated_match.current_discipline,updated_match.winner_side,updated_match.winner_player_id,updated_match.status;
end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.undo_player_match_score_rack(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, undone_rack_number integer, score_a integer, score_b integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare target_match __LANE__.player_matches%rowtype; tracker_id uuid; submission __LANE___private.player_match_score_submissions%rowtype; rack_count integer; next_racks jsonb; next_score_a integer; next_score_b integer; begin select * into target_match from __LANE__.player_matches pm where pm.id=target_player_match_id for update; if not found then raise exception 'Player match not found'; end if; if target_match.status in ('finalized','corrected') then raise exception 'Player match is finalized'; end if; tracker_id:=__LANE___private.match_tracker_for_scoring_team(actor_user_id,target_match,target_scoring_team_id); select * into submission from __LANE___private.player_match_score_submissions s where s.player_match_id=target_player_match_id and s.tracker_player_id=tracker_id for update; if not found or jsonb_array_length(submission.racks)=0 then raise exception 'Score record has no racks to undo'; end if; rack_count:=jsonb_array_length(submission.racks); next_racks:=submission.racks-(rack_count-1); select count(*) filter(where elem->>'winnerSide'='A')::integer,count(*) filter(where elem->>'winnerSide'='B')::integer into next_score_a,next_score_b from jsonb_array_elements(next_racks) elem; update __LANE___private.player_match_score_submissions set racks=next_racks,confirmed_at=null,updated_at=now() where id=submission.id; insert into __LANE___private.audit_events(actor_user_id,action,entity_type,entity_id,before_state,after_state) values(actor_user_id,'player_match.team_score_rack_undo','player_match',target_player_match_id,jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id,'racks',submission.racks),jsonb_build_object('scoringTeamId',target_scoring_team_id,'trackerPlayerId',tracker_id,'racks',next_racks)); return query select target_player_match_id,target_scoring_team_id,tracker_id,rack_count,next_score_a,next_score_b; end; $function$;


CREATE OR REPLACE FUNCTION __LANE__.undo_player_match_score_rack_checked(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, expected_racks jsonb)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, undone_rack_number integer, score_a integer, score_b integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
begin
  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(
    actor_user_id,
    target_match,
    target_scoring_team_id
  );
  perform __LANE___private.assert_expected_score_history(
    target_player_match_id,
    tracker_id,
    expected_racks
  );

  return query
  select * from __LANE__.undo_player_match_score_rack(
    actor_user_id,
    target_player_match_id,
    target_scoring_team_id
  );
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.update_player_match_score_rack(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, target_rack_number integer, rack_winner_side text)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, discipline text, previous_winner_side text, winner_side text, score_a integer, score_b integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_match __LANE__.player_matches%rowtype;
  tracker_id uuid;
  submission __LANE___private.player_match_score_submissions%rowtype;
  rack_count integer;
  existing_rack jsonb;
  previous_winner text;
  rack_discipline text;
  next_racks jsonb;
  next_score_a integer;
  next_score_b integer;
begin
  if target_player_match_id is null then raise exception 'target_player_match_id is required'; end if;
  if target_rack_number is null or target_rack_number < 1 then raise exception 'target_rack_number must be a positive integer'; end if;
  if rack_winner_side not in ('A', 'B') then raise exception 'rack_winner_side must be A or B'; end if;

  select * into target_match
  from __LANE__.player_matches pm
  where pm.id = target_player_match_id
  for update;
  if not found then raise exception 'Player match not found'; end if;
  if target_match.status in ('finalized', 'corrected') then raise exception 'Player match is finalized'; end if;

  tracker_id := __LANE___private.match_tracker_for_scoring_team(actor_user_id, target_match, target_scoring_team_id);

  select * into submission
  from __LANE___private.player_match_score_submissions s
  where s.player_match_id = target_player_match_id
    and s.tracker_player_id = tracker_id
  for update;

  if not found then raise exception 'Score record is empty'; end if;
  rack_count := jsonb_array_length(coalesce(submission.racks, '[]'::jsonb));
  if target_rack_number > rack_count then raise exception 'Rack is not present in this team score record'; end if;

  existing_rack := submission.racks -> (target_rack_number - 1);
  previous_winner := existing_rack ->> 'winnerSide';
  rack_discipline := existing_rack ->> 'discipline';
  if previous_winner not in ('A', 'B') or rack_discipline not in ('8-ball', '9-ball') then
    raise exception 'Rack record is invalid';
  end if;

  if previous_winner = rack_winner_side then
    select
      count(*) filter (where elem ->> 'winnerSide' = 'A')::integer,
      count(*) filter (where elem ->> 'winnerSide' = 'B')::integer
    into next_score_a, next_score_b
    from jsonb_array_elements(submission.racks) elem;

    return query select target_player_match_id, target_scoring_team_id, tracker_id,
      target_rack_number, rack_discipline, previous_winner, rack_winner_side,
      next_score_a, next_score_b;
    return;
  end if;

  next_racks := jsonb_set(
    submission.racks,
    array[(target_rack_number - 1)::text, 'winnerSide'],
    to_jsonb(rack_winner_side),
    false
  );

  select
    count(*) filter (where elem ->> 'winnerSide' = 'A')::integer,
    count(*) filter (where elem ->> 'winnerSide' = 'B')::integer
  into next_score_a, next_score_b
  from jsonb_array_elements(next_racks) elem;

  update __LANE___private.player_match_score_submissions
  set racks = next_racks,
      confirmed_at = null,
      updated_at = now()
  where id = submission.id;

  insert into __LANE___private.audit_events(actor_user_id, action, entity_type, entity_id, before_state, after_state)
  values (
    actor_user_id,
    'player_match.team_score_rack_edit',
    'player_match',
    target_player_match_id,
    jsonb_build_object(
      'scoringTeamId', target_scoring_team_id,
      'trackerPlayerId', tracker_id,
      'rackNumber', target_rack_number,
      'discipline', rack_discipline,
      'winnerSide', previous_winner,
      'racks', submission.racks
    ),
    jsonb_build_object(
      'scoringTeamId', target_scoring_team_id,
      'trackerPlayerId', tracker_id,
      'rackNumber', target_rack_number,
      'discipline', rack_discipline,
      'winnerSide', rack_winner_side,
      'racks', next_racks
    )
  );

  return query select target_player_match_id, target_scoring_team_id, tracker_id,
    target_rack_number, rack_discipline, previous_winner, rack_winner_side,
    next_score_a, next_score_b;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.update_player_match_score_rack_checked(actor_user_id uuid, target_player_match_id uuid, target_scoring_team_id uuid, target_rack_number integer, rack_winner_side text, expected_racks jsonb)
 RETURNS TABLE(player_match_id uuid, scoring_team_id uuid, tracker_player_id uuid, rack_number integer, discipline text, previous_winner_side text, winner_side text, score_a integer, score_b integer, record_complete boolean)
