$function$;


CREATE OR REPLACE FUNCTION __LANE__.upsert_player_profile(actor_user_id uuid, profile_display_name text)
 RETURNS TABLE(id uuid, user_id uuid, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  normalized_display_name text;
begin
  if actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  normalized_display_name := btrim(profile_display_name);
  if normalized_display_name is null or char_length(normalized_display_name) = 0 then
    raise exception 'display_name is required';
  end if;

  if char_length(normalized_display_name) > 80 then
    raise exception 'display_name must be 80 characters or fewer';
  end if;

  return query
  insert into __LANE__.players (
    user_id,
    display_name
  ) values (
    actor_user_id,
    normalized_display_name
  )
  on conflict on constraint players_user_id_key do update
    set display_name = excluded.display_name,
        updated_at = now()
  returning
    players.id,
    players.user_id,
    players.display_name;
end;
$function$;


CREATE OR REPLACE FUNCTION __LANE__.withdraw_team_application(actor_user_id uuid, target_application_id uuid)
 RETURNS TABLE(id uuid, status text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor_player_id uuid;
begin
  select p.id into actor_player_id
  from __LANE__.players p where p.user_id = actor_user_id;
  if not found then raise exception 'Player profile is required'; end if;

  update __LANE___private.team_applications ta
  set status = 'withdrawn', updated_at = now()
  where ta.id = target_application_id
    and ta.applicant_player_id = actor_player_id
    and ta.status in ('applied', 'deferred');

  if not found then raise exception 'Team application cannot be withdrawn'; end if;

  return query
  select ta.id, ta.status, ta.updated_at
  from __LANE___private.team_applications ta where ta.id = target_application_id;
end;
$function$;

$lane_template$;
  table_count integer;
  private_table_count integer;
  function_count integer;
  policy_count integer;
  trigger_count integer;
begin
  foreach lane in array array['jfl', 'dru', 'gamma']
  loop
    if exists (select 1 from pg_namespace where nspname in (lane, lane || '_private')) then
      raise exception 'Refusing to overwrite existing schema for lane %', lane;
    end if;

    execute replace(template, '__LANE__', lane);

    select count(*) into table_count
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = lane and c.relkind in ('r', 'p');
    select count(*) into private_table_count
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = lane || '_private' and c.relkind in ('r', 'p');
    select count(*) into function_count
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in (lane, lane || '_private');
    select count(*) into policy_count from pg_policies where schemaname = lane;
    select count(*) into trigger_count
    from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace
    where not t.tgisinternal and n.nspname in (lane, lane || '_private');

    if table_count <> 26 or private_table_count <> 20 or function_count <> 165
       or policy_count <> 32 or trigger_count <> 19 then
      raise exception 'Lane % shape mismatch: public tables %, private tables %, functions %, policies %, triggers %',
        lane, table_count, private_table_count, function_count, policy_count, trigger_count;
    end if;
  end loop;
end;
$provision$;

do $actors$
declare
  lane text;
  actor_email text;
  actor_user_id uuid;
  actor_player_id uuid;
begin
  for lane, actor_email in
    select * from (values
      ('jfl', 'jfl-actor@fremontderby.com'),
      ('dru', 'dru-actor@fremontderby.com')
    ) as actors(lane, actor_email)
  loop
    select id into actor_user_id from auth.users where lower(email) = lower(actor_email);
    if actor_user_id is null then
      raise exception 'Required staging auth user % does not exist', actor_email;
    end if;
    execute format(
      'insert into %I.players (user_id, display_name) values ($1, $2)',
      lane
    ) using actor_user_id, upper(lane) || ' Test Actor';
    execute format(
      'insert into %I.league_admins (user_id, note) values ($1, $2)',
      lane || '_private'
    ) using actor_user_id, 'Shared staging lane test actor';
  end loop;
end;
$actors$;

alter role authenticator set pgrst.db_schemas =
  'public,graphql_public,jfl,dru,gamma';
notify pgrst, 'reload config';
